window.HARDTRP.receive("194458",[[194460,"2026-09-06T19:26:24",9,"Начало темы.\n\nHard Master — Дм этой темы.",194458,null],[194462,"2026-09-06T19:28:19",9,"\"Общее о игре\"\n\n🎮Игроки, начальный состав: @PaIIasCat @dunchev @lady_godzilla @OIK77GK \n\n🕰Время: Ориэнтируемся на 10.00 до 17.00 по мск. Постараюсь вести активно в это время когда не занят, в остальное по ситуации.\n\n🗣Флуд: не оч люблю его, го если не по делу начнем усиленно что-то обсуждать в основу во флуд или обсуждение квестов.\n\n📚Опыт: после продолжительного выдаётся опыт.\n\n🔝Инициатива. Инициатива, импровизация и всё такое приветствуется в логических рамках. Квест о инициативе.\n\nЕсли сцена себя исчерпала или вы идете куда то укажите на это внеигровым чтобы я не ждал и не думал что вы просто заняты.\n\nМожет дополнится.\n\nPs: Пока что всё приятной нам игры! 🥳🎉",194458,null],[194463,"2026-09-06T19:28:50",9,"🎺🪉ВДОХНОВЕНИЯ🪇🥁\n\n— Люпен 1д4\n\n— Рен 3д4\n\n— Лют Виндривер 0д4\n\n— Вакс 1д4\n\nЭти вдохновения — это доп кубы. Вы можете докинуть эти д4 к любому броску, будь то атака, урон от атаки, спас, проверка и так далее, но они тратятся, тратьте с умом. На один бросок — один куб. (Говорите когда их добавляете)",194458,null],[194464,"2026-09-06T19:28:58",9,"Запас",194458,null],[194465,"2026-09-06T19:29:07",9,"ХХХХХХХХХХХХХХХХХХХХХХХХХХ",194458,null],[194468,"2026-09-06T19:30:01",9,"//Представьте своих персонажей в нескольких словах. Имя, артик и ссылочка",194458,null],[194471,"2026-09-06T19:30:32",9,"Селение \"Дрейгхолт\" вверх по реке что стекает дальше к землям близ Веспирали, но деревенька ещё в Вальдхейме. Здесь некротические облака виднеются едва едва, но при этом нежить бывает захаживает, правда от монстров проблем и то больше.\n\nНочью сторож слышал свист, как от свистка, а утром часть могил была разрыта словно изнутри. Мертвецы повылазили и пошли куда-то.\n\nНарод паникует. Требуется помощь приключенцев разобраться что черт возьми тут происходит!?\n\nПлотют 200 золотых, всей деревгей скидались.",194458,null],[194620,"2026-09-06T20:14:17",18,"Лют \"Лютый\" Виндривер. Уроженец ветровальных лесов предгорья Северной Элазии...Продан в рабство родителями в возрасте 6 лет, \"рекрутирован\" в наëмную роту в 20, получил свободу в 45...Старый солдат оттрубивший четверть века в наёмных ротах, без семьи, почти без друзей, на старости лет решивший осесть в тихом местечке...",194458,null],[194742,"2026-09-06T20:33:08",18,"https://t.me/c/3239766844/6570",194458,null],[195221,"2026-09-07T08:51:56",22,"Вакс Стальная глотка.\nАраакокра-козодой, певица с очень специфичным голосом.\n\nКоллекционирует \"мёртвые языки\" и последние крики умирающих тварей, которые выступают в качестве аккомпанимента на ее концертах.\nhttps://t.me/c/3239766844/6097/6099",194458,null],[195228,"2026-09-07T09:20:40",20,"Рен\n\nНачинающий ученик мага, пацан на вид лет 14. Сейчас сейчас одетый не в такую чистую и пафосную зелёную мантию, а в простую одежду и дорожный плащ.\n\nhttps://t.me/c/3239766844/4762",194458,null],[195232,"2026-09-07T09:25:18",20,"/можно было закупку снаряжения перед квестом сделать в лагере?",194458,null],[195237,"2026-09-07T09:35:15",9,"// @dunchev ток твой остался, ты же идёшь?",194458,null],[195252,"2026-09-07T09:52:57",17,"/ делаю",194458,null],[195253,"2026-09-07T09:56:46",17,"Люпен худой жилистый пройдоха. На вид около 30 лет. Одет в обычную одежду и плащ из шкуры вепря. Лук у него странный напоминает плетёный, как плетут корзины.\n\nhttps://t.me/c/3239766844/4571",194458,null],[195300,"2026-09-07T10:23:49",9,"//О, все в сборе",194458,null],[195325,"2026-09-07T10:40:47",9,"*Прекрасный летний день, повозка фермера что ездил в город полна покупок для своих односельчан. А ещё он везёт из города четверых наёмников что отозвались на дело.*\n\n*Беда у них приключилась, знаш какая. Мертвые встали и ушли, куда и почему сразу не скажет никто, вот только моторошно все это, люди боятся, надо разобраться.*\n\n*Фермер поправил соломенную шляпу и краем глаза взглянул на своих пасажиров. Воин привычный глазу, стражник какой-то в отставке, добро выглядит. Охотник возможно со своим пацаном, хотя не, красные волосы... а может мамины? И птичка, да не простая, на ножки лучше не заглядываться на орков, фермер не мог решить она страшная или красивая. Быстро убрав взгляд продолжил путь.*\n\nФермер — По часика да мы будем в Дрейгхрлте. — *Вез он вас по дороге, немногоболотистая местность, много мхов и трав, редкие деревья близ виднеющейся вдали деревни-заставы. Сегодня было пасмурно и шел мелкий дождь, почти не ощутимый но было зябко.*\n\n*В повозке пахло сыром, хлебом и маслом. Что вез фермер тем и пахло.*\n\n*Путники согласились на это дело по разным причинам, может звучало интересно, может деньги, а может... а может они сами раскажут что здесь забыли? Фермер еще какое-то время будет везти их на своей повощке, как раз самое время познакомится, ведь прийдется решать общее дело, оно всяко лучше в команде чем порознь.*\n\n// https://pin.it/6JnHPSI3f",194471,null],[195326,"2026-09-07T10:41:13",9,"// @dunchev @PaIIasCat @lady_godzilla @OIK77GK начал",195325,null],[195328,"2026-09-07T10:42:41",20,"/до квеста была возможность закупится и фамильяра призвать? 👉👈",195326,null],[195329,"2026-09-07T10:43:39",9,"//Го, закупайтесь. Ты же устаканила лист заклинателя опыт и прочее? А то не помню чтобы из анкеты удалял свои соо)",195328,null],[195330,"2026-09-07T10:49:21",22,"Вакс достала свой барабан и набивала лёгкую мелодию.\n\n- Никто не против лёгкой музыки в дороге? Так и время получится скоротать быстрее.\n\nВакс мелодично постукивала по барабану.\n\n- А не подскажите, откуда все началось? Где мертвые по первой то встали?",194458,null],[195340,"2026-09-07T10:53:52",9,"Фермер — Сторож говорит свист слышал, а на утро могилы разрыты изнутри, мёртвых нет. — *Говорит что знает.* — Кто первым встал, да черт знает, я погост ни ногой.",195330,null],[195341,"2026-09-07T10:54:11",18,"- Да кто против то... \nПустил дымок из раскуренной трубки, ритм барабана сразу же унёс в даль воспоминаний, ритмичные удары барабанов, шаг, шаг, шаг, острие вражеских пик всё ближе, такие же перепуганные глаза напротив, первый скрежет метала о металл, под ногами зачавкало, окропив снежную кашу красеньким... \nВсплыв из череды воспоминаний прислушивается к разговору о происшествии...",195330,null],[195342,"2026-09-07T10:55:13",18,"- уважаемый, а все встали разом? До этого подобного не случалося?",195340,null],[195344,"2026-09-07T10:58:00",9,"— Да ни в жизнь, мы святой водичкой поливаем когда провожаем да Попа приглашаем. Веспираль близко же, сами по себё мертвые не встанут. — *Он потянулся рукой и взял кусочек сыра из кармана, занюхнул глубоко успокаивая нервишки и закусил сырком.* — Чертовщина, что взять.",195342,null],[195346,"2026-09-07T11:00:03",20,"- как ушли они так и не вернулись? Ни нападений, ни тех кто их ещё раз видел? *Интересуется пацан, поправляя капюшон, который то и дело сползает ему на глаза. Большеват на ребенка, что поделаешь*\n\n- Я Рен кстати *он приветливо улыбается попутчикам*",195344,null],[195347,"2026-09-07T11:00:18",18,"- однако... \nУмолкает, поглядывая на спутников... \n- кто сведущ в делах сиих, может доводилось сталкиваться с подобным?",194458,null],[195348,"2026-09-07T11:00:52",18,"Пожимает руку... \n- Лют...",195346,null],[195350,"2026-09-07T11:03:28",18,"К крестьянину:\n- кстати, вот ты говоришь встали и ушли, следовательно раскопа нет, именно что сами разрыли свои же могилы, а ушли, стало быть есть следы, что на своих двоих?",194458,null],[195351,"2026-09-07T11:03:42",9,"Фермер — Я откуда то знаю. За покупками собирался, а там новости такия. Денег мне дали, повозку, вторую лошадь и пенделем выперли искать кто бы мог решить. — *Мужик шёл в город на ускоренни так сказать.* — Может чет решилось уже, вчера дело дело было.",194458,null],[195353,"2026-09-07T11:06:28",9,"//мужик не знает ничего особо, вы немного меж собой познакомтесь пока в пути,",194458,null],[195354,"2026-09-07T11:08:16",20,"- Хм...живого мертвеца видел разок, но вот с тем, что их поднять может не так хорошо знаком *Отвечает Рен*",195347,null],[195357,"2026-09-07T11:11:26",18,"- Рен, я так понимаю ты из попутчиков тоже не знаешь никого?",195354,null],[195359,"2026-09-07T11:12:39",17,"/ 20 мин я в дороге",194458,null],[195360,"2026-09-07T11:12:51",18,"Поворачивается к остальным:\n- ну что будем налаживать взаимодействие? А то может случиться так что через несколько часов помирать вместе придётся... \nОбвёл взглядом...",194458,null],[195362,"2026-09-07T11:15:18",20,"- Не совсем - я ещё не настолько взрослый чтобы один гулять *полушутить он*\n\n- Я вместе со старшим *кивает на мужчину охотника, давая ему самому представится перед попутчиками*",195357,null],[195364,"2026-09-07T11:20:38",18,"Протягивает руку охотнику: \n- Лют...",195362,null],[195370,"2026-09-07T11:30:49",9,"//На будущее",194462,null],[195383,"2026-09-07T11:35:55",18,"//поскольку информации больше особо не получим, а познакомиться можно и дальше  в процессе предлагаю уже доехать до поселения",194458,null],[195385,"2026-09-07T11:37:06",9,"//Щас николай расчехлится, не спешим",194458,null],[195386,"2026-09-07T11:38:14",17,"Люпен сидел и проверял стрелы, он закупился в городе дополнительным колчаном и носил теперь два с собой. Но сами стрелы ему показались сомнительного качества, там где наконечники затупились он точил наждачным камнем придавая остроту\n\n— Приятно звучит, а ты что за птица такая? Говоришь по нашему, я не видал раньше таких как ты, не обижайся, я просто из глубинки. Меня зовут Люпен\n\nПоследнее он говорил обращаясь ко всем, а не только к аракокре",195330,null],[195387,"2026-09-07T11:40:31",17,"— Пацан мне как родной, мы с ним уже пуд соли вместе съели\n\nУлыбается охотник",195357,null],[195388,"2026-09-07T11:40:58",22,"- Вакс, очень приятно. Я ааракокра, подвид козодоев. Я не обижаюсь, наше племя не так часто покидает родные земли. Мы предпочитаем гнездиться повыше и подальше ото всех. Но иногда душа жаждет приключений!\n\nВакс ненадолго прикрыла глаза, наслаждаясь ветерком.\n\n- Тогда предлагаю нам начать с осмотра фермерских земель.",194458,null],[195389,"2026-09-07T11:41:14",17,"— Лют, у тебя выправка военного, ты служивый?",195364,null],[195391,"2026-09-07T11:42:59",18,"- Кхе..есть трошки, четвертной выслуги в наёмных ротах за спиной имеется. \nПриветливо улыбается безпрестрастными \"стальными\" глазами...",195389,null],[195392,"2026-09-07T11:43:23",20,"*Пацан с интересом рассматривает новую знакомую*\n\n- Козодои? А правда что их крик предвестник беды? *Спрашивает он с почти детским любопытством.*\n\n*Из складок его плаща на тебя с не меньшим интересом выглядывают блестящие глаза-бусинки ворона*",195388,null],[195393,"2026-09-07T11:43:51",18,"- Вакс стало быть... \nС интересом разглядывает... \n- а правда что вы можете схватить человека и внести его в горы?",195388,null],[195394,"2026-09-07T11:44:49",18,"Ухмыляясь:\n- предвестник беды это необдуманный поступок, возможно тот который свёл нас всех вместе...",195392,null],[195398,"2026-09-07T11:49:42",17,"— Наверное в городе много таких... разных. В лесу если зверь, то обычно добыча или хищник, а городах не понятно...\n\nУбрав стрелы в колчан Люпен принялся проверять ремни рюкзака, чтобы всё надёжно держалось",195388,null],[195399,"2026-09-07T11:51:34",18,"- тоже так думаю, поэтому и поселился на заброшенном хуторе, красота и не снуют всякие взад-назад...я вообще как стены каменные вижу так меня потряхивать начинает...",195398,null],[195407,"2026-09-07T11:57:29",17,"— Согласен. Лют, есть у тебя байка со службы занятная? Может крепость брали штурмом или еще какая?",195399,null],[195408,"2026-09-07T11:58:08",9,"//Я исчезну на час или два, ирл, сорян",194458,null],[195412,"2026-09-07T12:05:34",18,"Насупившись... \n- байка говоришь, я стены то от того и не люблю, разок в пролом сходишь или с другой стороны постоишь, его удерживая и всё поймёшь, если выживешь, будешь травить байки, если конечно захочешь))",195407,null],[195421,"2026-09-07T12:17:03",22,"Вакс каркающе рассмеялась.\n\n- На счет бед не знаю, но моё появление точно к хорошей заварушке и последующему бомбическому концерту!",194458,null],[195427,"2026-09-07T12:18:36",20,"/мертвяков ждёт dead metal во всех смыслах",195421,null],[195429,"2026-09-07T12:18:54",17,"— Вот как, это хорошо. Я наоборот предпочитаю прятаться, чтобы никто не видел откуда прилетела смертельная стрела. Так что сработаемся.",195421,null],[195430,"2026-09-07T12:19:02",18,"- о, нисколько не сомневаюсь, скоро мы это узнаем на своих с шкурах, главное чтобы концерт не понихидою оказался...",194458,null],[195432,"2026-09-07T12:19:58",20,"- Я тоже в бою вам мало чем смогу помочь к сожалению. Зато немного смыслю в магии - может пригодится когда будем место осматривать",194458,null],[195433,"2026-09-07T12:22:08",18,"- я сразу догадался кто у нас на передке окажется... \nПоглаживает с любовью рогатину с навершием узорчатого металла.",195429,null],[195434,"2026-09-07T12:23:02",18,"- ну теперича стало быть я спокоен, стало быть похороните... По людски... \nРжёт Аки конь.",195432,null],[195435,"2026-09-07T12:23:46",20,"- Да, не переживай об этом. Убедимся что точно не встанешь *смеётся пацан*",195434,null],[195437,"2026-09-07T12:24:53",18,"- а твой оголец то ничего, задорный такой... \nПодмигивает Люпену.",195435,null],[195683,"2026-09-07T15:27:14",9,"Фермер — Ох, приехали! — *О себе напомнил вас извозчик.*",194458,null],[195693,"2026-09-07T15:30:04",22,"- Отлично! Спасибо!\n\nОтсалютировала Вакс и спрыгнула с повозки",194458,null],[195702,"2026-09-07T15:32:29",9,"*Повозка поехала по самодельному деревянному мосту к деревне что была осень похожа на небольшое укрепление снаружи.*\n\n*На входе стояли двоя охранников с пиками, на них старые вычвевшие бригантины, наверное их носило не одно покаление предшественников.*\n\nСтарший стражник — Курт, сволочь, ты не спешил. — *Он ворчал ну улыбался.*\n\nФермер — Жонка так переживает?\n\nСтарший стражник — Угадал, это твои? Орка привёз с собой, хех. — *Стражник был то расистом.*",194471,null],[195705,"2026-09-07T15:33:49",20,"/рано походу прыгать...",195693,null],[195710,"2026-09-07T15:34:25",18,"- любезный, вы нас к дому деревенского головы, али кудой?\nОбращаясь к вознице и поглядывая по сторонам",194458,null],[195713,"2026-09-07T15:34:59",9,"Фермер — Да сами дотопаете. Мне щас поклажу раздать да дамой воротится.",194458,null],[195715,"2026-09-07T15:35:09",9,"//Ссаживайтесь)",194458,null],[195718,"2026-09-07T15:35:40",9,"*Второй стражник отодвигает засовы на воротах.*",194458,null],[195721,"2026-09-07T15:35:59",18,"* спрыгнул чертыхнувшись, колени уже не те...",194458,null],[195724,"2026-09-07T15:36:18",3,"(сорян что врываюсь это же как понимаю чье то приключение? Я тут случайно или как?)",194458,null],[195725,"2026-09-07T15:36:18",22,"Пыльная ааракокра доходит, недовольно зыркнув на возницу.\n\n- То спешивайся, то не спешивайся.. - бурчит девушка.",195713,null],[195728,"2026-09-07T15:37:01",20,"*Рен осторожно слазить с телеги, следуя за взрослыми*",194458,null],[195729,"2026-09-07T15:37:17",22,"//тут у нас темы с квестами, после того, как в поиске ты подберешь себе квест, мастер пригласит тебя в твою тему, а так ты можешь почитать чужие игры☺️",195724,null],[195740,"2026-09-07T15:41:48",18,"Оглядев всех:\n- ну что пройдёмся до начальства местного?",194458,null],[195748,"2026-09-07T15:44:49",18,"- или в кабак, подкрепиться? \nЗаговорчески подмигивает попутчикам.",194458,null],[195755,"2026-09-07T15:47:42",9,"*Старая дверь деревенской заставы скрипит, открывая путь.*\n\nФермер — Бывайте, удачи вам, захаживайте ко мне если места не найдёте, примощу где нибудь. — *Прощается и заезжает внутрь.*\n\nСтарший стражник — Чё встали, заходите. Нечего открытыми воротами светить. — *Он смотрит куда-то на гортзонт при этом, деревня похожа на небольшое укрепление не просто так.*",194458,null],[195772,"2026-09-07T15:54:13",18,"*Лют поводу плечами и разминая кисти проходит первым...оглядывается на остальных, начинает внимательно рассматривать поселение.",194458,null],[195794,"2026-09-07T16:01:46",9,"1. Фонтовые ворота\n2. Башни наблюдения\n3. Ивы и деревья\n4. Местный пивовар, куда без него\n5. Бараки\n6. Рыночная площадь\n7. Колодец\n8. Площадь\n9. Рыбный рынок\n10. Ратуша\n11. Дом попа (гостевой, редко в гостях)\n12. Корчма \"Подгоревшая жопа Вепря\"\n13. Дом Фермера извозчика что вас сюда привёз\n14. Пирс\n15. Лодочная\n16. Смотрящий за пирсом\n17. Местный лекарь\n18. Северные ворота\n19. Какая то хуйня, наверное там колья с головами монстров хз\n\n20. Ну кладбище",194458,null],[195824,"2026-09-07T16:04:43",9,"*Внутри Дрейгхолт меньше напоминал заставу. Люди суетились, местные поля. Возле фермера что вьехал перед вами на площади тут же собралась толпа, разбирали кто что купил. Деревенька жила своей жизнью будто и небыло проблеммы внешне.*",194458,null],[195833,"2026-09-07T16:06:10",9,"//Ели нашёл чёт такое. Ну что-же, все в ваших руках",194458,null],[195861,"2026-09-07T16:10:47",18,"Оглядевшись:\n- какое миленькое поселение...",194458,null],[195863,"2026-09-07T16:11:16",22,"- Давайте сходим к фермеру? С его полей ведь все началось, как нам сказали. Он первый \"пострадавший\".",194458,null],[195866,"2026-09-07T16:11:22",22,"Вакс осматривает карту",194458,null],[195868,"2026-09-07T16:12:04",18,"- разве? Вроде мертвяки с погоста утопали в неизвестном направлении, не?",194458,null],[195894,"2026-09-07T16:15:41",20,"- Можно для начала сходить в ратушу - запрос на наемников отправили коллективный, наверное староста как раз должен быть ответственный за награду за заказ и располагать большей частью информации, что же всё-таки случилось.",194458,null],[195961,"2026-09-07T16:26:19",18,"- это к гадалке не ходи, два путя, либо к голове либо в харчевню...",195894,null],[195964,"2026-09-07T16:26:44",22,"- Наверное я что-то путаю. Почему то была уверена, что все началось с фермера..\n\nАаракокра пожала плечами. Она была согласна начать с ратуши",194458,null],[195973,"2026-09-07T16:27:53",18,"- ну в ратушу так в ратушу, быстрее возьмёмся, да и закончим уже...",195964,null],[195986,"2026-09-07T16:31:52",9,"//Дунчев?",194458,null],[196030,"2026-09-07T16:36:36",9,"//Он темнейшее ведёт и другие, ладно тогда",194458,null],[196130,"2026-09-07T16:55:20",17,"/ Я тут",194458,null],[196137,"2026-09-07T16:56:29",17,"Люпен спешившись сразу шепчет Рену на ухо\n\n— Ты парень смышлёный, я тебе доверяю. Полагаюсь на твою думалку парень\n\nПотрепал красные волосы по отечески\n\n— Скажешь кого нужно пристрелить, дальше дело за мной",194458,null],[196156,"2026-09-07T16:59:52",17,"— Кладбище наверняка было у церкви, можно там узнать, \"как\" ушли мертвецы",194458,null],[196180,"2026-09-07T17:03:49",18,"- по очереди везде пойдём или разделяемая? Корчма, ратуша, дом попа...",194458,null],[196181,"2026-09-07T17:04:11",17,"— Доверюсь Рену, знаю, что он головастый пацан",194458,null],[196189,"2026-09-07T17:05:16",20,"- Лучше держаться вместе. Вдруг мертвецы вернуться и придется давать отпор?",196180,null],[196200,"2026-09-07T17:06:27",20,"- И к лекарю тоже можно заглянуть - может кто-то из свежих мертвецов через него прошел...",196156,null],[196204,"2026-09-07T17:07:01",20,"/все дружненько идём в ратушу?",194458,null],[196243,"2026-09-07T17:12:18",20,"*По дорогу Люпен, возможно уже привыкнув к магическим приколам, слышит в голове голос пацана.*\n\n\"Видишь того ворона? Он с нами, поможет если что-то случиться или мы разделимся. Можешь доверять ему в беде\"\n\n*И правда, с крыши на крышу перскакивает небольшой черный ворон, как будто следуя за группой*",196137,null],[196246,"2026-09-07T17:13:09",17,"Они чуть ранее договорились что Люпен просто думает ответ и Рен его услышит",196243,null],[196247,"2026-09-07T17:13:19",17,"\"Хорошо, что сказал, я уж думал его на ужин стрельнуть\"",194458,null],[196254,"2026-09-07T17:15:03",18,"Посмотрев на ворона передëрнул плечами...",196243,null],[196299,"2026-09-07T17:21:05",9,"*Ратуша, приличный такой отгроханный дачный домик, рядом есть даже где припарковать карету. Возле лвери на лавке спит девушка в приличной одежде, чуть прлучше чем у обычных крестьян, обнимает книгу или блокнот.*",194458,null],[196380,"2026-09-07T17:32:56",18,"Лют неспеша направляется к ней, нависает, звеня кольчугой и громким голосом:\n-Здравствуйте!",194458,null],[196381,"2026-09-07T17:33:02",17,"Люпен подталкивает паренька вперёд \n\n\"Время болтать, значит твой выход. Я осмотрю периметр\"",194458,null],[196409,"2026-09-07T17:35:49",20,"*Рен подходит в след за Лютом. Внутренне надеется что бедняжка не слишком испугается такого пробуждения*",194458,null],[196483,"2026-09-07T17:47:04",9,"*Девушка встрепенулась и буквально вынырнула из под Люта собираясь убегать, а потом кажется поняла что происходит.*\n\nДевушка — Кхм кхм, кто вы? — Неуверенно спросила она пытаясь понять что заьыли тут незнакомые ей люди. И недобро взглянула на Люта, уже собиралась кричать и звать на помощь если бы не была на опыте секретаря.*",194458,null],[196496,"2026-09-07T17:48:58",18,"- нам бы старшого вашего, потолковать...по делу мы к нему, думаю вы уже догадались по какому.",196483,null],[196523,"2026-09-07T17:52:11",20,"- Доброго дня, уважаемая. *Вежливо приветствует Рен*\n- Нам действительно очень нужно попасть к старосте, как и сказал мой коллега, - мы по делу о живых мертвецах \n\n*Объясняет он с вежливой улыбкой, решив уточнить. А то Лют звучал так, будто они долги пришли выбивать. Очень устрошающе, видно человек с опытом.*",196483,null],[196551,"2026-09-07T17:56:25",9,"*Она мгновение постояла перебирая в уме кем бы вы мо6ли быть. Её немного сбил с толку Рен, нг она догадалась.*\n\nДевушка (Анастасия) — Наемники? Кхм, ну. Староста занят, на пирсе какая-то погрузка. Не знаю что там но он очень внимательно следит за этим. — *Она помотала головой, её просили не беспокоить.* — Могу я вам помочь чем-то? Да и о проишествии мне основном расказывали люди, у главы деревни свои заботы как видите. — *Он слегка приподняла платье сделав неумелый реверанс.* — Меня зовут Анастасия.",194458,null],[196568,"2026-09-07T17:59:44",20,"- Очень приятно, я Рен. Не могли бы вы нам рассказать больше о произошедшем? Когда и сколько мертвецов покинуло свои могилы? Не произошло ли ещё что-то после этого за день - может были пропажи среди жителей или скота?",196551,null],[196576,"2026-09-07T18:01:05",9,"*Анастасия.*",194458,null],[196611,"2026-09-07T18:07:07",9,"Девушка (Анастасия) — Мать пришла на могилу своего сына, она часто захаживала туда, его привезли три месяца назад не живым. Позавчера утром мне пришлось смотреть на это вместе с односельчанами, могилы разрыты изнутри, мертвецы встали и пошли. Сторож говорит что ничего не видел и не слышал, лишь свист свистка ночь, но он часто пьян. — *Она что-то прикинула в уме поправив локон завернуа его назад.* — Никаких пропаж скота и людей, а следы что мы нашли ведут к дороге. Многокто поссорился, несколько семей уехали к родным подальше. Единственное, я изучила кто именно воссстал, это были те кто умер относительно недавно, не старше пяти лет могилы.",196568,null],[196635,"2026-09-07T18:12:20",18,"- чудны дела твои...",194458,null],[196640,"2026-09-07T18:12:59",18,"- а сколько всего... Встало и ушло? Их что-то связывало между собой при жизни?",196611,null],[196717,"2026-09-07T18:23:21",9,"Девушка (Анастасия) — Ушло в общем почти пятдесят усобших. Связывает их только то что умерли в течении последних пяти лет. — *Повторила она, и посмотрела на люта взглядом \"ты меня вообще слушаешь или нет старикан\".*",196640,null],[196762,"2026-09-07T18:27:53",20,"\"Хм,  может их в Веспираль стырили некромантам продавать оптом...\" - думает Рен, прикидывая масштаб заклинания которое могло провернуть подобное",194458,null],[196808,"2026-09-07T18:33:48",18,"- сдаюсь, сдаюсь... \nПримиряюще поднимает руки, смотрит в сторону причалов...",196717,null],[196901,"2026-09-07T18:46:49",9,"Девушка (Анастасия) — Награда немного выросла, люди дособрали 240 золотых общими усилиями к этому моменту. — *Она будто хотеля вас хоть немного больше заинтересовать прийти к решению проблеммы, хотя такое колличество золота на четверых было скудно.*",194458,null],[196935,"2026-09-07T18:51:30",18,"- а вот это благая весть...\nИ уже обращаясь к сотоварищам: \n- таки может пройдёмся до причалов с головой потолкуем...",196901,null],[196974,"2026-09-07T18:55:28",20,"- Понятно, спасибо за информацию.*Рен кивнул на прощание Анастасии, оборачиваясь и снова отходя к остальным.*\n\n- хм, можно и до причала. Хотя насколько это полезно будет пока не знаю, если по словам секретаря староста мало погружен в детали проблемы. Разве что заявить о себе... *Он оборачивается к остальным, желая узнать их мнение*\n\n- Кто что ещё думает? Я бы начал с осмотра кладбища, но и на причал можем зайти",196901,null],[197029,"2026-09-07T19:07:23",18,"- можно и на кладбище...местечко присмотреть))",196974,null],[197611,"2026-09-07T20:50:02",9,"//Поздновато уже, но завтра жду решения что вы делаете",194458,null],[197650,"2026-09-07T20:54:30",22,"- Мне кажется, что лучше на кладбище для начала сходить. Это как будто бы само напрашивается.. А на причал мы так или иначе вернемся.",194458,null],[198680,"2026-09-08T08:58:45",9,"//Идёте дружно искать кладбище? Где оно, явно не в посёлке)",194458,null],[198683,"2026-09-08T09:08:30",22,"- По логике кладбище должно быть ниже по реке, давайте прогуляемся?",194458,null],[198684,"2026-09-08T09:08:50",17,"— Мы должны найти там следы, если толпа мертвецов ушла по земле их не может не быть. Последуем за ними и найдём куда они отправились",197650,null],[198693,"2026-09-08T09:13:06",9,"//Покажите куда вы идете искать кладбище)",194458,null],[198695,"2026-09-08T09:13:44",17,"/Щас спросим",198693,null],[198696,"2026-09-08T09:14:04",9,"//вы приехали из этой стороны и кладбища не видели.",194458,null],[198697,"2026-09-08T09:14:38",17,"— Прости, можешь нам указать дорогу к кладбищу мы хотим выследить толпу мертвецов по следам.",196717,null],[198698,"2026-09-08T09:16:00",9,"Девушка (Анастасия) — О, это легко... — *Слегка воодушевленная что вы все же взялись за работу она расказыват где кладбище.*",198697,null],[198701,"2026-09-08T09:17:16",17,"— Спасибо красавица. Не переживай, мы разберёмся. Потом еще песни будут слагать и в тавернах петь об этом подвиге. Как отряд наёмников под названием... Эм... Пока безымянный, но скоро мы придумаем хорошее название нашей компании!",194458,null],[198702,"2026-09-08T09:18:19",9,"*Вверх по реке через северные ворота слегка свернув в лес при первом же повороте направо по слегка узковатой тропе. Через заросшие советовала не ходить, это могут быть тропы грибников, ток заблудитесь.*\n\nДевушка (Анастасия) — Вам нужна еще какая-то помощь? — *Интересуется девушка слегка заулыбавшись, хоть и секретарь да молодая ещё.*\n\n//Кладбище отмеченно на карте",195794,null],[198707,"2026-09-08T09:24:59",18,"- а может прогуляешься с нами, покажешь дорожку?",198702,null],[198708,"2026-09-08T09:27:01",22,"- Вам наверное скучно тут сидеть и заниматься бумажной волокитой. Хотите мини-приключение? Бурю эмоций мы вам точно обещаем.",194458,null],[198709,"2026-09-08T09:27:30",17,"— Зачем рисковать такой хорошенькой девушкой? Ей еще детей рожать, а не гоняться по курганам за нежитью",198707,null],[198710,"2026-09-08T09:28:07",9,"*Она взглянула на Люта, Вакс, на пацана с охотником. На своё место а после на порт, чуть ли не минуту думала.*\n\nДевушка (Анастасия) — Думаю я могу. Пошло оно всё к чертям, сегодня у меня выходной. — *Она усмехнулась и повесила книжку на пояс, у девугки проснулся авантюрный дух, нг и здравый смысл не прошёл, надо оправдать своё отсутсвие на посту:* — Если что — я вам помогаю потому что вы настояли?",198707,null],[198712,"2026-09-08T09:29:16",9,"*Надменный взгляд, словно \"ты не заставишь меня рожать детей, я лучше сдохну\". Возможно с этим уже ей давно надоели родители.*",198709,null],[198713,"2026-09-08T09:30:54",22,"- Часики \"тикают\" ага ага. Знаем такое.\n\nВакс целиком и полностью поддерживает девушку.",194458,null],[198719,"2026-09-08T09:33:20",9,"Девушка (Анастасия) — Ну что, пошли тогда, пока ко мне работа не прибежала. — *Поправила юбку подтянув её чутка с одной стороны чтобы не мешала идти в темпе или бежать.*\n\n//Теперь на кладбище хреначим?)",198713,null],[198720,"2026-09-08T09:33:55",17,"— Тогда берите ответсвенность за безопасной девченки сами. Я пас",194458,null],[198721,"2026-09-08T09:34:03",17,"— Следы на мне, потопали",194458,null],[198723,"2026-09-08T09:34:57",9,"//Поставьте большой палец под этим сообщением что все тут и я продолжу",194458,null],[198729,"2026-09-08T09:37:52",17,"/@PaIIasCat",194458,null],[198776,"2026-09-08T09:59:25",20,"/на месте",198729,null],[198835,"2026-09-08T10:26:48",9,"*Старое кладбище, ближе к дорогам могилы за которыми смотрят, а дальше заросшее, старое и почти никаких тропинок. У самого леса стоит сгоревшая часовня. Меж кенотафами и могильными камнями ветром колышатся полевые цветы.*",194458,null],[198836,"2026-09-08T10:27:12",17,"— Что с часовней стряслось? Молния господня попала или подожгли?",194458,null],[198838,"2026-09-08T10:30:26",9,"*У самого кладбища есть ещё сторожка, сейчас она пустует. Новое кладбище разорено, все относительно недавние разрытые изнутри, словно из могил вылезали.*\n\nДевушка (Анастасия) — Она сгорела за пару лет от моего рождения. Всегда думала что лучше строить из камня. — *Она ответила в шутку, а после серьёзно.* — Думаю кто-то был неосторожен к огню. Гуляла там ребенком, просто развалюха что может рухнуть в любой момент.",194458,null],[198839,"2026-09-08T10:32:00",20,"- Священников получается в деревне нет?\n\n/Ну кроме попа который тут проездом иногда",198838,null],[198840,"2026-09-08T10:32:07",9,"*Старое кладбище с сгоревшей часовней, рядом новое протоптанное где могилы разорены. Прямо у самого кладбища пустая сторожка, Анастасия недовольно зыркнула на неё прежде чем присела показывать следы.*\n\nДевушка (Анастасия) — Тут уже натоптали, но видно что мертвецы вылезли сами.",194458,null],[198841,"2026-09-08T10:33:51",9,"Девушка (Анастасия) — Раз в месяц к нам заезжает отец, иногда чаще, несколько дней он точно не приедет. Еще есть один... но он так, слишком набожный, не более, никаких святых фокусов не умеет. — *Настя не слишком набожная.*",198839,null],[198844,"2026-09-08T10:36:13",9,"*Пахнет свежей землёй и гнилью. Девушка слегка поморщилась.*\n\nДевушка (Анастасия) — Не уверена сама что здесь произошло. — *Встала слегка отряхиваясь.* — Но для этого вы здесь, есть идеи или подобный опыт?",194458,null],[198845,"2026-09-08T10:38:07",20,"- Думаю пока взрослые проверяют физические следы которые тут могли остаться я попробую посмотреть магический след *Рен ищет место, где можно присесть, и открывает книгу, готовясь к ритуалу обнаружения магии*",198844,null],[198846,"2026-09-08T10:39:31",9,"Девушка (Анастасия) — О, ты сведущ в колдовстве? Родители не скупились на умные книжки. — *Слегка улыбнулась, она поняла что паренек тут не просто так. Но все равно немного саркастично.*",198845,null],[198847,"2026-09-08T10:41:18",20,"- Семья...Да, можно и так сказать *Слегка хмыкает пацан, уже листая книгу на нужное заклинание.*\n\n- Хочешь посмотреть? *Указывает на место рядом с собой.*",198846,null],[198850,"2026-09-08T10:41:57",18,"Осмотревшись:\n- какое милое место, тишина, умиротворение... \nНеспешно направляется к часовне, поглядывпя по сторонам.",194458,null],[198851,"2026-09-08T10:42:05",9,"Девушка (Анастасия) — Может позже, мне думаю есть за кем присматривать. — *Смотрит на остальных, вояка уже к часовне пошел за чем-то, на старое кладбище.*",198847,null],[198852,"2026-09-08T10:43:34",9,"//Пока Рен занят ритуалом что остальные?",194458,null],[198854,"2026-09-08T10:44:47",18,"//Прошёлся до часовенки, заглядывая в пустые могилы, чисто визуально я могу заметить что-то интересное?",198852,null],[198855,"2026-09-08T10:45:15",9,"//Кинь восприятие, а так",198854,null],[198856,"2026-09-08T10:47:59",18,"/roll@roll_bot",198855,null],[198860,"2026-09-08T10:51:36",9,"*Свежие могилы, из них чточно разрывались мертвецы. То тут то там Лют может заметить отвалившуюся кость или кусочек еще не сгнившей полностью плоти. Чем ближе к сгоревшей часовенке тем реже ходят люди, пока тропы вообще перестали угадываться. Старые могилы не тронуты совсем, только новые. Ты отошел на доброе расстояние от своих.*",198857,null],[198865,"2026-09-08T10:55:01",18,"Неспешно возвращаюсь, наблюдая за работой юного дарования... \n- странно что затронуты только относительно свежие могилы, тут 5 лет назад ничего такого...не хорошего не происходило?",194458,null],[198869,"2026-09-08T10:57:11",18,"- Люпен, ты же явно лучше всех разбираешься в следах, может посмотришь куда они уходят? А кое-кто может тебе помочь зорким взглядом с неба, кивает на \"птичку\".",194458,null],[198870,"2026-09-08T10:57:21",9,"Девушка (Анастасия) — Монстры иногда наплыаают, отбиваемся. Заборы вокруг деревни не просто так. Но монстры — не мертвые, люди их уже не бояться. — *Взглянула на пасмурное небо, вздохнула.* — Уже не возле Веспирали, но еще не в Вальдхейме, дикая охота к нам не захаживает.",198865,null],[198871,"2026-09-08T10:58:17",18,"- и то дело...а из монстров кто обычно наведывается?",198870,null],[198875,"2026-09-08T11:00:43",9,"Девушка (Анастасия) — Гоблины, рыбы иногда тревожат рыбаков. Ночью в реке плавает бормотун, нечисть лесная и звери. — *Она перечислила то что слышала и видела чаще всего сама.* — Охотники иногда троллей и орков разных гоняют по лесу, возвращаются живыми не всегда.",198871,null],[198876,"2026-09-08T11:01:56",22,"Вакс осматривает местность на предмет обычных человеческих следов, не мертвецов. Присматривается к походке, ведь у трупов она специфичная и ищет, может найдёт какой-то мусор свежий, типа бутылок, бумажек и пр.",194458,null],[198877,"2026-09-08T11:02:29",22,"/r +5 внимание",194458,null],[198879,"2026-09-08T11:05:56",18,"- фронтирненько у вас тут  а что держит на этом месте, может сняться всем вдруг да и двинуть вниз по течению подальше от Веспирали ентой? Был я кстати там не так давно, жуть редкостная...",198875,null],[198880,"2026-09-08T11:05:59",9,"*Люди много натоптали, но это обычно лапти и ботинки, но ты находишь след от каблука среди следов из-за более глубокого углубления на земле, отличается от остальных. На кладбище чисто, никто не накидает лишнего, правда пару пустых фляг лежит, возле сторожки уже с дюжину пустых фляг и пару разбитых бутылок.*",198878,null],[198881,"2026-09-08T11:07:03",9,"Девушка (Анастасия) — Все просто, я тут родилась и живу.",198879,null],[198883,"2026-09-08T11:08:09",20,"*Ворон кружится и садится на плечо к Люпену. Похоже и правда будет помогать?*\n\n/Действия помощь на проверки будущие, пока Рен занят ритуалом",194458,null],[198885,"2026-09-08T11:10:07",18,"Набивая трубку, с ехидцей прищурившись, наблюдает за действиями остальных...",194458,null],[198900,"2026-09-08T11:14:04",18,"- Анастасия, солнышко, а что смотритель кладбища не часто в сторожке появляется, бухает-с?",198881,null],[198904,"2026-09-08T11:16:33",9,"Девушка (Анастасия) — Пьянствует. Где у него только деньги берутся. Той ночью он слышал лишь свист и ничего не помнит. — *Она криво улыбнулась.* — Сейчас в корчме наверное сидит, его работа \"убежала\" так сказать. — *Махнула рукой на могилы.*",198900,null],[198905,"2026-09-08T11:18:00",22,"Вакс указывает товарищам на находку.\n\n- Анастасия,  вопрос, конечно,  будет очень странный. Но много ли у вас жителей, кто носит обувь с каблуком?",198880,null],[198906,"2026-09-08T11:20:25",18,"- мда, нет работы спать ложимся, есть работа, дальше спим...",198904,null],[198907,"2026-09-08T11:20:57",9,"Девушка (Анастасия) — Только по праздникам или городские, только... — *Вспомнила одну особу легкого поведения.* — Ещё Клавдия, девушка легкого поведения если вы пониматете о чем я. — *Она усмехнулась свом мыслям, может очередной любовничек перепутал с ней обувь после ночи.* — Думаю её точно небыло тут.",198905,null],[198909,"2026-09-08T11:21:33",22,"- Хорошо. Ребята, вы осмотрели сторожку?",194458,null],[198921,"2026-09-08T11:26:12",9,"//Заметка для игроков. Если вы заметили что-то как персанаж, условно другие не знают этого пока вы остальным не расказали/указали на это. Если вы ведете будто знаете и делаете то что персонаж знать не должен — это метагейм, он не приветствуется в НРИ. Узнайте у других, спросите, и любой другой способ. На будущее.",194458,null],[198922,"2026-09-08T11:26:48",17,"Люпен улыбается ворону севшему на плечо и садится ближе к земле, к следам\n\nОн проводит пальцем проверяя глубину отпечатка и смотрит в поисках особых следов, костяных стоп или босых ног",194458,null],[198923,"2026-09-08T11:27:08",17,"/r +d20+3 Выживание с помощью ворона",194458,null],[198927,"2026-09-08T11:27:54",9,"*Люпен находит ещё несколько следов от башмаков, а ещё кажется мертвецы шли в сторону деревни.*",198924,null],[198930,"2026-09-08T11:29:05",17,"— Мертвецы сошли с дороги и шли к деревне. И тут следы от необычных башмаков с каблуком. Их кто то вёл?",194458,null],[198933,"2026-09-08T11:30:17",18,"- дамы вперёд... \nИскренне по отечески улыбается))",198909,null],[198937,"2026-09-08T11:31:22",18,"- Очень интересно, на родные шконки их что-ли потянуло? С другой стороны, а деревне всё тихо, получается они не дошли...",198930,null],[198941,"2026-09-08T11:32:19",18,"*Смотрит на обувь Анастасии, что видит Лют?",194458,null],[198943,"2026-09-08T11:33:47",22,"Не дождавшись ответа, ааракокра пошла самостоятельно осматривать сторожку, а после и часовеньку.\n\nЕсть ли следы земли, если есть слой пыли/сажи, поврежден ли он.",194458,null],[198945,"2026-09-08T11:34:10",22,"/r +5 внимание в сторожке",194458,null],[198947,"2026-09-08T11:34:19",22,"/r +5 внимание в часовне",194458,null],[198971,"2026-09-08T11:46:53",9,"*Ботинки гомнодавы, только и того что чистые и аккуратные, не каблуки.*",198941,null],[198972,"2026-09-08T11:47:51",9,"*Часовня очень старая, сгоревшая давно. Здание кажется модет вскоре рухнуть. Щепки, мелкий мусор, остатки сидений, все это было минимум 20 лет назад.*",198948,null],[198980,"2026-09-08T11:50:58",9,"*В сторожке тхнет алкоголем, что-то сгнило. Обычный крохотный бревенчатый домик сторожа, внутри есть где полежать, посилеть, поглядеть снаружи что творится через окошко. Небольшая печ, снаружи еще стоят козлы для расптла и работы, но ими не пользовались давно, сторож спился в какой-то момент.*",198946,null],[198994,"2026-09-08T11:54:12",18,"- похоже нужно идти обратно к селению, смотреть куда мертвяки ушлепали...или юный маг нам прямо сжечь и сейчас готов явить чудо?",194458,null],[199006,"2026-09-08T11:56:36",20,"/ритуал там ещё не успел сработать?",198852,null],[199013,"2026-09-08T11:57:35",17,"Люпен тоже идёт за Аракокрой в сторожку.\n\n— Что то нашла?\n\nосматривается\n\n/Помощь",194458,null],[199017,"2026-09-08T12:04:22",9,"*Рен начинает чувствовать некротику в воздухе, особенно от места с несколькими следами от башмаков. Точно ничего не уловить кроме того что те ушли к деревне. Школа некромантии.*",199006,null],[199018,"2026-09-08T12:04:57",9,"*Ты находишь золотую монету не местной чеканки.*",199013,null],[199021,"2026-09-08T12:06:22",9,"*Анастасия ходити тоже ищет, но большую часть всего она видела, лишь направление куда шли мертвецы не знала, не видела башмаков до того момента как с вами пошла и других мелочей.*",194458,null],[199024,"2026-09-08T12:09:12",20,"- Хм...след некромантии, идёт в сторону деревни. *Он хмурится, осматриваясь*\n\n*Возможно на том месте как раз и применили какую-то магию, чтобы поднять мертвых?*\n\n/За ворона хочу ещё облететь это место и посмотреть сверху в более далёком радиусе",199017,null],[199031,"2026-09-08T12:15:33",9,"*Небольшой пролесок и дальше открытая местность, по общим признакам они будто шли к северным воротам. Но как сторожа не заметили толпу нежити из около 50 трупов?*",199024,null],[199036,"2026-09-08T12:21:05",20,"- Странно это все... *Рен задумчиво поглаживает ворона, который вернулся и теперь сидит на его плече*\n\n- Судя по всему мертвецы шли к Северным воротам, но почему-то никто их так и не заметил. Аура невротическая туда же ведёт *Сообщает он другим*",199031,null],[199037,"2026-09-08T12:21:09",17,"— Монета не здешней чеканки, кто то узнаёт принадлежность?\n\nЛюпен демонстрирует монетку\n\n— Может сторожа подкупили",194458,null],[199038,"2026-09-08T12:23:34",9,"Девушка (Анастасия) — Покажи покажи. — *Смотрит на монетку.* — Не сильно разбираюсь, но это кажется из союза королевств, частая, но у нас такие редко увидишь.\n\n*Достает свою монету, местную. Вместо гербов на ней изображён пегас, хоть и криво, но видно что золото и старались.*",199037,null],[199040,"2026-09-08T12:31:44",20,"*Рен пока идёт к месту где аура некротики видна сильнее всего. Может там есть следы применения какого-то ритуала, которые не заметили остальные?*",194458,null],[199041,"2026-09-08T12:34:37",17,"— Надо дальше по следам следовать, не могли же мертвецы под земли провалиться? Или... могли?",194458,null],[199042,"2026-09-08T12:35:27",18,"- не нравится мне всё это...очень и очень. \nПроверяет легко ли щит перебрасывается на руку и справно ли боевой молот выходит из петли на поясе, начинает заметно нервничать.",194458,null],[199043,"2026-09-08T12:35:31",9,"*Следы от каблуков где-то в центре нового кладбища и самое густое скопление некротической эманации тут, больше ничего. Аура достаточно слабая, да и не удивительно, уже пару дней как прошло.*",199040,null],[199045,"2026-09-08T12:36:29",18,"- Да уж не мешало бы понять куда они дружною гурьбою подалися...",199041,null],[199046,"2026-09-08T12:36:47",9,"//Идёте исследовать дальше?",194458,null],[199047,"2026-09-08T12:37:57",9,"*Следы ведут все дальше, после пролеска из почти не видно, словно кто-то убрал часть, но по помятой траве вы кое как поняли что к воротам мертвецы все де дошли.*",194458,null],[199050,"2026-09-08T12:38:20",20,"*Рен подумал, постоял на этом месте, посмотрел на эту ауру... Наложил доспех мага на себя - мало ли*\n\n*Потом пошел за остальными*\n\n/Доспех мага",194458,null],[199053,"2026-09-08T12:38:56",9,"Девушка (Анастасия) — Странно все это. — *Она взяла записную книжку и сжала ее в руках, не думала что мертвецы могут быть в деревне все этов время.*",194458,null],[199068,"2026-09-08T12:42:18",9,"*Перед северными воротами сидят два стражника и играбт в кости, эти веселее чем на южных.*\n\nПервый страж — Воротилися? Что там Анастасья.\n\nДевушка (Анастасия) — Прости, я сама пока в шоке. — *Она глянула на вас не зная говорить ли что вы заметили, решила сама не говорить пока, а то мало ли.* — Если узнаю чего, раскажу.\n\nВторой страж — У меня 16! — *Он грохнул чашкой и на костях ему свезло.*\n\nПервый страж — Ах ты ж, щас отыграюсь. — *Колотит чашку с кубиками.*",195794,null],[199106,"2026-09-08T12:52:11",18,"- служивые, тут такое дело... По всему выходит, что умертвия прям к воротам подходили, либо и вовсе зашли внутрь, второе конечно сомнительно, но...",199068,null],[199116,"2026-09-08T12:54:09",9,"Первый — Да мы невидели ничё. — *Чешет голову.*\n\nВторой — Ночные бы приметили, куда там, если больше обного. Брэшешь.",199106,null],[199117,"2026-09-08T12:54:41",9,"*Страдники молодые, не верят, только дружно рассмеялись. Как они могли мертвецов в деревню пропустить?*",194458,null],[199118,"2026-09-08T12:55:04",18,"- а вы в ту ночь при воротах стояли?",199116,null],[199136,"2026-09-08T12:59:29",18,"- Рен, а ты можешь определить от ворот куда дальше костяки пошлепали?",194458,null],[199140,"2026-09-08T13:00:29",20,"- Могу попробовать, если аура ещё сохранилась *Рен уже осматривается вокруг, пытаясь найти след некротики, который сюда вел*",199136,null],[199141,"2026-09-08T13:00:40",9,"Первый — Неа.\n\nВторой — Не помню, вроде Юра стоял, он мужик соровый, и муху не пропустит.",199118,null],[199143,"2026-09-08T13:01:04",9,"//Еще ритуал обнаружения один?",199140,null],[199146,"2026-09-08T13:01:19",9,"//Шли вы больше 10 минут к воротам",194458,null],[199149,"2026-09-08T13:01:33",20,"/тогда да ритуал, ячейку берегу",199146,null],[199155,"2026-09-08T13:03:18",18,"- Юрия этого, если что, нам где найти?",199141,null],[199161,"2026-09-08T13:06:16",9,"Первый — Дома наверное спит.\n\nВторой — Да не, он же со старостой в порту последние лва дня. Думаю там, если не дома.\n\nДевушка (Анастасия) — Я знаю где он живет. — *Она уточнила на всякий случай.* — Деревушка небольшая, все друг друга знаем.",199155,null],[199171,"2026-09-08T13:12:25",18,"- это хорошо, дождемся результатов ритуала да и пойдём наверное до головы и Юрия дойдём?",194458,null],[199173,"2026-09-08T13:13:37",9,"//С нами Ааракокра чет пропала, пока подождём её.",194458,null],[199202,"2026-09-08T13:29:25",22,"//это помощь на сторожку была, но раз ничего не нашли, идем к воротам со всеми",199198,null],[199203,"2026-09-08T13:29:53",22,"//я с вами, не ждите, если что я большим постом все охвачу👌",194458,null],[199216,"2026-09-08T13:32:24",9,"// *прикольные звуки недовольного мастера* Что дальше, вы у северных ворот?",195794,null],[199218,"2026-09-08T13:33:20",22,"- Может в таверну? Перекусим да опросим, вдруг кто что интересное видел, а мы и не знаем",194458,null],[199227,"2026-09-08T13:35:38",18,"- ща молодой человек волшбу досотворит...а так то да перекусить да народ поспрощать не помешало бы, а может и голову там с Юрием встретим, всех зайков одним махом...",194458,null],[199232,"2026-09-08T13:36:51",9,"*Слабо, но ты чувствуешь что нежить прошла через ворота внутрь.*",199149,null],[199234,"2026-09-08T13:37:00",17,"— Мужики, Юру то где сыскать? В таверне небось, але дом у него?",199218,null],[199235,"2026-09-08T13:37:40",9,"//.",199161,null],[199243,"2026-09-08T13:40:55",18,"- ну что, получилось, дознания до чего али в пустую почародействовал?",199149,null],[199244,"2026-09-08T13:41:43",17,"— А, да. Давайте найдём ночных дозорных той ночи",194458,null],[199245,"2026-09-08T13:41:53",9,"Второй — Да говорю же, со старостой напирсе.\n\nПервый — Анастасья покажет. — *Махнул рукой.*\n\n*Стража северных ворот лениво с вами общалась.*",199234,null],[199246,"2026-09-08T13:42:27",20,"*Рен осматривает ауру*\n\n- Аура ведёт за ворота. *Сообщает он*\n\n- Давайте пока отложим таверну и остальное - нужно пройти посмотреть куда ведёт след, пока я его ещё вижу",199232,null],[199247,"2026-09-08T13:42:50",17,"— Тоже верно, магический компас дали, надо воспользоваться",199246,null],[199248,"2026-09-08T13:44:09",18,"Первым проходит в ворота: \n- Показывай куда дальше...",199246,null],[199250,"2026-09-08T13:44:32",9,"*Вас пропускают и Рен до окончания ритуала понимает что след ведет в сторону пирса, а ещё, кажется часть нежити все же разбрелась по селению, но куда одиночки ращошлись не определить.*\n\n*Со стороны корчмы что-то горит, кажется?*",194458,null],[199262,"2026-09-08T13:46:39",20,"\"А вот похоже что и погружал там староста...\" - мрачно думает Рен.\n\n- Основная часть ушла к пирсу, но вот остатки все ещё в поселении.\n\n*Он смотрит на дым*\n\n- Похоже нужно бежать спасать...\n\n*А вот ворона он мысленно посылает посмотреть что там на пирсе*",199250,null],[199265,"2026-09-08T13:47:35",9,"//Ваши действия господа)",194458,null],[199266,"2026-09-08T13:48:07",20,"/бежим спасать пиво?",194458,null],[199273,"2026-09-08T13:53:53",17,"— Тоесть ночью они в город проникли, а после спрятались где то? В землю зарылись?\n\nСмотрит на дым\n\n— Бежим быстрее, Рен веди по четкому следу, одиночки меньшая беда чем толпа",199262,null],[199278,"2026-09-08T13:57:04",22,"- Да, могли в сарае заныкаться, странно только, что животина деревенская не выдала их. Животные же такое чуют.\n\nКозодой посмотрела на Рена.\n\n- Согласна, давай по следу побежим, пока он не пропал",194458,null],[199279,"2026-09-08T13:58:51",20,"- Четкий след - на пирсе. В горит кормча",194458,null],[199280,"2026-09-08T13:59:12",20,"/нужно выбрать короче",194458,null],[199281,"2026-09-08T14:02:29",9,"*Ворон быстро прилетел к докам, там пяток людей в доспехах лёгких, поношенных и никого не пускают. На пирсе видны лодки, в них что-то накрыто парусиной и одна разбитая словно её перекусили пополам. Староста разговаривает с кем-то и этот кто-то заходит в лодочную и закрывается там.*\n\n*Люди сейчас все бегут к корчме, кто с ведрами, а кто зевака.*\n\nДевушка (Анастасия) — Что за чертовщина тут происходит, ничего же не горело еще с позапрошлого года. — *Немного ругается и бежит смотреть что-там горит, что вы шли к докам она услышала, пойдёт позже.*",199262,null],[199285,"2026-09-08T14:14:33",20,"/через ворона вроде все ещё работает обнаружение магии. Есть аура некротики у груза в лодках?",194458,null],[199298,"2026-09-08T14:17:20",18,"- Покушали на...",199279,null],[199313,"2026-09-08T14:20:15",9,"//Я не уверен работает ли, опиши что делает ворон, результат очень зависит от этого)",199285,null],[199320,"2026-09-08T14:22:43",20,"*Ворон ведёт себя по максимуму как обычная птица. Покружился над пирсом, сел в сторонке что-то поклевал с земли. Потом сел (футах в 30 от лодок) на какую-то балку, чистит пёрышки*",199313,null],[199324,"2026-09-08T14:23:58",9,"//попрошу показать точку на карте где ворон именно сидит)))",195794,null],[199326,"2026-09-08T14:25:30",18,"Стоим на перекрестке...слева горит корчма, справа причалы:\n- сердце кровью обливается...",194458,null],[199330,"2026-09-08T14:25:44",20,"Пусть будет так",195794,null],[199331,"2026-09-08T14:26:31",9,"//Внимательность ворона)",194458,null],[199332,"2026-09-08T14:27:07",20,"/r d20+3",199331,null],[199334,"2026-09-08T14:27:15",20,"/ну ладно",194458,null],[199336,"2026-09-08T14:27:27",9,"//Скок у него хитов напомни?",194458,null],[199338,"2026-09-08T14:27:45",20,"/1, это же ворон просто",199336,null],[199339,"2026-09-08T14:27:49",9,"/roll +d20+7 от засады преим",194458,null],[199341,"2026-09-08T14:28:02",20,"/убил че",194458,null],[199343,"2026-09-08T14:28:22",20,"/хоть увидел кто напоследок?",194458,null],[199345,"2026-09-08T14:28:31",9,"*Ворон успевает лишь мельком заметить костяную руку что появилась из воздуха и схватила его, сжав насмерть...*",194458,null],[199346,"2026-09-08T14:29:24",9,"*В доках чувствовалась некротика,  что лежит в лодках точно сказать нельзя, если конечно это не очевидно.*",194458,null],[199347,"2026-09-08T14:30:15",18,"Видя как побледнело лицо юноши, взял его за плечо:\n- Рен, что там?!",194458,null],[199348,"2026-09-08T14:32:01",17,"/Обновил",194458,null],[199349,"2026-09-08T14:32:23",22,"- Доки говоришь.. а ведь мы хотели начать с пирса.. Мне кажется лучше туда сходи.. \n\nВакс увидела побледневшего парня.\n\n- Ой, вы в порядке?",194458,null],[199350,"2026-09-08T14:32:54",20,"*Рен морщится, рывком возвращаясь из зрения погибшего фамильяра к своему.*\n\n- В доках - лодки нагружены чем-то ч скорее всего как раз телами. Одна как будто перекушена. Староста и странный человек в лодочной. Везде некротика - больше не могу увидеть, ворон попал в засаду",199347,null],[199351,"2026-09-08T14:32:58",18,"Щит и молот сами собой очутились в руках, размял шею, слегка зашелестела звеньями кольчуга...",194458,null],[199352,"2026-09-08T14:33:17",17,"/r Проблеск гениальности Люпена",194458,null],[199354,"2026-09-08T14:33:47",20,"/Рен читал книгу заговоров, мог же понять что это было леденящее прикосновение?",194458,null],[199355,"2026-09-08T14:34:21",17,"— Стойте! Нам нужно бежать за одиночками отбившимися от стада! Если ночные дозорные пропустили нежить в город, значит куплены! Если нежить вели к докам, значит к лодкам! Их перевезли! А те кто потерялся... Они представляют опасность для людей!",194458,null],[199356,"2026-09-08T14:34:22",9,"//У тебя отличная память, даж бещ проверок мог понять",194458,null],[199357,"2026-09-08T14:34:26",20,"- Атаковали заклинанием. Там либо маг либо опасная нежить",194458,null],[199358,"2026-09-08T14:35:08",20,"- Согласен, сначала убедимся чтобы остатки не навредили людям. На пирс все равно быстро не попасть, учитывая что там происходит и стражу",199355,null],[199359,"2026-09-08T14:35:22",22,"- А ведь ты совершенно прав! Тогда нам лучше разделиться и осмотреть деревню или пойдем вместе?",199355,null],[199367,"2026-09-08T14:37:57",18,"Цедит сквозь зубы, улыбаясь:\n- по одиночке на..",199359,null],[199369,"2026-09-08T14:38:39",20,"- Разделимся - меньше шансов выжить в бою *просто говорит пацан*\n- побежали уже, а то кормча догореть успеет",194458,null],[199370,"2026-09-08T14:38:44",18,"- там просто мертвяки говорили они, дел до полудня...",199357,null],[199380,"2026-09-08T14:39:47",18,"Смотрит на Рена ехидно, но добро, по отечески... \n- так как минимум есть одно место где по любому без потеряшки не обошлось, дуем в корчму?!",199369,null],[199385,"2026-09-08T14:40:53",18,"Срывается первым, демонстрируя недюжую старческую скрепяколенную прыть...",194458,null],[199394,"2026-09-08T14:42:13",9,"//В корчму решили?",194458,null],[199400,"2026-09-08T14:45:00",17,"Люпен бежит позади выискивая крышу куда можно забраться",194458,null],[199404,"2026-09-08T14:48:21",22,"Ааракокра взлетит, осматривает деревню сверху",194458,null],[199408,"2026-09-08T14:48:48",22,"- Рен, не против, если я свяжу наши мысли?\n\n//телепатия до 1 мили",194458,null],[199409,"2026-09-08T14:48:57",9,"*Возле корчмы собралась толпа селян, а точнее у сартира рядом с корчмой. Он догорал, а внутри были кажется чьи то останки, девука сидела на лавке возле кормы и плакала маме в жилетку. Там же Анастасия пытась распросить её что случилось.*\n\nДевушка (Анастасия) — ...так, еще раз. Ты пошла в сартир а там мертвяк. — *Девушка зарёванными глазами перепуганная кое как подтвердила.* — Ты закрыла его в сартире и подожгла в итоге.\n\n*Снова сомнительное подтверждение и плач, вот только бухие мужики у самого сартира были другого мнения.*\n\n— Ахахах, героиня!\n\n— Это моя дочка, вся в отца.\n\n— Черт, на такой и женится можно.\n\n— Глаза на мою дочу не раззувай, пидрила. — *Возле горящего сартира были зеваки, и своя атмосфера, кто-то кому то бил лицо, кто-то тащил ведра с водой.*",194458,null],[199410,"2026-09-08T14:49:26",9,"//Ахренеть, как телепатия такая? Интересно просто, вижу впервые",199408,null],[199411,"2026-09-08T14:49:28",22,"Если Рен не возразит, то перед полётом, делаю с ним мыслесвязь и транслирую все, что увижу",194458,null],[199413,"2026-09-08T14:50:51",22,"//так тг не пускать мои картинки. Плут: клинок души, Психический шепот\nПсихический шёпот. Вы можете установить телепатическую связь с другими — это идеально для тихого проникновения. Действием выберите одно или нескольких существ, которых вы можете видеть — вы можете связаться с количеством существ, равном вашему бонусу мастерства или меньше, после чего бросьте кость псионической энергии. Результат броска определяет то, в течение скольких часов выбранные существа могут телепатически общаться с вами, а вы с ними. Чтобы отправлять или получать сообщения (действий не требуется), вы и другие существа должны быть на расстоянии не дальше 1 мили друг от друга.\n\nСущество не может использовать эту телепатию, если оно не может говорить ни на одном языке.\n\nОно может оборвать телепатическую связь в любой момент (действий не требуется). Вам и существу необязательно говорить на общем языке, чтобы понимать друг друга.\n\nКогда вы впервые используете эту способность после окончания продолжительного отдыха, вы не расходуете кость псионической энергии. Во всех остальных случаях, когда вы используете способность, ваша кость расходуется\n.",194458,null],[199414,"2026-09-08T14:50:51",20,"- Хорошо *Пацан согласно кивает. Какая удобная телепатия, интересно сможет ли он когда-нибудь так же...*",199408,null],[199416,"2026-09-08T14:51:10",17,"/А можно всем?",199408,null],[199417,"2026-09-08T14:51:37",17,"/Ну там по БМ это ты +2",194458,null],[199418,"2026-09-08T14:51:45",22,"/бонус мастерства 2, значит только 2х могу по идее связать",199416,null],[199419,"2026-09-08T14:52:14",22,"Подключаю Люпена",194458,null],[199421,"2026-09-08T14:53:15",9,"//Ааракокра в небе?",194458,null],[199422,"2026-09-08T14:53:17",17,"/Мы можем общаться через тебя с Реном. Если ты выступишь ретранслятором, так как это мысли они мгновенны",194458,null],[199423,"2026-09-08T14:53:55",22,"Да/",194458,null],[199424,"2026-09-08T14:56:08",9,"*Вакс видит с высоты как кажется староста (сложно не отличить единственного облысевшего тучного мужика среди воинов в хорошей одежде) идет с пирса к корчме.*",194458,null],[199425,"2026-09-08T14:56:36",17,"/На крышу могу найти как подняться?, хочу занять позицию на высоте",199424,null],[199426,"2026-09-08T14:56:39",17,"/И спрятаться",194458,null],[199427,"2026-09-08T14:56:44",9,"//Если еще что-то, спрашивай, ваши действия",194458,null],[199430,"2026-09-08T14:57:27",9,"//Ну, смотри как на картинке, чё",199348,null],[199437,"2026-09-08T14:58:42",9,"//Карта настолько хороша, что Дрейгхолт щас станет общей деревенькой для квестов такого типа)",194458,null],[199444,"2026-09-08T15:00:12",17,"На крышу дома попа хочу залезть",194458,null],[199446,"2026-09-08T15:01:03",9,"//Описывай как и кидай куб",194458,null],[199447,"2026-09-08T15:01:24",17,"Люпен сворачивает к дому попа\n\n\"Залезу повыше, прикрою вас издали\"\n\nОн отталкивается от телеги у дома и хватается за карниз, подтягивается и забирается наверх",194458,null],[199450,"2026-09-08T15:02:09",17,"Он достаёт свой особый лук, накладывает стрелу и приятаившись за печной трубой смотрит на корчму, готовясь выстрелить по любому кто покажет агрессию к его союзникам\n\n/Засада + заготовленое действие",194458,null],[199452,"2026-09-08T15:02:11",17,"/Ок?",194458,null],[199457,"2026-09-08T15:03:10",22,"Вакс пытается присмотреться к его обуви и к волнам. Воины дышат?\n\n\n*все транслируется ребятам*",199424,null],[199461,"2026-09-08T15:03:25",18,"Остаюсь у Подгоревшей жопы, смотрю на парящую в небе Арукарру... \n- Рен, ты бы схавался или смешался с толпой...",194458,null],[199463,"2026-09-08T15:03:58",9,"*Вакс заметили в небе, страже с питра, кто-то тыкнул на тебя пальцем и все остальные подтянулись, смотрели ведь примерно в том же направлении где сартир горел. Они подоставали арбалеты, на всякий случай.*\n\n\"Это птица? Это самолёт? Нет! Это Вакс стальная глотка.\"",199423,null],[199468,"2026-09-08T15:04:44",20,"- Как только возникнет опасность - сразу *Отвечает пацан, осматривая место происшествия. Похоже трактир только что оправдал свое название...*",199461,null],[199469,"2026-09-08T15:05:35",9,"*Староста в кирзовых красных сапогах, начищенные, там точно нет каблука. Стража что у доков и пирса жива, даже слишком наверное.*",199457,null],[199471,"2026-09-08T15:06:20",22,"Летаю над полями и домами, выглядываю одиночек",194458,null],[199472,"2026-09-08T15:06:25",22,"/r +5 внимание",194458,null],[199474,"2026-09-08T15:06:41",22,"Икар летел близко к солнцу/",194458,null],[199476,"2026-09-08T15:07:06",22,"Давай прям в коровник, бомбочкой/",194458,null],[199478,"2026-09-08T15:07:55",9,"Тучный староста — Что тут происходит!? — *Явно недовольный тем что устроили.*\n\nДевушка (Анастасия) — У нас был мертвец в деревне. — *Она пересказывает что произошло.*\n\nТучный староста — Мертвец? Да... — *Он внимательно слушает и черещ расступившуюся толпу идет к сартиру что тушат.*",194458,null],[199479,"2026-09-08T15:08:57",9,"*Произошло худшее, Вакс не увидела то что она пыталась высмотреть, мелкий моросящий ещё с утра дождь слегка раздражал глаза.*",199473,null],[199482,"2026-09-08T15:10:06",9,"//Не все тут, щас будем жлать всех реакций и тд. Игра что, где, когда выходит",194458,null],[199483,"2026-09-08T15:10:39",17,"/А кого нет?",194458,null],[199485,"2026-09-08T15:10:48",17,"/Горит сартир у корчмы же?",194458,null],[199491,"2026-09-08T15:11:35",20,"/ага, рядом там только двое",199485,null],[199493,"2026-09-08T15:11:51",22,"Векс приземляется и потирая глаза, идет к остальным",194458,null],[199494,"2026-09-08T15:11:54",17,"\"Они там мертвеца сожгли? В сортире?\"",194458,null],[199495,"2026-09-08T15:12:02",9,"//Сартир тушат, староста смотрит что с сартиром, Анастасия обьясняет ему что узнала о произошедшем близ таверны + толпа зевак",194458,null],[199497,"2026-09-08T15:12:24",17,"\"Что говорят там? Что стряслось?\"",194458,null],[199498,"2026-09-08T15:13:08",20,"\"Верно\" - через телепатическую связь отвечает Рен. - \"Похоже одна из местных наткнулась на него там и с испугу подожгла. Вместе с самим сартиром\"",199494,null],[199499,"2026-09-08T15:13:36",17,"\"Вот это женщина\"\n\nПодумал Люпен забыв что у них общий канал связи",199498,null],[199501,"2026-09-08T15:15:05",9,"//След сцена тогда, раз все",194458,null],[199504,"2026-09-08T15:19:46",9,"Тучный староста — ... Анастасия, она сожгла человека. — *Серьёзно говорит староста.*\n\nДевушка (Анастасия) — Но... — *Она прямо обомлела от такой наглости, человека, но кого?!* — Я..\n\nТучный староста — Молчать! Под арест её до выяснения обстоятельств, в подвал ратуши. Быстро. — *Под влиянием авторитета старосты накопленного годами пару мужиков вышли и оторвали плачущую девушку от мамки извиняясь.* — Никаких мертвецов здесь нет, она сожгла живого человека, не жалейте её. — *Он недобро взглянул на Анастасию, та не нашла что сказать.*",194458,null],[199505,"2026-09-08T15:20:19",9,"//Чем занимаются в это время Рен, Лют и Вакс? Люпен вроде в засаде до сих пор",194458,null],[199509,"2026-09-08T15:22:12",18,"Я прохожу мимо старосты к сельскому туалету, заглядываю туда...\n*можно понять что жгли не живого?",194458,null],[199511,"2026-09-08T15:23:10",9,"*Выглядит как почерневший от пламени труп, с виду так и не скажешь. Похоже на тебя обратили внимание.*\n\nТучный староста — Ты кто?",199509,null],[199514,"2026-09-08T15:24:15",18,"- я то? Лютом зовут, по найму вот, с ситуацией разобраться нанят, дык вы же и наниматель, не?",194458,null],[199516,"2026-09-08T15:24:28",17,"Люпен выжидает в засаде",194458,null],[199523,"2026-09-08T15:25:21",20,"*Рен подходит следом, вставая рядом с Лютом. Косится на сгоревшие останки. Видно остатки ауры?*",194458,null],[199526,"2026-09-08T15:25:55",9,"Тучный староста — Я наниматель да, по запросу односельчан. Почему в деревне? Иди на кладбище, расследуй куда погребённые ушли.",199514,null],[199527,"2026-09-08T15:26:28",9,"*Да, остатки некротики ощущаются.*",199523,null],[199529,"2026-09-08T15:27:31",18,"- Так они сюда и ушли, мил человек... \nСбстоит разведя руки...\n- прям через ворота похоже, строевым маршем...\nсмотрит с прищуром.",199526,null],[199530,"2026-09-08T15:27:46",20,"- И вам доброго дня *Рен звучит вежливо, но внутреннее подбирает слова осторожно*\n\n- Мы как раз этим занимались. Однако следы вновь привели нас в поселение. Пока мы полагаем что некоторые мертвецы действительно могли зайти и затеряться здесь. Девушка скорее всего не обманывает",199526,null],[199532,"2026-09-08T15:28:13",20,"*Лют слышет в голове*\n\n\"Не говори ничего про магию и что я вижу ауры\"",194458,null],[199536,"2026-09-08T15:29:43",9,"Тучный староста — Где? — *Он разводит руками.* — Я знаю здесь каждый уголок в деревне и целыми днями проверяю. Где вы нашли здесь нежить?\n\n*Слышны перешептывания и недоверие среди толпы. Соухи то ползут, странности недавно начались.*",194458,null],[199537,"2026-09-08T15:30:05",9,"/roll +d20+5 староста убеждает толпу",194458,null],[199549,"2026-09-08T15:32:48",9,"*Кажется его слова всем кажутся вполне разумными.*\n\nТучный староста — Мы проверяли, хороненные ушли куда то в лес, это ваша забота если откликнулись на заявление. — *Он указал на Рена и Люта.* — Я узнал о том что вы этом занимаетесь только сейчас. Вы действительно делаете свою работу?\n\n*Анастасия даже засомневалась, хотя была с вами.*",194458,null],[199550,"2026-09-08T15:33:32",18,"- уважаемый, а может мы к пирсам сходим, посмотрим, вот все дружно так сказать всем сходом народным? Поскольку со слов нашего юного дарования дела там происходят... некромантские. Да и деревню по ходу дела осмотрим на наличие нежелательного элемента...",199536,null],[199555,"2026-09-08T15:34:30",18,"- вот это и будет выполнением наших обязательств перед поселением... \nСмотрит старосте в глаза, без вызова, холодно, выжидающе.",194458,null],[199556,"2026-09-08T15:34:41",20,"/лют проигнорировал предупреждение Рена про магию?",199550,null],[199557,"2026-09-08T15:34:45",9,"//Выступление с помехой если не поможет никто",199550,null],[199563,"2026-09-08T15:35:25",9,"//А, не, без помехи, ты упомянул что Рен маг)))",194458,null],[199564,"2026-09-08T15:35:48",20,"/ну Рен помогает, что уже теперь остаётся",194458,null],[199565,"2026-09-08T15:36:16",9,"//Нет врага хуже чем союзник 😏👌",194458,null],[199567,"2026-09-08T15:37:16",20,"- В городе действительно есть след некротический *кивает он, понимая что раз что-то сказал лют, ещё и раскрыв его, то надо хоть как то помочь.*",194458,null],[199570,"2026-09-08T15:37:42",9,"//Помеха была, вы не местные",194458,null],[199574,"2026-09-08T15:39:49",9,"// @dunchev @lady_godzilla если вакс не учавствует в споре а где то в толпе то восприятие, Люпен то же самое",194458,null],[199575,"2026-09-08T15:41:51",17,"/r +2 Зоркий глаз",199574,null],[199579,"2026-09-08T15:43:59",9,"*Скорей всего ты больше сосредоточен на поиске угроз, поэтому не замечаешь ничего интересного.*",199576,null],[199580,"2026-09-08T15:46:03",18,"/roll@roll_bot",199557,null],[199589,"2026-09-08T15:56:06",18,"//мой персонаж знает что Рен на связи с Стальной глоткой?",194458,null],[199591,"2026-09-08T15:56:33",20,"/да, при тебе они об этом говорили",199589,null],[199592,"2026-09-08T15:57:41",18,"Наклонившись, шепотом Рену на ухо:\n- может попросишь стальную глотку метнуться на пристань и притащить мертвяеа какого если они там?",194458,null],[199593,"2026-09-08T15:57:44",17,"/Он еще телепат и тебе в голову может говорить",199589,null],[199595,"2026-09-08T15:59:12",20,"\"Там засада, ее скорее всего атакуют. Но ладно, может рискнёт\" - Рен мысленно передает слова Люта Вакс, предоставляя выбор ей - и ещё раз предупреждает о возможной опасности.\n\n*Рен говорит все тебе мысленно, там он стоит молчит. Ну и выглядит как ребенок который немного запутался и напуган большой толпой - внешне, голос у него спокойный ты слышал*",199592,null],[199615,"2026-09-08T16:03:02",22,"/r +5 Вакс проморгалась после полета",199574,null],[199617,"2026-09-08T16:03:22",22,"-А-АПЧХИ",194458,null],[199621,"2026-09-08T16:04:06",22,"- Извините, где тут аптекарь? У меня аллергия.. \n\nВакс смотрит покрасневшими глазами.\n\n- На работу.. \n\nЕдва слышно добавляет она",194458,null],[199628,"2026-09-08T16:08:24",20,"/это не квест, это затянувшаяся комедия  положений",194458,null],[199709,"2026-09-08T16:23:32",18,"//затишье перед бурей?",194458,null],[200086,"2026-09-08T18:50:30",9,"*Кажется Вакс простудилась немного, глазки слезятся. Погодка мерзкая до ужаса.*",199616,null],[200089,"2026-09-08T18:53:22",9,"*Какая то мазурка, её лицо немного в саде, старая одежда но выглядит красиво. Она увидела незнакомку, но в отличие от остальных не испугалась орка.*\n\nЗолушка — О, простите. Вам плохо? Я могу вас проводить к нашему аптекарю. — *Мило улыбается.*",199621,null],[200122,"2026-09-08T19:08:03",9,"Тучный староста — Вижу вам больше нечего сказать гости. — *Он усмехнулся.* — Не нужно строить теории, кто поверит вашим словам? Да и на пирс сейчас никто не пойдёт, видели лодку перекушенную пополам? Бормотун разбушевался, вылезет ещё на шум, или вы хотите чтобы кого-то съели? Тогда уходидите и не создавайте проблемы, вас позвали помочь, но если так. — *Он указывает на южные ворота, наигранно.* — Выход там.\n\n*Люди заметили Вакс, не все жаловали её внешний вид похоже:*\n\n— Они орка с собой притащили?\n\n— Этот мальчишка из дикой охоты?\n\n— Не, точно сам колдун какой-то, на глаза гляньте, а волосы.\n\n— Дак в дикой охоте же все колдуны.\n\n— Что. Здесь делаю, ма навернре пирог уже приготовила.\n\n*Ращного дела слушки, почему то Рен постоянно улавливает больше о дикой охоте или о нём. В толпе был фермер, тот что вас привёз.*\n\nФермер — Эй, старик. Не бухти. Сгорел сартир и сгорел. Зачем дочку в повал? — *Он остановил мужиков что хотели упаковать плачущую девушку.* — Давайте разьерёмся кого она спалила, кто пропал?\n\n*Народ слегка засомневался, но это да, никто не пропал. В то де время старосте все ещё верили.*\n\n— Ну да, чегойсь это дочу мою пугаете, она никого не жгла. — *Женжина образумилась и давай вместе с бабами у мужиков дочу отнимать.*\n\nТучный староста — Ладно, но следите за ней пока не разберёмся. — *Махнул рукой и обратился к Люту и Рену.* — Будете создавать проблеммы для деревни, я прикажу вас просто выгнать. И потушите уже сартир, место преступление не трогатьи не осматривать, я пошлю кого-то разобраться.",199581,null],[200160,"2026-09-08T19:19:10",22,"- Да, *шмыг*, пожалуйста",200089,null],[200182,"2026-09-08T19:24:22",20,"*Рен тянет Люта за край плаща*\n\n- Пойдем лучше пока к остальным, нужно решить что делать...\n\n\"К осмотру трупа нас все равно не допустят. Но и без этого я вижу что это был живой мертвец.\" - слишишь ты параллельно в голове",200122,null],[200187,"2026-09-08T19:29:11",9,"*Золушка ведёт Вакс к лекарюс милая девушка с корзиной полной белья.*",200160,null],[200190,"2026-09-08T19:30:08",9,"*Староста подсуетился и какой-то мужик остался смотреть за сгоревшим сартиром никого не пуская, а сам пошел к пирсу. Зеваки потехонька начали расходится.*",194458,null],[200196,"2026-09-08T19:31:45",9,"*Анастасия разочарованная идет сидеть на лавке под ратушей. Сидит изучая свою книжку проигнорировав всех кто у неё что спрашивал да и не подойдя к героям, видно что задумалась над жизнью.*",194458,null],[200199,"2026-09-08T19:32:36",9,"*Девушку что сожгла мертвеца в сартире кое как успокоили, пришлось немного ей прибухнуть сидра для храбрости. Но и то молодец что среагировала быстро.*",194458,null],[200208,"2026-09-08T19:34:22",22,"🧠осмотрите пожалуйста вокруг сатира следы, если ещё не замели. Откуда мертвец выполз. Или прям из дырки оттуда?",194458,null],[200219,"2026-09-08T19:36:36",9,"Фермер что вас привез — Ну и представление. А чего это так вы со старостой поспорили? — *Он подршел и спросил у Рена и Люта прямо, ему было интереснос да и знакомец ваш.*",194458,null],[200222,"2026-09-08T19:38:33",18,"- хотел прояснить ситуацию...",200219,null],[200225,"2026-09-08T19:39:19",9,"*Девушка привела Вакс к аптекарю, там пахло травами и мазями. За простыми разговорами ей и тебе налили чай от которого должно пройти небольшое недомогание от простого \"простыл\".*\n\nЗолушка — Такая красивая, вы умеете летать? — *Искренне поинтересовалась девушка.* — Это наверное классно.",200208,null],[200226,"2026-09-08T19:39:35",18,"- странный человече, на работу нанял, а работать мешает, ещё поди и денег займет...",194458,null],[200233,"2026-09-08T19:40:06",20,"- Да как видишь не сошлись в версиях. Следы по нашему мнению явно вели в деревню. Он наверное решил не поднимать панику среди населения, вот и сказал что тут быть никого не может\n\n*Рен выдает короткую версию, опуская магию и подозрения на старосту. Рано для этого пока, нет доказательств...*",200219,null],[200236,"2026-09-08T19:40:25",18,"- если спасаемый не хочет быть спасён, то...это не мои проблемы...",194458,null],[200237,"2026-09-08T19:41:09",18,"- ясно дело тёмное и участвовать в нём всё меньше желания, особенно учитывая риски и вероятность кидка.",194458,null],[200241,"2026-09-08T19:44:04",9,"Фермер что вас привез — Да чего вы. За дело и награда положенна, не со своего кармана староста платит, народ же собрал. — *Фермер почухал затылок пытаясь понять, да кивнул.* — Утро вечером оно получше, хотя обед ещё. Если что у меня переночуете и утром со свежими силами двините отсюда, так и быть отвезу вас, хоть и в город мне не надо.",194458,null],[200255,"2026-09-08T19:50:38",20,"- Спасибо вам, надеюсь не слишком потесним на ночь *Улыбается Рен*\n\n- Ну а с делом мы всё-таки ещё попытаемся разобраться, негоже так людей оставлять, верно? Уж не получится тогда ничего не поделаешь - утром до города\n\n*Он снова поворачивается к Люту - мол пойдем поищем наших?*",200241,null],[200258,"2026-09-08T19:51:10",20,"/кстати какой там сейчас час дня?",194458,null],[200261,"2026-09-08T19:52:02",9,"Фермер что вас привез — Хороший настрой пацан. — *Он оглянулся и наклонился.* — Я тут краем уха слышалс вот в толпе кто-то говорил, ты и правда колдун?",200255,null],[200262,"2026-09-08T19:52:20",9,"*Молодому фермеру просто интересно.*",194458,null],[200266,"2026-09-08T19:54:20",20,"- Только учусь, но немного умею *так же заговорчески делится шопотом пацан. То что он волшебник а не колдун не поправляет намеренно*\n\n- Вот недавно даже научился свечки зажигать по щелчку. *Делится он самым настоящим детским и доверительным тоном* - может скоро даже дверь без рук открывать научусь!",200261,null],[200268,"2026-09-08T19:54:55",20,"/кстати, что Рен знает о дикой охоте?",194458,null],[200269,"2026-09-08T19:55:20",18,"- вот что точно, на ночь нам тут не стоит оставаться, а до заката найти, притащить на площадь мертвяка да собрать, подтянуть старосту за язык его поганый...",200255,null],[200285,"2026-09-08T20:01:53",9,"*Дикая охота, великий шабаш, колдуны и маги из Вальдхейма по легендам разьезжающие на призрачных конях, а правит ими самый сильный маг и воин, Король Колдун.*\n\n//Самый минимум",200268,null],[200291,"2026-09-08T20:04:13",38,"// Если че, персонаж из Лимбуса, но по книге Грозовой перевал, где тоже была дикая охота)",200290,null],[200293,"2026-09-08T20:04:22",9,"Фермер что вас привез — Да вряд ли, всю жизнь его знаем. Темнит часто но человек хороший, моей двухюродной сестре за лекарством дорогим посылал. — *Не верит в догадки из за добродетели старосты, но и в штыки не принимает.*",200269,null],[200311,"2026-09-08T20:08:37",18,"- эт мы есшо поглядим...",200293,null],[200316,"2026-09-08T20:10:09",18,"Отводя Рена подальше от чужих ушей: \n- ещё раз волшбу сотворить можешь, найти след, мало ли какой жмур тут ошивается недалеко...",194458,null],[200345,"2026-09-08T20:27:58",20,"- Этим тоже обязательно займёмся, но сначала нужно все обсудить с остальными - есть у меня мысли по поводу происходящего *Задумчиво тянет Рен, бросая взгляд в сторону доков*",200316,null],[200364,"2026-09-08T20:34:44",18,"- Люпен всё ещё на крыше похоже можешь ему сигнал подать? А вот где Глотка не знаю, вроде к причалам летела...",194458,null],[200367,"2026-09-08T20:35:40",20,"\"Люпен, Вакс вы где?\" - мысленно связывается Рен с этими двумя",194458,null],[200869,"2026-09-09T08:29:41",22,"- Да, спасибо вам большое вы очень добры.\n\nВакс засмущалась.\n\n- Да, я очень люблю полет. Это просто невероятное ощущение, как ветер держит твои крылья и нести тебя вперед.. \n\nАаракокра мечтательно закрыла глаза. \n\n- Скажите, а чем вы любите заниматься, когда нет работы?\n\nДождавшись ответа, Вакс продолжила беседу.\n\n- Вас наверное наверное очень напугало все произошедшее, мы обязательно постараемся все уладить. Но нам нужна ваша наблюдательность! Замечали ли вы в последнее время что-то необычное?",200225,null],[200871,"2026-09-09T08:31:39",22,"🧠Я в аптеке, пью чай и беседую с дамой",200367,null],[200873,"2026-09-09T08:40:03",9,"Золушка — Говорят... мёртвые с кладбища ушли. И вот, у корчмы. — *Она кажется ничего не видела особо.* — Рыбный рынок последние дни не открывают, староста не пускает рыьаков, Бормотун в реку никого не пускает.\n\n*Золушка просто была работящей девушкой что жила одна, красивая но в простой поношенной олежде и то что она всегда умудрялась испачкатьсяс еще не женилась. Но люди к ней хорошо относятся.*\n\nЗолушка — Я люблю гулять под дождём и весенние полевые цветы. — *Улыбнулась она слегка разбавляя чай мёдом, судьба её не то чтобы нелегка, но при этом обычна. Она не та падчерица из сказки.*",200869,null],[200874,"2026-09-09T08:50:40",17,"/Я тут",194458,null],[200886,"2026-09-09T09:11:03",22,"- Спасибо вам большое за вашу помощь и большое открытое сердце!\n\nИскренне поблагодарила Вакс, вставая.\n\n- Но долг зовёт.\n\nКозодой допила чай и направилась в сторону товарищей, пересказав им по прибытии диалог с девушкой.\n\n- Как думаете, куда стоит направиться дальше?",194458,null],[200896,"2026-09-09T09:21:51",17,"\"Я следил издали, ничего толком не заметил подозрительного. Рен, что твоя птичка там?\"",200871,null],[200897,"2026-09-09T09:21:58",17,"/Помоему ты не сообщал что ворона грохнули",194458,null],[200899,"2026-09-09T09:22:59",20,"/сообщал, даже сказал что его магией убили",200897,null],[200900,"2026-09-09T09:23:07",20,"/из засады",194458,null],[200901,"2026-09-09T09:23:25",18,"Лют нервно посматривая на южные ворота:\n- если честно у них тут такая идилия, что закачаешься, староста душка, у которого все под контролем, обожаем толпой, вот пущай сам и разгребает...а я одним местом чую выйдут нам его интрижки боком.",194458,null],[200902,"2026-09-09T09:24:54",20,"\"Мертва, попала в засаду на причале\" - мысленно передает Рен. - \"Атаковали заклинанием\"",200896,null],[200903,"2026-09-09T09:26:28",17,"\"Я пойду проверю, где он летел когда его прибили?\"",200902,null],[200904,"2026-09-09T09:26:44",17,"\"На причале прямо?\"",194458,null],[200905,"2026-09-09T09:27:14",20,"\"Да. Он сел на крышу на причале, тебя туда стража скорее всего не пустит\"",200904,null],[200906,"2026-09-09T09:27:14",9,"//В доке, там где лодки строят и спускают на воду",194458,null],[200907,"2026-09-09T09:27:34",9,"//Лодочная)",194458,null],[200908,"2026-09-09T09:28:15",20,"/чё может соберёмся обсудим все что узнали и что делать дальше?",194458,null],[200909,"2026-09-09T09:28:55",22,"- Давайте доберёмся до причала и нормально его осмотрим? Мне кажется, что медлить опасно.. я переживаю за жизни местных.\n\nВакс нервно теребила перья и рыхлила землю когтями",194458,null],[200912,"2026-09-09T09:34:09",17,"\"Иду к вам\"\n\nСоскользнув с крыши дома попа Люпен направился к остальным",194458,null],[200913,"2026-09-09T09:34:19",20,"\"Ну, мертвые в доках скорее всего сейчас не представляют прямую опасность. А вот те что заныкались в самом поселение могут\"",200909,null],[200914,"2026-09-09T09:34:24",17,"/ Да, один не пойду кароче, давайте вместе все",194458,null],[200915,"2026-09-09T09:34:48",17,"\"Если в сортире мертвец, может быть где то в городе есть еще\"",200909,null],[200916,"2026-09-09T09:35:11",17,"\"Не учитывая основную толпу которая по следам шла к пирсу\"",194458,null],[200917,"2026-09-09T09:42:09",22,"- Тогда давайте просто пройдём по всей деревне, осматривая все подозрительные места по типу сараевч сортиров, погребов. Деревенька то маленькая совсем.",194458,null],[200918,"2026-09-09T09:42:39",22,"- Можем начать прямо отсюда, постепенно продвигаясь в сторону доков",194458,null],[200919,"2026-09-09T09:43:43",18,"- прочёсываем, сгоняем всех в амбар, палим... Кх-м, о чём это я?.. \nЛюта явно накрывают воспоминания о службе.",194458,null],[200920,"2026-09-09T09:45:37",18,"Подходит к колодцу заглядывает во внутрь... \n*видит ли Лют в нём воду?",194458,null],[200921,"2026-09-09T09:46:32",9,"*Где то внизу мелькают проблески воды, глубокий колодец.*",200920,null],[200922,"2026-09-09T09:49:01",18,"- Ну-ну... Тогда начинаем отсюда? Корчма, ратуша, дом попа...я в корчму))",194458,null],[200923,"2026-09-09T09:49:44",18,"* неспешно обходит здание по кругу осматриваясь по сторонам...",194458,null],[200924,"2026-09-09T09:50:27",17,"— Давайте на рыбный рынок, оттуда можно ближе подобраться не привлекая внимания.\n\nЛюпен быстрым шагом нагоняет остальных",200918,null],[200925,"2026-09-09T09:52:32",22,"- О, у меня есть идея.. \n\nВакс начинает шебуршать в подсумках и победоносно достает какой-то подсушено-подтухший мясной снек.\n\n- Надеюсь, я не налажаю.. снова. Ну-ка, помогите мне его привязать, давайте попробуем раздразнить кого-то, кто может быть в колодце?",200920,null],[200926,"2026-09-09T09:53:19",22,"\"Боги упасите, если я уроню туда свой подтухший кусок мяса.. сраться вся деревня будет дальше чем видеть.. а сортир то сгорел..\"\n\nДумала нервничающая ааракокра",194458,null],[200928,"2026-09-09T09:54:09",9,"//Опиши что ты делаешь, а еще держи вдохнову",194458,null],[200929,"2026-09-09T09:54:24",9,"//.",194463,null],[200933,"2026-09-09T10:07:00",22,"Вакс аккуратно обвязывает мясной снек верёвкой, несколько раз проверяет узел и, выглянув за край колодца, начинает медленно опускать приманку вниз. \n\nОна придерживает верёвку, постепенно разматывая её, и напряжённо вслушивается в темноту.\n\n- Ловись рыбка большая да тухлая.",194458,null],[200934,"2026-09-09T10:07:08",22,"//думаю тут ловкость рук",194458,null],[200935,"2026-09-09T10:07:23",22,"/r +6",194458,null],[200937,"2026-09-09T10:07:27",22,"Блять",194458,null],[200939,"2026-09-09T10:08:01",22,"//это слишком эпично, чтобы перекидывать",194458,null],[200940,"2026-09-09T10:08:26",22,"Это вот прямо то, что ожидаешь от такой идеи😂//",194458,null],[200941,"2026-09-09T10:09:38",9,"*Вакс за что-то зацепилась снизу, не вытащить.*",194458,null],[200942,"2026-09-09T10:10:25",9,"*К колодцу подходит баба с пустыми ведрами.*\n\n— Что вы... делаете?",194458,null],[200943,"2026-09-09T10:11:09",9,"//Кто ещё возле колодца? Кто вообще чем занят, описывайте, буду отвечать.",194458,null],[200945,"2026-09-09T10:13:48",22,"Вакс на мгновение замирает, всё ещё держа верёвку в руках, и виновато улыбается\n\n-Э-э… мы тут… воду достаём?\n\nОна бросает взгляд на мясо, болтающееся в колодце.\n\n- Просто немного нестандартным способом. Отойдите, пожалуйста!",200942,null],[200946,"2026-09-09T10:15:13",9,"*Мяса внищу уже не видно а веревка в воде. Женщина странно косится на Вакс и ставит коромысло, ждет. Она пришла набрать воды.*",200945,null],[200947,"2026-09-09T10:20:15",22,"Вакс дергает за верёвку, пытаясь вытащить.\n\n🧠попробуйте увести женщину, пока я пытаюсь вытащить, веревка застряла.. думаю тут опасно",194458,null],[200948,"2026-09-09T10:26:17",9,"//Атлетика сл 20 чтобы вытащить верёвку",200947,null],[200949,"2026-09-09T10:27:55",18,"Вернувшийся после обхода корчмы Лют не совсем понимая что происходит, но видя, что положение щекотливое, проходит мимо селянки прокручивая кистью боевой молот и глядя исподлобья говорит:\n- шли бы вы отсюда, следствие идёт, а ну как умертвия за из колодца на вас кинутся, да пообглодают! \n//запугивание?",194458,null],[200950,"2026-09-09T10:28:10",20,"\"Ну...я попробую\"\n\n- Уважаемая госпожа *Рен подходит к женщине, улыбаясь*\n\n- Могу ли я вас немного расспросить, пока мы все равно ждём? *Он указывает чуть в сторону от колодца, на заваленку где можно присесть*",200947,null],[200951,"2026-09-09T10:31:23",9,"*Бабонька смотрит на пацана, потом на солдата что ей угрожает.*\n\n— Знаете... я наверное через пол часика подойду...\n\n*Берёт коромысло с пустыми ведрами и уматывает.*",194458,null],[200952,"2026-09-09T10:34:45",18,"- Баба с возу...ну что, зацеп, тянем-потянем?",194458,null],[200954,"2026-09-09T10:36:41",17,"— Давайте вместе\n\nЛюпен тоже помогает вытягивать",194458,null],[200955,"2026-09-09T10:37:42",9,"//В четвером? Тогда тот у кого сильнее всего атлетика с преимуществом и +2д4 помощь от двух лишних помощников, проверка разовая и результат",194458,null],[200956,"2026-09-09T10:41:35",22,"/r +1",200948,null],[200958,"2026-09-09T10:41:55",17,"/мы тебе помогаем!)",194458,null],[200959,"2026-09-09T10:42:20",22,"//не увидела ласт сообщение, мб кто посильнее будеь",194458,null],[200962,"2026-09-09T10:47:17",17,"/Давай еще взлетай",194458,null],[200963,"2026-09-09T10:47:18",9,"*Сейчас немного за полдень, часпик, люди основном заняты а зеваки разбрелись по делам, только пару человек наблюдают за тем что происходит со своих огородов краем глаза и женщина смоталась.*",194458,null],[200964,"2026-09-09T10:47:26",17,"/ Клянчим преимущество!",194458,null],[200965,"2026-09-09T10:47:44",9,"//преимущество и 2д4 сверху",200955,null],[200968,"2026-09-09T10:51:54",18,"//у меня сила 16+3 мне что кидать?",194458,null],[200969,"2026-09-09T10:52:24",9,"//Атлетику кидай и +2д4, всей толпой репу тяните",194458,null],[200970,"2026-09-09T10:52:58",18,"/roll d20+3+2+2",194458,null],[200972,"2026-09-09T10:53:52",9,"//Не так чутка, но думаю все равно хватит)",200971,null],[200974,"2026-09-09T10:54:26",22,"//ааа я тормозок, извините",194458,null],[200975,"2026-09-09T10:56:48",9,"*Веревка натянулась как струна когда её пытались вытащить и \"треск\", вы успешно порвали верёвку, половина с мясом осталась в колодце, а вы попадали на пол с другой половиной. Похоже узел зацепился намертво внизу за какой-то штырь или что-то подобное.*",200971,null],[200976,"2026-09-09T10:58:29",18,"- твоим богам душу матерь...",194458,null],[200977,"2026-09-09T10:59:26",18,"*встаёт отряхивается, звеня железом, помогает встать остальным...",194458,null],[200979,"2026-09-09T11:00:40",18,"- пошли к хренам в кабак, тут похоже пока доброй кружечкой пива не смочишь, дело не двинется... \nИща поддержку заглядывает в глаза товарищам...",194458,null],[200982,"2026-09-09T11:05:32",22,"- Давай деру отсюда. Не забудьте, что пить отсюда не рекомендуется!\n\nВакс поспешила прочь за соратниками.\n\n- Нам ещё осматривать дальше. Так в кабак или на рынок?",194458,null],[200983,"2026-09-09T11:10:55",20,"*Рен заглядывает в колодец, нет ли там случайно тоже ауры некротики...*",194458,null],[200985,"2026-09-09T11:13:17",9,"*Не чувствуется, кажется в колодце ничего небыло, до того как туда обранили кусок гнилого мяса вместе с верёвкой.*",200983,null],[200986,"2026-09-09T11:15:45",18,"Тяжело вздыхает... \n- но после рынка однозначно, обед-с! \nПервым двигает к рынку быстрым шагом, злой, голодный и без пива...",200982,null],[200987,"2026-09-09T11:17:50",20,"- Я тоже был бы не против отдохнуть... часочек *вздыхает пацан, прикидывая где удобней будет устроить ритуал вызова фамильяра*\n\n- Но пока я ещё вижу ауры давайте пройдемся - может найдем ещё одну мертвую потеряшку. И нам улика для осмотра и для местных больше доказательств что мы не врем",194458,null],[200988,"2026-09-09T11:23:41",18,"*останавливается у входа на рынок, оглядывается назад, ожидая остальных...",194458,null],[200989,"2026-09-09T11:24:14",20,"*Рен тоже подходит, ждёт и оглядывает местность на ауру*",200988,null],[200990,"2026-09-09T11:25:28",20,"- Надо будет посмотреть, нет ли тут подходящих благовоний ...*бормочет он под нос, мысленно упрекая себя за то, что взял только один запасной комплект*",194458,null],[200991,"2026-09-09T11:28:33",18,"- так ничего не чувствуешь?",200990,null],[200992,"2026-09-09T11:28:36",18,"* мы что-то видим подозрительное на рынке?",194458,null],[200995,"2026-09-09T11:34:57",9,"*Рыбный рынок пуст, всех прогнали ещё позавчера, стража с пирса следит за вами.*",194458,null],[200997,"2026-09-09T11:38:32",22,"Вакс уверенно следует за Реном, доверяя его чутью",194458,null],[201002,"2026-09-09T11:46:41",20,"/Рен что-то чувствует?",194458,null],[201003,"2026-09-09T11:47:04",9,"//Так, я отвлекся, что вы проверяете?",194458,null],[201004,"2026-09-09T11:47:36",20,"/зашли на рынок, Рен высматривает ауры, а остальные наверное следы или просто что-то подозрительное",201003,null],[201009,"2026-09-09T11:50:47",9,"*Только из пирса веет некротикой, холодком по коже. Ты еще замечаешь что стража смотрит найболее настороженно именно на тебя, староста возможно предупредил их что Рен может быть колдуном.*",201004,null],[201011,"2026-09-09T11:51:47",17,"/Видел такое в ходячих мертвецах))",200975,null],[201013,"2026-09-09T11:52:24",17,"/Но там половина зомби осталась в колодце))",194458,null],[201015,"2026-09-09T11:52:43",22,"/я поэтому и решила сделать заявку, тоже об этом вспомнила",201013,null],[201016,"2026-09-09T11:53:09",17,"/Надо было себя выдвинуть в качестве добровольца) Как Глен)",194458,null],[201018,"2026-09-09T11:54:10",17,"Люпен приглядывается может тут есть особые воровские знаки или подобное. Он знает, как их читать",200995,null],[201019,"2026-09-09T11:57:01",9,"*Нет воровских знаков, есть какие-то близ самих лавок, но там лишь указанно что продавец краденым, скорее всего проездом, в такой небольшой деревне воров особо не водится на первый взгляд.*",201018,null],[201020,"2026-09-09T12:01:07",17,"Внимательно присматриваюсь к крытому ангару лодочной. Прохожу мимо стражей не нарушая их личные границы",194458,null],[201021,"2026-09-09T12:03:26",9,"— Эй ты! К лодочной и пирсу нельзя. — *Люпена предупреждают, один из стражников стает на пути.*",194458,null],[201022,"2026-09-09T12:05:35",18,"Подхожу к Люпену и обращаюсь к стражникам:\n- мы тут по поручению головы вашего, мертвяков стало быть ищем и сюда не просто так заглянуть решили...",194458,null],[201025,"2026-09-09T12:10:44",9,"*Они вообще не реагируют, просто переглянулись.*\n\n— Велено не пускать никого, вас тоже.\n\n— Уходите.\n\n*Староста выходит из доков на шум, видно что ваше присутствие его раздражает.*\n\nСтароста — Вы не отстанете просто так да? Возомнили себя детективами или героями не ведающими что творят. — *Он лишь вздохнул и махнул рукой на лодки, говорил не громко.* — Вы тут не просто так, догадались что происходит ведь. Если вас интересует лишь награда, то я готов вам заплатить за дело иного рода.",194458,null],[201026,"2026-09-09T12:10:47",17,"Поднимаю руки в мирном жесте\n\n— Тише, тише",201021,null],[201027,"2026-09-09T12:14:58",18,"- опа, вот это дело! Бабки на бочку и расходимся! \nЛют, сияет как начищенный самовар...",201025,null],[201028,"2026-09-09T12:15:33",18,"*оглядывается на сопартийцев ища поддержки...",194458,null],[201032,"2026-09-09T12:21:46",9,"Староста — Просто так платить не собираюсь. — *Он показал на перекушенную лодку пополам.* — Прогоните Бормотуна и лодки спокойно отплывут куда положенно, заплачу 300 золотых. Дело с пропавшими мертвецами можете не брать в расчет вовсе, все это чтобы народ подуспокоился, не всё люди должны знать чтобы спокойнее спать.",201027,null],[201036,"2026-09-09T12:25:03",18,"- и за мертвяков 240, раз с ними всё так благополучно разрешилося))",194458,null],[201037,"2026-09-09T12:26:49",9,"*Качает головой.*\n\nСтароста — Это деньги людей, они вернутся им в карманы. Я плачу из своего.",201036,null],[201039,"2026-09-09T12:28:22",18,"- а если мы доложим куда нужно, что староста поднятых сокрыл, и причастен к некромантии...",194458,null],[201040,"2026-09-09T12:31:39",20,"/капец что я пропустила...",194458,null],[201041,"2026-09-09T12:31:56",9,"Староста — Посмотри как хорошо живет деревня. — *Он показывает рукой, на новые крыши, тенты, чисто.* — Здесь водятся деньги, в такой глуши, знаешь почему? Потому что я все делаю для этого, своей добротой вы разрушите людям жизни. Сможешь ли ты потом сказать что сражался за бравое дело, солдат? — *Он рассмеялся.* — Живым нужно жить, мертвым уже все равно что с ними.",201039,null],[201042,"2026-09-09T12:34:46",9,"*Старосту похоже не просто так слушают и не подозревают обычные люди. Он для них благодетель поднявший деревню на ноги, даже если они не знают о методах.*",194458,null],[201043,"2026-09-09T12:38:10",22,"Вакс рассматривает обувь старосты.\n\n Каблук похож на тот след что она увидела?",194458,null],[201044,"2026-09-09T12:39:02",9,"*Все те же красные кирзовые сапоги, гомнодавы без каблука.*\n\n//Ты прошлый раз на нём их же видела",201043,null],[201045,"2026-09-09T12:39:22",20,"*Рен прикидывает в уме. В целом предложение звучит ну... не так плохо. Методы такого управления он видел и не видит в них вообще ничего странного, типичные и эффективные, если осторожно применять*\n\n*Да и возможность пообщаться с тем возможным магом некромантом...заманчива. можно попробовать договориться о встрече, если разберутся с монстром*\n\n\"Что думаете?\" - спрашивает он мысленно остальных",194458,null],[201052,"2026-09-09T12:48:28",18,"- думаю нужно сюда дознавателя вызывать и добрую наëмную роту, да порядок наводить от сих до сих...",194458,null],[201054,"2026-09-09T12:49:41",9,"//Это вслух?",201052,null],[201055,"2026-09-09T12:50:05",17,"Шепотом Люпен говорит Люту\n\n— Не кипятись, Лют. Он тёртый калач, рыльцо у него в пушку, а на руках у нас ничего нет. Нас или взашей или на вилы. Давай лучше про бормотуна расспросим",201052,null],[201056,"2026-09-09T12:50:09",22,"- Раз одиночек не удалось найти, давайте разберёмся с монстром, может кто-то на шум прибежит",194458,null],[201057,"2026-09-09T12:50:44",17,"\"Если староста мертвечиной торгует ему сейчас жизнено необходимо, чтобы бормотуна истребили, иначе у него товар вонять начнёт\"",194458,null],[201058,"2026-09-09T12:51:53",9,"//Что из этого вслух, у Люпена и Рена то понятно \"все что через телепатию в скобочках\" а у вас?",194458,null],[201061,"2026-09-09T12:56:26",17,"/Вакс сделала",201058,null],[201062,"2026-09-09T12:56:26",20,"\"Это верно, я бы не шел на такой прямой конфликт. В доках ещё похоже есть маг некромант - сильный или опытный, а может обвешанные свитками или магическими предметами, раз смог столько за раз поднять. Слишком рискованно нападать или провоцировать\" - там же мысленно, всем своим",201055,null],[201071,"2026-09-09T13:03:46",18,"//да",201054,null],[201073,"2026-09-09T13:05:40",18,"*Лют насвистывая удаляется...",194458,null],[201078,"2026-09-09T13:08:45",9,"Староста — Наемников, из своего кармана? — *Лишь усмехнулся вслед. Деревня то меж Веспиралью и Вальдхеймом, ничейная считай, никому не нужная, даже название унылое как болото на котором та стоит.*",201052,null],[201090,"2026-09-09T13:16:34",18,"*молча продолжает идти к центру поселения",201078,null],[201091,"2026-09-09T13:17:19",9,"//Ты отделяешься от группы? Что планируешь делать?",201090,null],[201092,"2026-09-09T13:17:49",18,"//иду в корчму",201091,null],[201093,"2026-09-09T13:19:34",17,"— Давайте не будем горячится. Бормотун вас одолел? Расскажите подробнее, что за тварь? Я охотник, мои друзья тоже бывалые наёмники. Может сумей избавить вас от напасти",194458,null],[201094,"2026-09-09T13:19:42",9,"*В корчме почти никто не сидит, пару пьяниц. Сам корчмарь. Люди основном сидят злесь после работы. Есть кто-то приезжий, какой-то торгаш, и пьяница, скорей всего пьяница это кладбищенский сторож, сидит уже никакой, пиво пьет, на поясе хороший увесистый кошель.*",201092,null],[201095,"2026-09-09T13:19:49",17,"Люпен говорил громко, чтоб староста слышал отчетливо",194458,null],[201103,"2026-09-09T13:25:16",9,"Староста — Хоть у кого то голова на плечах. — *Напряжение его слегка спало и он начал описывать монстра.*\n\n*Бормотун, это говорящая жаба с красными светящимися глазами и острыми как бритва зубами, он живет вниз по реке, как к Веспирали плыть. Обычно достаточно было просто не выходить на реку ночью, но когда они пытались отправить лодки по ней позавчера, он напал и раскусил одну из них. Бормотуном эту большую тварь называют помому что она будто бормочет в голове, некоторые слышали его голос, кто выжил после встречи.*\n\nСтароста — Чай бы всё давно улеглось, если бы не Бормотун, он просто не пускает проплыть. Что нашло на него, не знаю.",201093,null],[201105,"2026-09-09T13:26:20",9,"Староста — Убивать его не обязательно, просто спугнуть на время или успокоить, отвлечь. Чтобы лодуи проплыли. Тварь сама когда нибудь успокоится.",194458,null],[201115,"2026-09-09T13:31:52",17,"— Надо бы место нападения осмотреть, о твари многое говорит, как она охотится. Дозвольте занурнуть в воду где гадёныш лодку раскусил?\n\n\"Ну давай толстопуз, покажи как ты недоволен таким вопросом, а на дне могут куски мертвецов лежать. Авось будет улика против тебя\"",194458,null],[201117,"2026-09-09T13:32:02",17,"Люпен пристально следит за ответом старосты",194458,null],[201118,"2026-09-09T13:32:07",17,"/r +2 Проницательность",194458,null],[201120,"2026-09-09T13:32:08",18,"*заказывает пожрать, выпивку, проходя мимо смотрителя кладбища, задевает его кошель, плюхается напротив, делает добрый глоток пива и глядя в глаза:\n- не слабо у тебя монеты звонкой для забулдыги, смотрящего за кладбищем, хорошее вы тут дело организовали, мертвяками с Веспиралью ентой торговать...",201094,null],[201127,"2026-09-09T13:38:01",22,"-АПЧХИ! \n\nГромко чихает Векс в ухо старосте. Чтобы вывести его из эмоционального равновесия.\n\n//помощь(?)",201117,null],[201131,"2026-09-09T13:44:47",9,"Пьяный сторож — Шо ты шепчешь. — *Он очень пьян и не вкуривает о чём речь, даже слова эти собрал едва в кучу.*",201120,null],[201135,"2026-09-09T13:47:11",9,"Староста — Сиотрите, что вы, смотрите. — *Он показывает раскушенную лодку, она лежала на виду, следов мертвецов нет. Походе он специально убрал следы и вытащил на берег чтобы народ не сильно возмущался что к пирсу не плдпускают. Глаза видят и бояться.*\n\n*Бормотун размером его почтение, лодку перекусил, даже есть следы от зубов.*\n\n//Что ты хочешь проницательностью узнать?)",201129,null],[201144,"2026-09-09T13:56:48",18,"- мдаа, говорил хер хауптман, наше дело простое не лезь кудой не надать... \nБоёв по быстрому харчи и допив в два глотка кружку пива вышел на улицу, настроение несмотря на сытость и легкий хмель не появилось совсем, в грустных мыслях добрел до колодца...",201131,null],[201146,"2026-09-09T13:58:14",9,"— Вода горьковата, тьфу ты. — *Кто то отпил с ведра у колодца, сплюнул да пошёл.*",201144,null],[201151,"2026-09-09T14:07:11",18,"Провожая селянку взглядом, себе под нос:\n- похоже скоро в тавернах барды будут петь о селе, жители которого связались с некромантией да и попередохли все незатейливо в муках поносных...трудами спасителей праведных...кх-м.",201146,null],[201182,"2026-09-09T14:25:13",17,"/Ну вот узнал, что действительно та мприбирались. В идеале я хотел подтвердить, что он раздраженно запретит, я подумал, что можно кусок мертвеца вытащить со дна и предъявить возможно",201135,null],[201183,"2026-09-09T14:25:51",17,"— Вижу вам очень нужно, чтобы бормотун поскорее перестал вас беспокоить. Как насчет накинуть к награде \"за срочность\"?",201135,null],[201186,"2026-09-09T14:27:10",17,"— И мы отправимся не медля",194458,null],[201187,"2026-09-09T14:28:20",9,"Тучный староста — Хорошо, но деньги тогда опосля. — *Готов 350, не более дать.*",194458,null],[201235,"2026-09-09T14:56:40",17,"— По рукам.\n\nЛюпен побежал быстро собирать всех, чтобы отправиться по берегу вниз по реке на охоту",194458,null],[201236,"2026-09-09T14:56:47",17,"/Так что может гоу погеройствуем?",194458,null],[201238,"2026-09-09T14:58:13",20,"/расследование не задалось, хоть хтонь речную попинаем",201236,null],[201241,"2026-09-09T14:58:50",17,"/Да че, он их там в лодочной держит готовыми к отправке, каблучок это некромант, а толстопуз староста просто карманы набивает на продаже тел в веспираль",194458,null],[201242,"2026-09-09T14:58:57",17,"/Больше я думаю тут и нет ничего",194458,null],[201257,"2026-09-09T15:04:12",18,"/вперёд",194458,null],[201265,"2026-09-09T15:05:04",18,"- вперёд! На встречу приключениям! \nСтарчески крехтя идёт за всеми...",194458,null],[201268,"2026-09-09T15:05:53",18,"- как только деньги получаем, валим!",194458,null],[201275,"2026-09-09T15:06:42",17,"Люпен пересказывает всем информацию, кто не слышал\n\n— Охота на монстра куда более понятна чем городские интриги.",194458,null],[201276,"2026-09-09T15:07:04",18,"- я то хоть поел, если и помру, то сытым)) ха-ха... \nНервно рассмеялся...",194458,null],[201280,"2026-09-09T15:07:51",18,"- жирно живут, это видят, дождутся набега...",201275,null],[201291,"2026-09-09T15:11:52",22,"- Мои перья готовы к бою.",194458,null],[201339,"2026-09-09T15:37:25",18,"- странно что они сами эту чуду-юду не подвинули, у них 6 или даже 8 оружных людей, пусть и не самых мастеровитых, да этот шельмец из некромантов похоже...а всё ли нам рассказал лысый хер, особенно учитывая, что разок он нам по сусалам проводил...",194458,null],[201345,"2026-09-09T15:43:35",18,"- опять же, готовы были заплатить чуть не 600 золотом, а наняли четверых, хотя могли позволить больше...",194458,null],[201349,"2026-09-09T15:46:06",9,"//Такс, что у нас в итоге господа. Я оч прошу прощение но как на зло тут со всех сторон отвлекаюсь.",194458,null],[201353,"2026-09-09T15:47:16",18,"//мы геройски решили геройски огребсти, ну либо победить",201349,null],[201355,"2026-09-09T15:52:02",18,"- а все уверены что это тварь там одна? Имел кто дела раньше с ними?",194458,null],[201356,"2026-09-09T15:52:25",9,"//Кого спрашиваешь.",194458,null],[201357,"2026-09-09T15:58:33",20,"/можно что-то попытаться припомнить о таких монстрах по описанию старосты? Может Рен в книгах где читал или среди наемников слышал",194458,null],[201358,"2026-09-09T16:00:00",9,"//Рен мог бы знать что эта тварь не из оьычного бестиария, ведь там её нет...",201357,null],[201360,"2026-09-09T16:09:55",20,"/так и запишем, местная мутировавшая хтонь ✍️",201358,null],[201361,"2026-09-09T16:11:09",22,"- Чего задумались? Погнали! По ходу разберемся",194458,null],[201362,"2026-09-09T16:14:31",18,"- и кто у нас самый смелый в воду лезть? Кстати если вода более менее прозрачная и не глубоко, то может и с небес её заметить получится...",194458,null],[201364,"2026-09-09T16:16:08",18,"//Да это я так просто вещаю, в слух оно думается лучше если голова отбита))",201356,null],[201365,"2026-09-09T16:18:58",9,"*Вода мутновата, околоболота.*",194458,null],[201367,"2026-09-09T16:20:23",17,"— По берегу пойдём",201362,null],[201374,"2026-09-09T16:25:01",22,"Вакс покосилась на воду.\n\n- Если честно.. я бы не хотела тут купаться..",194458,null],[201381,"2026-09-09T16:27:09",9,"//Такс, я так понял вы пошли вниз по реке через южные болота через которые приехали в поисках следов?",194458,null],[201386,"2026-09-09T16:28:40",17,"Люпен зарится на воду с опаской. \n\n— Тварь водная если жаба, но может отдыхать и греться на суше. Найдем логово",194458,null],[201390,"2026-09-09T16:31:00",17,"/r +3 Люпен ищет следы. Выживание",194458,null],[201395,"2026-09-09T16:31:26",20,"/батя следопыт за работой",194458,null],[201401,"2026-09-09T16:33:01",18,"- ну чë тама, нашукал чë?",194458,null],[201406,"2026-09-09T16:33:49",18,"- учитывая шо она на лодки кидыется, может нам пошуметь, она сама и прискачет...",194458,null],[201414,"2026-09-09T16:35:04",20,"- Мне больше интересно что это существенно могло так расшевелить, раз у него такой необычный всплеск агрессии",194458,null],[201430,"2026-09-09T16:38:04",18,"- мертвичинку может любит? Хер хауптман помнится травил байки на счёт сомов любящих утопленников...",201414,null],[201436,"2026-09-09T16:39:30",9,"*Когда вы вышли из южных ворот вдоль реки, Люпен внимательно прочесал глазами местность, он видел щепки местами, или углубление, невысокие кручи мелкие грязные пляжи из песка и след, след большой, оно вылезает иногда, но с этой стороны больше их небыло. А что с другой?*\n\n*За широкой рекой с противоположного берега камышей, и хоть едва заметно, но видно несколько борозд словно что-то очень крупное их пересекало, по ним можно сказать в какой примерно части реки сидит Бормотун.*\n\n*А еще у реки рыбачит рыбак и ловит рыбу с вашего берега. Что-то подсказывает Люпену что на другую сторону люди редко выбираются, поэтому и не знают что там может находится логово этой жабы? Если это конечно просто лягушка переросток.*",201391,null],[201440,"2026-09-09T16:41:49",18,"*подходит к рыбачку, присаживается, неспешно набивает трубочку, раскуривает:\n- клюëт шо, а?",201436,null],[201444,"2026-09-09T16:44:08",9,"Рыбак — Смари. — *Открывает ведро с лининой и карасями, пару карпов.* — Мало, мелкие, эх. — *Он вздыхает.* — Сетями больше, на воду не пускают. С другой стороны, помереть тожа не хочется.\n\n*Закинул удочку еще раз, да подальше.*",201440,null],[201445,"2026-09-09T16:45:11",18,"- не сыкотно то тут рыбку удить, а ну как какая водяная падла выскочит и утащит под воду и поминай как звали...",194458,null],[201448,"2026-09-09T16:46:03",18,"- кстати, а на тот берег в брод можно, али только лодкою?",194458,null],[201466,"2026-09-09T16:51:12",17,"— Мужик, подскажи, где тут вброд можно перейти?",201444,null],[201469,"2026-09-09T16:52:11",9,"Рыбак — Не, я везучий. — *Лишь хмыкнул.*",201445,null],[201473,"2026-09-09T16:53:29",9,"Рыбак — Пять золотых, раскажу что знаю, да совет дам. — *Он рассмеялся.* — Не серчайте, мне детей кормить, а вы приезжие, завтра уйдёте поди, ни подсобите ничем, а так хоть деньгами.",194458,null],[201497,"2026-09-09T17:00:37",18,"- э, уважаемый, ты не понял, вашему поселению угрожает опасность, если эта тварь, за которой мы охотимся, икру метнет, показывает тому размер икрины с кулак, кулак при этом маячит у рыбака прямо перед носом, вам тут всем житья не будет, одно дело одну лодку тю-тю, а так вся торговля по воде по детородному органу пойдёт и порыбачить тебе уж точно тут более не доведётся, так что давайка выкладывай всё что знаешь.",201473,null],[201498,"2026-09-09T17:00:58",18,"//запугивание?",194458,null],[201502,"2026-09-09T17:03:28",9,"//С помехой",194458,null],[201504,"2026-09-09T17:03:59",9,"/roll +d20+2 мудрость местного, его байками не напугаешь, тертый качанс но авось",194458,null],[201507,"2026-09-09T17:04:28",9,"//На запугивание с помехой больше 16-ти если выкинешь — запугаешь",194458,null],[201511,"2026-09-09T17:05:41",18,"/roll d20+1+2",194458,null],[201515,"2026-09-09T17:06:15",9,"//Помеха, еще бросок",194458,null],[201536,"2026-09-09T17:11:39",18,"/roll d20+1+2",194458,null],[201540,"2026-09-09T17:12:41",18,"-подавись. кидаю ему монеты в лицо.",194458,null],[201552,"2026-09-09T17:18:11",9,"Рыбак — Денег жалко, так и скажи. — *Он лишь рассмеялся и поднял их. Не гордый.* — Ну раз всё же заплатил, слушай.\n\n*Он расказывает что вверх по воде как с северных ворот идти, есть домик у реки в лесу, в лесничей сторожке, лодка там старая есть если с лесниками договориться. Ну или здесь, чуть ниже по воде плот детский, сейчас не сезон, полноценный брод появляется ток весной и осенью на короткое время, река полноводная, что поделать.*\n\nРыбак — Иначе только в плавь. — *Он положил монеты в карман, да похлопал, радый зароботку.* — Не злись добр человек, я детям сегодня думаю медовых леденцов принесу, скажу заяц принёс, у медведя украл, да им передал.\n\n*Вообще не стал хуже относиться к Люту за его поведение.*",194458,null],[201569,"2026-09-09T17:24:29",18,"- ага, скажи-скажи, да добавь, что если мы не сдюжим, сожрут вас всех жабороты в следующем  году...если конечно староста раньше всех до цугундера не доведёт своими играми с мертвичиной...\nНеспешно удаляется.",194458,null],[201572,"2026-09-09T17:25:20",18,"*идёт вдоль берега высматривая плотик",194458,null],[201575,"2026-09-09T17:25:46",9,"Рыбак — Хех, ладно. — *Он возврашается к рыбалке и со смехом закилывает удочку подальше.* — Ловись рыбка, большая да еще больше!",194458,null],[201577,"2026-09-09T17:26:20",9,"/roll +d20 удача рыбака считайте с везунчиком)",194458,null],[201583,"2026-09-09T17:27:25",9,"*Следующая рыбина которую рыбак вытащил была пятикилограмовой щукой что только что поймала карася которого тот вытаскивал на берег.*",201578,null],[201584,"2026-09-09T17:28:00",20,"/я уж думала сейчас мертвяка вытащит",194458,null],[201591,"2026-09-09T17:28:59",9,"//Ну, думаю если бы там крит, бормотуна вам не надо было бы искать 😏👌",194458,null],[201598,"2026-09-09T17:30:17",9,"//Что делаете дальше",194458,null],[201609,"2026-09-09T17:32:41",20,"- Что дальше будем делать? Пойдем подальше до лодки или к плоту? *Спрашивает Рен*\n\n- Ну или Вакс нас по одному просто перенесет на тот берег \n/🤔",194458,null],[201614,"2026-09-09T17:33:25",9,"//То чувство когда Лют узнаёт что Вакс могла их перетащить, реально везучий рыбак, что скащать)",201609,null],[201630,"2026-09-09T17:36:56",18,"- Силенков то у неё хватит, я со всем скарбом вешу больше 200 фунтов...",201609,null],[201642,"2026-09-09T17:39:30",9,"//Эх, ладно, снова пауза. Николай с полиной в кукольном домике основном. До завтра навернре",194458,null],[201650,"2026-09-09T17:41:05",17,"/Нааааа маленьком плотуууууу",201552,null],[201653,"2026-09-09T17:41:44",17,"— Вплавь нельзя, тут говоря бормотун поселился, он недавно лодку пополам перекусил. Так что ни какого плота",194458,null],[201656,"2026-09-09T17:42:15",9,"//Рыбаку говоришь?",201653,null],[201657,"2026-09-09T17:42:31",17,"— Да и лодка тоже... А моста нет на ту сторону?",194458,null],[201658,"2026-09-09T17:42:58",20,"*Рен смотрит на Вакс. На ее крылья. Ну решение очевидно, если она сможет перенести самого тяжёлого из них - Люта*",194458,null],[201668,"2026-09-09T17:44:19",9,"Рыбак — Моста нет. А бормотун тут сколько помню жил, о нём ещё дед расказывал. Правда мог толкнуть кого, лодку перевернуть или напугать лишь по ночам. Не сожрал ещё никого поди, а вот гоблины и урки всякие, это да, беда.",201657,null],[201673,"2026-09-09T17:45:40",20,"/а Люпину случайно не вспоминается та огромная жаба? Ну, которая \"мое болото, съебите отсюда\"",194458,null],[201676,"2026-09-09T17:46:44",9,"//Это точно не та, далеко достаточно эти два места но может сородичь)",201673,null],[201677,"2026-09-09T17:46:56",17,"— Так, а дед не говорил, что нельзя делать, чтоб бормотуна не беспокоить? Он сейчас как с цепи сорвался, буйствуйет!",201668,null],[201679,"2026-09-09T17:47:22",20,"/я больше к тому что если похожа, то может этот бормотун тоже говорящий)",201676,null],[201680,"2026-09-09T17:48:12",9,"Рыбак — Перекушенную додку я видел да. — *Подумал, соломенную шляпу поправил.* — Не шуметь и ночью огнем не светить. Лучше уж без фонаря к берегу прибиться, осторожно.",201677,null],[201685,"2026-09-09T17:51:04",17,"— А Бормотун тухлятину любит?",194458,null],[201698,"2026-09-09T17:56:34",9,"Рыбак — Чего не знаю того не знаю. Прикармливать не пробовал. — *Пошутил рыбак, вряд-ли бормотун раньше клевал на его прикормку, хотя рыбы точно тащатся от его наживки.*",194458,null],[201702,"2026-09-09T17:58:09",9,"*Улыбнулся едва заметно и сам. Было время и девки на него клевали, молодой был, но после женился.*",194458,null],[201709,"2026-09-09T18:00:54",17,"— Что ж делать нам на цт сторону надо. Ладно. Спасибо мужик. Пойдем к лестникам, лодочку просить",194458,null],[201714,"2026-09-09T18:03:10",9,"Рыбак — Удачи, Бормотун вверх по реке редко заплывает. Да и тут, даже следа его не видел. Толи нет его, толи другим не везёт. Если бы не расказы да лодка перекушенная ни в жизнь не поверил бы.",194458,null],[201722,"2026-09-09T18:05:09",9,"*Смотрит на воду, хмыкнул.*\n\nРыбак — Плавает где-то, на мою удочку еще ни разу не клевал. Интересно животину повидать и самому, хе хе.",194458,null],[201835,"2026-09-09T18:47:24",17,"— Там вон след его, а вон там камыша римят. Он тут неподалеку где то. Ты бы лучше сменил место. Ато жинка да дитятки без кормильца останутся",201722,null],[201837,"2026-09-09T18:47:43",17,"Люпен рыбаку показал все что нашел и предостерёг, негоже если за просто так сгинет",194458,null],[201853,"2026-09-09T18:53:31",9,"Рыбак — Пасиб мужик, поосторожнее буду. — *Он искренне поблагодарил, да дальше сидит на своём месте рыбном.*",194458,null],[201856,"2026-09-09T18:58:14",22,"- Вы тяжелые.. не донесу",201609,null],[201859,"2026-09-09T18:58:50",9,"//Пацана думаю дотянешь)",194458,null],[201860,"2026-09-09T18:59:00",22,"//ааракокра не летает даже со средним доспехом. Мужик врядли весит меньше доспеха",194458,null],[201890,"2026-09-09T19:08:00",18,"- Искушать судьбу на плотике желающих я так думаю что нет...двигаем на заимку?",194458,null],[201919,"2026-09-09T19:17:37",22,"- Давайте я низко полетаю над рекой, и попробую его рвздразнить как нибудь?",194458,null],[201942,"2026-09-09T19:24:31",18,"- было бы конечно неплохо выманить эту жабу на этот берег и дать бой на наших условиях...",194458,null],[202042,"2026-09-09T19:59:49",22,"Вакс взмахивает крыльями и летит над водой, выделывая всевозможные кульбиты,  чтобы спровоцировать рыбеху",194458,null],[202044,"2026-09-09T20:00:24",22,"/r +6 от Ловкости крыльев",194458,null],[202939,"2026-09-10T10:11:58",9,"//Ааракокры же спят и видят сны?)\n\n// \"Очень важный вопрос\"",202042,null],[203070,"2026-09-10T11:34:16",9,"*В какой то момент на Вакс наплывает знакомое ощущение, телепатия но слегка более агрессивная, от которой бы могла заболеть голова. Казалось будто кто по мозгам прошелся щеткой выуживая тайны. На мгновение будто из под воды сверкнули двое фонарей блюдец, багрово огненных, вертикальных как у змей или котов.*",202042,null],[203071,"2026-09-10T11:37:31",9,"*Рыбак аж присвистнул.*\n\nРыбак — Хорошо летит. — *Чего только не увидишь.*",202045,null],[203072,"2026-09-10T11:46:23",18,"*ненавязчиво примеряется молотом по затылку рыбака...",194458,null],[203073,"2026-09-10T11:47:26",17,"Люпен притаился в камышах и приготовил лук, чтобы выстрелить если тварь появится",194458,null],[203074,"2026-09-10T11:47:35",9,"//Преимущество, он полностью беспечен. Щас вас положит рыбак, ууда там монстр 😏👌",203072,null],[203124,"2026-09-10T12:34:31",22,"Вакс присмотрелась к воде",203070,null],[203125,"2026-09-10T12:34:36",22,"/r +5 внимание",194458,null],[203130,"2026-09-10T12:35:41",18,"//я не бью, я просто мало ли))",203074,null],[203135,"2026-09-10T12:37:53",9,"*Что-то там есть, мелькнуло пару раз, не разглядеть. Слишком мутная вода и глубоко.*",203126,null],[203202,"2026-09-10T12:58:24",17,"/ДУмаю нам нужно возвращаться на рельсы, плот или охотничья сторожка, бормотун на аракокру не клюёт",194458,null],[203208,"2026-09-10T13:05:21",20,"/поддерживаю - тут прям явный выбор - плот ближе но рисковей, лодка дальше и нужно договариваться но безопаснее",203202,null],[203213,"2026-09-10T13:08:08",9,"//Или пойти искупаться, придумать свой план, или выбросить все планы к чертям 😎",194458,null],[203219,"2026-09-10T13:10:38",20,"/пойти рыбачить",203213,null],[203251,"2026-09-10T13:55:14",17,"— Так! У меня есть план. Грузим на плот мяса и толкаем на реку, вон туда где тварь прыгала. Приманим и убьём, неча сиськи мять! Вакс, давай возвращайся",203213,null],[203252,"2026-09-10T13:58:27",18,"- Кто будет мясом?",203251,null],[203254,"2026-09-10T13:59:01",18,"- а если ему только мертвичину подавай?",194458,null],[203256,"2026-09-10T13:59:48",18,"- Короче, пошли плот искать, я геройски поплыву мочить падлюку.",194458,null],[203257,"2026-09-10T13:59:49",17,"— Можно вернуться на рыбный рынок и купить улов, или на охоту сходить. Главное на месте не стоять. Возражения есть?",194458,null],[203259,"2026-09-10T13:59:57",18,"//Река тут широкая?",194458,null],[203260,"2026-09-10T14:00:06",17,"— Я тебе сдохнуть помогать не буду, Лют. Мы даже еще не выпили",194458,null],[203264,"2026-09-10T14:04:34",20,"- С рыбного рынка сейчас всех выгнали, он совсем пуст был. Так что либо в кормче что-то брать, либо на охоту. На охоту пока звучит более надёжно, зная твое мастерство",203257,null],[203265,"2026-09-10T14:05:48",17,"— Да мне только всласть за косулями побегать и от кабанов попрятаться. Пойдём?",194458,null],[203274,"2026-09-10T14:08:02",20,"*Пацан кивает. Можно и травы повыглядывать по пути, никогда лишним не будет*",203265,null],[203277,"2026-09-10T14:08:45",17,"- Лют, пойдёшь?\n\n— Ваааакс! Ты слышишь? Сворачивайся!",194458,null],[203278,"2026-09-10T14:08:49",17,"/@lady_godzilla",194458,null],[203280,"2026-09-10T14:09:08",20,"/так то ещё с этой жабой можно телепатией побазарить, но это Вакс должна упомянуть что она чувствовала псионическое воздействие",194458,null],[203281,"2026-09-10T14:09:58",17,"/ Не совсем. Она должна знать язык",194458,null],[203283,"2026-09-10T14:11:58",22,"Летит обратно",203277,null],[203299,"2026-09-10T14:20:56",17,"/Такс мы идём на охоту, чтобы добыть тушу, чтобы погрузить на плот, чтобы привлеч бормотуна, чтобы его убить, чтобы получить награду, чтобы втерется в доверие, чтобы исследовать лодочную, чтобы найти доказательства против старосты и заказчика этого всего некромансткого пиздеца, чтобы быть героями",194458,null],[203309,"2026-09-10T14:27:48",18,"- Да, иду я, иду",203277,null],[203312,"2026-09-10T14:32:24",9,"*Достаточно широкая, но другой берег видно.*",203259,null],[203313,"2026-09-10T14:40:51",17,"Лес. Рожное пространство. Каждая травинка, каждое деревцо, восхитительны.\n\nЛюпен подошел к берёзе и обнял её немножко прижавшись лбом к коре.\n\n— Родная стихия. \n\n— Пора за работу. Кто найдёт следы зверя- тому ставлю сегодня вечером в корчме выпивку!",194458,null],[203314,"2026-09-10T14:41:05",17,"/r +3 Выживание на поиск следов",194458,null],[203317,"2026-09-10T14:41:58",9,"//Щас я соберусь и сяду вести, заактивничали мои хорошие)))",194458,null],[203320,"2026-09-10T14:45:36",20,"/r d20+2 Рен высматривает какие-нибудь целебные травы по дороге",194458,null],[203322,"2026-09-10T14:46:03",22,"Ааракокра же осмотрелась, по-птичьему дернула головой и сказала.\n\n- Мы просто слоняемся тут без дела. Это скучно, я лучше займусь другими делами. Удачи вам.\n\nИскренне пожелала птица и улетела.\n\n//персонаж покидает группу ввиду своего закрытия",194458,null],[203328,"2026-09-10T14:48:32",9,"//Сложность легче не станет, предупредил)",194458,null],[203354,"2026-09-10T14:57:47",9,"*Рыбак провёл вас глазами в лес. В поисках добычи, по тропам сборщиков. Рен собирал травы по дороге, болотистая местность этих краёв хоть и слегка неудобна, но богата на то что можно подсобрать.*",194458,null],[203355,"2026-09-10T14:57:58",9,"//Навыком каким?",203320,null],[203357,"2026-09-10T14:58:14",20,"/внимание",203355,null],[203363,"2026-09-10T15:00:19",9,"*Рен осматриваясь по сторонам видит растение которое точно находил в каком то справочнике.*\n\n// Материал для зелья лечения, заменяет компоненты на 10 зм для его крафта.",203321,null],[203370,"2026-09-10T15:02:50",9,"*Люпен искал слелы, но нашел кое что другое. Пробираясь через куст он заметил гоблина, гоблин тоже заметил незадачливого охотника.*\n\n*Глаза в глаза, нос в нос, между вами футов 10, мгновение и гоблин точно что-то предпримет или закричит если Люпен резко дёрнется.*",203315,null],[203376,"2026-09-10T15:03:52",9,"*До встречи с этим зелёным лесным жителем вам удалрсь пройти целых пол мили в чащу, хоть и возле тропки.*",194458,null],[203381,"2026-09-10T15:07:30",17,"Люпен сигает в кусты и шипит остальным\n\n— Прячтесь!",194458,null],[203382,"2026-09-10T15:07:38",17,"/r +4 Скрытность",194458,null],[203386,"2026-09-10T15:08:09",9,"//Опиши боженька как ты исчез",203383,null],[203394,"2026-09-10T15:09:27",17,"Люпен натренерован скрываться в лесу\n\nон как ползучий змий пал на землю, как только завидел опасность и ПУФ его нет",194458,null],[203397,"2026-09-10T15:10:36",17,"/Могу я выстрелить по гоблину?",194458,null],[203400,"2026-09-10T15:11:55",9,"*Гоблин моргнул, и привстал, вот перед ним был человек, а теперь нет! Секунда замешательства.*\n\n//Давай",194458,null],[203402,"2026-09-10T15:12:14",17,"/Сек проверю лук",194458,null],[203407,"2026-09-10T15:13:24",17,"/r 3d20+1 Выстрел пошел с натяжечкой!",194458,null],[203411,"2026-09-10T15:13:46",17,"/r d6+10+3+1+5",194458,null],[203413,"2026-09-10T15:14:01",9,"//Опиши как ваншотнул его 😂👍",194458,null],[203415,"2026-09-10T15:15:09",17,"Стрела пробила глаз и мозги гоблина, так и осталась торчать, гоблин постоял еще пару секунд и упал\n\nЛюпен скрытненько побежал и утащил его тело в кусты за вонючую зеленую ногу с нестрижеными ногтями",194458,null],[203438,"2026-09-10T15:18:24",9,"*В лесу вроде тихо. На гоблине старый плащ, кинджал, праща с камнями. Мешочек с парой медях и вяленый кусок мяса, чей — не определить. Разведчик, тихий, низенький, зелёный как огурчик. Он что-то тут высматривал, похоже те черепа монстров на кольях у стен там не просто так.*",194458,null],[203440,"2026-09-10T15:19:16",9,"*Тихо, вас не заметили кажется, если тут еще кто-то был.*",194458,null],[203448,"2026-09-10T15:26:18",18,"Шепотом: - хватаем тушу и валим!",194458,null],[203465,"2026-09-10T15:31:45",18,"//схватили остывающее и побежали к берегу?",194458,null],[203475,"2026-09-10T15:33:44",17,"— Маленький, это разведчик, тут еще будут, может поохотимся на гоблинов?. Лют если ты на себя привлечешь их внимание, я им быстренько насую. Рен или думаешь не стоит?",194458,null],[203480,"2026-09-10T15:34:57",18,"Лют думал кажется целую вечность... \n- если малой за, то почему не",194458,null],[203482,"2026-09-10T15:36:36",20,"- Если это разведчик, то значит где-то может быть лагерь. Вряд ли мы справимся в троём против толпы мелких тварей, которые этот лес возможно лучше нас знают *честно говорит пацан*\n- да и я вам тут мало буду полезен - могу случайно лес поджечь если полезу",203475,null],[203489,"2026-09-10T15:38:05",20,"/короче можете поохотиться но для Рена это прям самоубийство(",194458,null],[203544,"2026-09-10T15:54:16",17,"— Но малой против, а он голова. Хватай зелёного и пошли к плоту",194458,null],[203547,"2026-09-10T15:55:23",18,"//тащим-с к берегу чуть-тепленького",194458,null],[203563,"2026-09-10T16:02:50",17,"— Он еще и обмочился, то что надо, близко к себе только не прижимай его, Лют",194458,null],[203564,"2026-09-10T16:03:23",17,"Долго ли коротко герои возвращаюся к побережью и по наводке рыбака идут искать тот самый плот",194458,null],[203599,"2026-09-10T16:24:34",9,"*Время клонилось уже к вечеру, потижоньку первое а то и второе солнце клонятся на вторую половину неба. Самый подходящий момент чтобы отобедать, рыбак сидит на месте, чет ест, видимо ему принесли тормозок пока вы бродили в лесу.*\n\n*Плот как и сказал рыбак оказался ниже в камышах, близ него под корнями деревьев и ветвями халабуда местных ребятишек, сейчас тут никого. Плот сделан неплохо, веревками хоть и кривые бревна неплохо связанны.*",194458,null],[203607,"2026-09-10T16:26:36",17,"Люпен достаёт верёвку и вяжет ее к плоту\n\n— Ловили когда нибудь гиганскую жабу на гоблина? Щас порыбачим или как правильнее сказать? Полягушачим?",194458,null],[203608,"2026-09-10T16:26:56",18,"//Плот большой, всех выдержит?",203599,null],[203609,"2026-09-10T16:27:07",17,"/ я не полезу ты че",194458,null],[203611,"2026-09-10T16:27:58",17,"— Гоблина на плот, ему еще надо вены вспороть чтоб кровоточил и толкаем на воду. А если клюнет, тянем ближе к беру, ну как? Рен, проканает?",194458,null],[203612,"2026-09-10T16:28:00",18,"- Давайте гоблину лапку оттяпаем и закинем, глядишь приплывет на мертвичинку...",203607,null],[203615,"2026-09-10T16:28:18",17,"— Да, правильно, прикормить надо",194458,null],[203616,"2026-09-10T16:28:56",18,"- это можно это мы запросто... \nПереворачивает молот обратной стороной и начинает методично компостировать тело зелёного вороньим клювом",203611,null],[203627,"2026-09-10T16:38:42",9,"//Описывайте что делаете",194458,null],[203628,"2026-09-10T16:38:50",18,"Сделав шаг назад:\n- пойдёт?",194458,null],[203629,"2026-09-10T16:39:43",18,"//размочаленное тело гоблина кладём на плот, плот привязываем верёвкой и отталкиваем от берега по направлению к противоположному",203627,null],[203630,"2026-09-10T16:40:23",18,"//так, товарищи, соучастники геноцида гоблинского народа? Банда Мэнсона мля 😂",203629,null],[203631,"2026-09-10T16:42:24",17,"/Да а что делать, бормотун спит сцука",194458,null],[203632,"2026-09-10T16:42:36",17,"— Ловись жабка большая и огромная",194458,null],[203633,"2026-09-10T16:43:05",17,"Люпен занял позицию в засаде и приготовил Лук, он встал подальше от воды на возвышености, чтобы берег был как на ладони",194458,null],[203634,"2026-09-10T16:43:19",17,"\"Шельма говорила, что лук нельзя мочить, лучше не подходить близко к воде\"",194458,null],[203636,"2026-09-10T16:44:08",9,"//Тоесть вы сделали это, я вижу просто что внеигровое но ок. @PaIIasCat что ты?",203629,null],[203639,"2026-09-10T16:45:41",20,"*Рен отходит на безопасное расстояние от воды, не сводя с нее взгляда.*\n\n/Просто настороже если что-то вылезет",203636,null],[203643,"2026-09-10T16:46:50",9,"*Плот медленно плывёт и его уносит вниз по течению немного ближе к центру.*",194458,null],[203644,"2026-09-10T16:46:56",9,"/roll 1d4",194458,null],[203646,"2026-09-10T16:47:41",9,"*Плот прибило обратно к берегу, футов на 200-300 ниже по реке.*",194458,null],[203649,"2026-09-10T16:49:03",20,"- Чёт не клюёт",194458,null],[203650,"2026-09-10T16:49:25",18,"Подходит к плоту и используя копьё как шест, отталкиваясь плывёт вдоль самого берега обратно, медленно, непривычно, но с высоко поднятой головой... \n- мама, я теперь ещё и моряк!",194458,null],[203653,"2026-09-10T16:49:56",9,"//Лют внимание, остальные тоже можете если хотите",194458,null],[203654,"2026-09-10T16:50:07",17,"/r +2 Пфф спрашиваешь!",194458,null],[203658,"2026-09-10T16:51:10",20,"/r d20+2",203653,null],[203662,"2026-09-10T16:51:57",18,"- мы теперь речная латная пехота, на!",203650,null],[203664,"2026-09-10T16:53:05",9,"//Внимание не кидаешь?",203662,null],[203666,"2026-09-10T16:53:28",18,"//за, листик потерял",194458,null],[203667,"2026-09-10T16:54:11",18,"/roll@roll_bot",194458,null],[203684,"2026-09-10T17:00:46",9,"*Может вы просмотрели, а может это монстр подплыл под берегом слишком скрытно, прямо перед Лютом выныривает огромная жаба, рогатая и лютая как стая зубастых оленей. Острейшие когти, кожа поросшая слизистыми водорослями в которых живут мелкие речные гады. Она ложит лапу на плот и толкает тот к берегу. Глаза словно блюдца, светят, заглядывают в душу, её губы едва заметно шевелятся, но фоне зубов этого не видно. Лют, и только он слышит у себя в голове когда Бормотун смотрит на него, обрывки слов на общем, бормотание, угадывается речь в бормотании \"Бе-ги\".*\n\n//Спас мудрости сл 16 или ты Лют испуган и убегаешь весь свой след ход.",194458,null],[203688,"2026-09-10T17:03:09",18,"/roll@roll_bot",194458,null],[203690,"2026-09-10T17:03:18",9,"*Жаба засопела и дыхнула на Люта через свои ноздри с такой силой что из них полетела застоявшеяся слизь тому на лицо. Просто очень неприятно.*",203684,null],[203694,"2026-09-10T17:04:33",18,"//вот тут, я думаю, мои товарищу тащат меня за шкварник подальше от воды со всех ног😅",194458,null],[203695,"2026-09-10T17:04:36",9,"*Лют может и сам не понимает что происходит, но он убегает на берег куда глаза глядят. Лягушка провожает его взглядом но не преследует, лишь толкает плот на берег.*\n\n// @PaIIasCat @dunchev ваши реакции?",194458,null],[203696,"2026-09-10T17:05:08",18,"*что-то не так в штанах",194458,null],[203698,"2026-09-10T17:05:50",17,"/Я в 60 футах на холмике сныкался))",203694,null],[203699,"2026-09-10T17:05:55",18,"Оглядывается на товарищей; - а...ть! Она не атаковала!!!",194458,null],[203704,"2026-09-10T17:06:39",18,"- народ ляга походу пришла к нам с миром, хорошо я ей на автомате копьём не впорол...",194458,null],[203706,"2026-09-10T17:07:05",9,"//Если реакций нет\n\n*Бормотун просто убедился что плот не уплывет и поворачивается собираясь возращаться в воду.*",194458,null],[203707,"2026-09-10T17:07:08",18,"- это что же получается... Она только на мертвичинку кидается?",194458,null],[203708,"2026-09-10T17:07:35",20,"*Рен сидит. Думает немного...а потом тянется телепатией. Ну потому что почему бы и нет - день и так уже достаточно странный*\n\n\"Доброго дня.\" 🗿\n\n/В голове у лягухи, да",203706,null],[203711,"2026-09-10T17:07:47",18,"- причём поднятую...",194458,null],[203712,"2026-09-10T17:07:53",17,"Люпен напугался до усрачки, но Люту там было хуже. Унимая дрож в руках он натянул тетиву и целился гадине в глаз",194458,null],[203717,"2026-09-10T17:09:00",18,"- что завалим тварь за 300 или пущай живёт?",194458,null],[203718,"2026-09-10T17:09:21",18,"*Лют обосрамшись",203712,null],[203719,"2026-09-10T17:09:22",9,"*Грузная туша на мгновение остановилась и повернулась к Рену, будто поняла. Не двигаясь смотрит в сторону где пацан. Никакой реакции пока, словно оценивает с чем столкнулась. Разум в его глазах.*",203708,null],[203724,"2026-09-10T17:11:42",20,"*Рен выходит из укрытия и подходит чуть ближе, хотя все ещё не подходит к воде*\n\n\"Говорят в последние время вы были чем-то обеспокоены, даже разрушили лодку в деревне. Что вас посмело потревожить?\" - продолжает он мысленно \n\n*Параллельно с этим Лют и Люпен слышат в мыслях:*\n\"Подождите немного, я хочу с ним попробовать поговорить\"",203719,null],[203726,"2026-09-10T17:12:22",9,"//Ну вот, что нить надо, или харизма или уход за животными",194458,null],[203729,"2026-09-10T17:12:59",20,"/r d20+4 на убеждение жабки",194458,null],[203737,"2026-09-10T17:17:29",9,"*Рен чувствует усиленное давление на мозг, голова раскалывается будто извилины прочесали щёткой, выуживая мысли и намеренья. После облегчение и голос, бормотание, будто сон, вудто на краю сознания голос за который едва можно ухватиться.*\n\nТелепатия только Рену: \"Дракон... разума... должны... спать... все... мёртвые... не видят... сны...\"\n\n*Монстр почему-то не трогал Рена и не пытался напугать. Вот Люта скорей бы всего сожрал без проблем.*\n\n//Детали",194458,null],[203738,"2026-09-10T17:17:50",9,"/roll 1d4 психического урона Рену за прошёрстку мозжевельника",194458,null],[203748,"2026-09-10T17:20:06",17,"Люпен унимает страх и ослабляет натяжение лука, держа его наготове",203724,null],[203751,"2026-09-10T17:21:35",20,"\"Понятно, значит тебя потревожили подняв живих мертвецов и пойдя против природы.\" - Рен понимающе кивает.\n\n*Общий смысл и мотив он уловил, но вот детали пока не до конца понял...дракон разума?*\n\n/Какой проверкой можно попробовать расшифровать слова жабы?",203737,null],[203757,"2026-09-10T17:25:45",9,"//Никакой, инфы минимум, то что ты только что услышал",194458,null],[203760,"2026-09-10T17:28:02",20,"\"Ты не хочешь пропускать лодки, на которых мертвые? Если они уплывут то унесут свое проклятие далеко из этих мирных мест и больше тебя не потревожат\" - продолжает он\n\n\"На земле ещё бродят остатки - и мы их выследим, упокоим\"\n\n/Ну пытаемся тогда дальше",194458,null],[203768,"2026-09-10T17:32:28",9,"*Жаба слушает, она прижмуривает глаза. Всё же не очень умна или плохо знает общий и не может сразу понять о чем Рен.*\n\nТелепатия Рену: \"Нет\"\n\n*Бормотун лениво разворачивается и уходит в воду.*",203760,null],[203776,"2026-09-10T17:37:24",9,"//Есть что-то пока Бормотун не ушел под воду, заявки и тд?",194458,null],[203782,"2026-09-10T17:39:06",20,"/ну я так понимаю у Рена все, убедить не нападать он не смог",203776,null],[203783,"2026-09-10T17:40:18",18,"- Итаааак...что мы имеем, облом по бабкам похоже.",194458,null],[203791,"2026-09-10T17:44:24",18,"- Ляга ненавидит поднятых мертвяков, лягу пожалели, за мертвяков нам уже похоже не заплатят. Варианты?",194458,null],[203793,"2026-09-10T17:45:01",9,"Рыбак — Чёрт, это же он! Ахахах, увидел, он существует. — *Радуется, только что подошел там где вы.* — А чегоэто он, мирный шоле? На вас не напал.\n\n*Рыбак со смотанными удочками и ведром с рыбой смотрит на это дело.*",194458,null],[203794,"2026-09-10T17:45:11",18,"- пойдём дадим старосте пиздюлей! Или спасём от некроманта если он их там вмех насильно использует в делах своих грязных...",194458,null],[203796,"2026-09-10T17:47:02",20,"- Да мирный, если сам зла не будешь делать *вздохнув бросает Рен, проходя мимо*\n\n*Потом возвращается к остальным, пересказывая диалог с лягухой*",203793,null],[203799,"2026-09-10T17:48:28",9,"*Рыбак рядом с вами слушает.*",194458,null],[203800,"2026-09-10T17:50:00",20,"*Рен смотрит на рыбака. Потом на своих спутников. И как ни в чем не бывало продолжает разговор только в их мыслях*\n\n\"Если там то придется в доки прорываться через стражу, а их там...\" *Рен вспоминает сколько их там*  \"ну, явно больше чем нас\"\n\n\"Если хотим туда попасть малой кровью придёт для начала склонить местных на нашу сторону\"",203799,null],[203810,"2026-09-10T17:54:07",20,"- Странно правда? Все эти годы вполне мирно это существо сосуществовало с деревней, а вот сейчас почему-то напало на лодку в доках... *Это уже слух, говорит как будто своим, а на самом деле все для ушей рыбака. Похоже хочет подпитать слухи для людей*\n\n- Странно правда? Ещё и никого туда не пускают, ни нас ни местных...",194458,null],[203816,"2026-09-10T17:56:31",9,"Рыбак — Всякое бывает. — *Он пожимает плечи.* — Староста заботится о людях. Деревня при нем на ноги встало, значит знает как лучше.",194458,null],[203826,"2026-09-10T17:59:00",17,"/ Я за рулём",194458,null],[203827,"2026-09-10T17:59:05",17,"/ Хочу выстрелить",194458,null],[203832,"2026-09-10T18:00:06",18,"- даже если в следующий раз мертвяк к тебе в дом не заглянет? Или думаешь деревня на горохе дамкуеурузе поднялась? Староста ваш умертвиями торгует либо сам либо принудил кто, то-то.",203816,null],[203833,"2026-09-10T18:00:06",18,"- рыбачок, а где у вас тут в набат бить принято, чтобы народный сход собрать?",194458,null],[203843,"2026-09-10T18:01:26",18,"/в кого!?! 😳",203827,null],[203844,"2026-09-10T18:02:10",9,"//Ну, тогда ждем, чё",194458,null],[203846,"2026-09-10T18:20:40",17,"Люпен опустил лук\n\nПодошёл к остальным\n\n— Староста мутными делами промышляет. Как пить дать. У нас пока только доказать нечем. Кто у вас в городе ещё властью обреиенен? Есть совет какой нибудь?",194458,null],[203847,"2026-09-10T18:21:07",17,"/ Да ну чё. Ходим бродили дальше. Я не буду ломать сцену потому что заскучал без боевых столкновений очевидно",194458,null],[203850,"2026-09-10T18:21:57",9,"//Ну, поступай как персонаж, я вообще за любой кипишь)))",194458,null],[203853,"2026-09-10T18:24:08",9,"Рыбак — Охотники, пивовар, трое старейшин, старики ой не любят старосту. — *Почухал голову.* — А так, не знаю, не умею я в эти ваши хитросплетения, простите.\n\n*Он рассмеялся, рыбак вообще будто живет по жизни по кайфу.*",203846,null],[203858,"2026-09-10T18:29:06",17,"— Спасибо рыбак, хорошего улова. Мой совет. Лучше подальше сядь, у бормотуна настроение переменчиво. А ты семейный человек.\n\nЛюпен отходит и зовёт всех за собой\n\n— Рен, что нам лучше предпринять? Старейшины не любят старосту, но нам им предложить нечего. Мы нихрена не сделали для города, улик не нашли. Может найти сгоревшего в сортире? Может при нем зацепка какая будет...\n\nОхотникам желательно отдать крупного зверя, любой охотник за такое сразу зауважает и выслушать может. А после охоты и попойка обычное дело, под хмелем и языки развяжутся и уговорить будет проще выступить против старосты. Потребовать лодочную показать.\n\nС пивоваром у меня идей нет, я пиво только пить люблю, варить не умею и как его расположение заслужить у меня даже идей нет.\n\nЛют, а ты что скажешь?",194458,null],[203860,"2026-09-10T18:29:49",9,"Рыбак — И правда, пора мне небойсь воротится. На Бормотуна посмотрел, детям раскажу, чтобы в воду не лазили, бывайте. — *Помахал вам на прощание и домой идёт.*",194458,null],[203863,"2026-09-10T18:36:50",20,"- Доказательств можно ещё достать - не один же только мертвец от общей толпы отбился. Если поймаем ещё парочку сразу и улику получим и от местных хоть каким-то доверием заручимся. А там уж можно будет и со старостами поговорить...",203858,null],[203864,"2026-09-10T18:39:48",17,"— Пошлите искать мертвецов, может кто то в подвал забрел или в колодец провалился",203863,null],[203865,"2026-09-10T18:40:10",17,"- как мертвец вообще в сортире оказался?",194458,null],[203866,"2026-09-10T18:44:43",20,"- Кто знает, может с наступлением утра попытались куда потемнее забиться - кто в подвал, а этот вот выбрал более...креативный вариант",203865,null],[203867,"2026-09-10T18:45:56",17,"— Насколько они умные? Ну вот мертвец мог сам открыть дверь сартира например? И закрыть за собой?",194458,null],[203868,"2026-09-10T18:51:24",20,"- Не знаю если честно. Наверное не слишком умный чтобы намеренно в сортире засаду устроить но достаточно умный чтобы закрыть дверь от солнечного света? *пожимает плечами пацан*\n\n- Мертвецы разные бывают, все зависит от того какое заклинание их подняло.",203867,null],[203894,"2026-09-10T19:08:32",18,"- Пойдём очки смотреть, а там уже общее прочёсывание местности от сих до сих...",194458,null],[203896,"2026-09-10T19:10:53",18,"- хотя сомнитено что под сортиром ход...так что можно и сразу шерстить...и это нравится мне всё это всё меньше, ох как я урурукару енту понимаю...",194458,null],[203899,"2026-09-10T19:13:58",9,"*Лют преисполнился в познании настолько что понял жизненную позицию речного монстра.*\n\n//Если ты о Бормотуне)))",203896,null],[203900,"2026-09-10T19:15:02",18,"// о мертвяках",203899,null],[203901,"2026-09-10T19:16:28",9,"//Тогда недействительно",203899,null],[203902,"2026-09-10T19:16:35",17,"— Хах, сидишь ты, серешь, а тут тебя Ам за жопу мертвец из очка. Да у меня теперь боязнь сортиров, спасибо Лют. Я уж лучше с лопушком да в кустиках",194458,null],[203903,"2026-09-10T19:19:20",20,"- Рассказывал мне как-то учитель про живые кусты ...",203902,null],[204251,"2026-09-11T09:56:45",18,"//Народ, соберёмся, добьём уже на конец?",194458,null],[204260,"2026-09-11T10:08:26",9,"//Так, вы в город?",194458,null],[204261,"2026-09-11T10:09:14",17,"/ По опыту в этой песочнице играть ещё неделю",204251,null],[204263,"2026-09-11T10:09:44",17,"/ потому что слишком много свободы. 3 стороны которые против старосты могут выступить",194458,null],[204264,"2026-09-11T10:09:49",9,"//Ну, это от вас зависит, я расчитывал на пару-тройку дней",194458,null],[204265,"2026-09-11T10:09:55",17,"/ Нам хотябы 1 склонить на свою сторону",194458,null],[204269,"2026-09-11T10:10:52",17,"— Давайте пойдем к охотникам. Решим из проблему и попросим во время пьянки поддержать нас против старосты. Я думаю это самый прямой и простой путь",194458,null],[204271,"2026-09-11T10:12:00",20,"- Хорошо, давай так *соглашается пацан*",204269,null],[204272,"2026-09-11T10:12:07",18,"- пьянка? Кто сказал слово Пьянка?! Я в деле, тысяча чертей!",204269,null],[204273,"2026-09-11T10:12:53",17,"/ Хотя я бы конечно тут закрыл все сайд квесты",194458,null],[204274,"2026-09-11T10:13:01",17,"/ Но Лют придушен уже видно",194458,null],[204276,"2026-09-11T10:14:12",9,"*Возвращаясо в Дрейгхолд вы заметили что на том же месте где сидел рыбак сидит человек немного бандитского вида и не рыбачит, он просто следит за рекой. Провожает вас взглядом.*",194458,null],[204278,"2026-09-11T10:14:25",18,"/Лют держится на морально-волевых, но тут на носу пьянка, всё побую! 😂😈",194458,null],[204280,"2026-09-11T10:14:39",9,"//Кто хочет кинуть на анализ? Или и так все ясно?)",204276,null],[204281,"2026-09-11T10:15:13",17,"/ Мне не ясно. Рен?",194458,null],[204282,"2026-09-11T10:15:26",20,"/мне тоже не совсем, сейчас кину",194458,null],[204283,"2026-09-11T10:15:40",20,"/r d20+2 анализ",194458,null],[204286,"2026-09-11T10:18:14",9,"*Собрав все факты рен понял что рыбак не совсем рыбачил а следил за рекой когда Бормотун слиняет. Сейчас пришла смена и он пошёл тогда посмотреть что вы делаете. Рыбак работает на старосту деревни, вместо него сейчас на стрёме сидит часовой.*",204284,null],[204287,"2026-09-11T10:19:29",9,"//Есть что-то или в деревню перемещаемся?",194458,null],[204289,"2026-09-11T10:19:51",17,"/ Пошли до него докопаемся",194458,null],[204291,"2026-09-11T10:20:07",17,"/ А тот щас настучит что бормотун вылез а мы его не убили и отпустили",194458,null],[204295,"2026-09-11T10:20:34",18,"- Пошли пообщаеимя, страсть как люблю светские беседы вести...",194458,null],[204297,"2026-09-11T10:26:18",9,"*Когда вы вяртаетесь в деревню то замечаете несколько изменений.*\n\n*Тело в сгоревшем сартире убрали.*\n\n*Возле ратуши стоит пустая черная карета, рядом с ней стоит охранник.*\n\n*Анастасии нет на своем месте почему-то.*\n\n*Староста разговаривает с рыбаком у пирса, мужик все ещё со смотанной удочкой и ведром с уловом в руках.*\n\n*На пирсе лишняя куча чего-то накрытая тканью. Судя по всему это перенесут в лодки.*\n\n*Немного более людно, местные под вечер заканчивают потихоньку дела.\n\n*Возле колодца кипишь, кто-то ругаясь из колодца подвязанный за верёвку что-то там ищет причитая мол \"не дай бог снова кот в колодец упал, надо крышку ставить!\"*",194458,null],[204302,"2026-09-11T10:33:23",17,"Люпен шепчет остальным\n\n— Может скажем, что мы заставили монстра осттупить? Он не потревожит лодки? Заберём награду да и свалим?",194458,null],[204303,"2026-09-11T10:33:40",17,"— Все равно рыбак видел только что тварь вылезла и ушла под воду назад",194458,null],[204305,"2026-09-11T10:34:04",17,"— Блефанем, а. Рен?",194458,null],[204306,"2026-09-11T10:34:05",9,"//И то что вы при нем обсуждали)",194458,null],[204311,"2026-09-11T10:35:13",17,"— Ааа млин. Мы ж принес обсуждали против старосты движения. Пиздец. Накрылся план",194458,null],[204312,"2026-09-11T10:35:26",17,"/ Ой блять я кароче хуй знает что делать. Скажите кого застрелить я готов",194458,null],[204316,"2026-09-11T10:36:57",20,"/я уже тоже если честно задушнилась(\n/Вообще не знаю что делать, у меня все планы и предположения проваливаются",194458,null],[204317,"2026-09-11T10:37:40",9,"*Люпену возможно пришла мысль что если просто завалить старосту и свалить? Есть шанс что проблема без головы сама решится, только как награду потом к рукам прибрать.*",204312,null],[204328,"2026-09-11T10:43:25",18,"/вырежем всю деревню! 😅",204317,null],[204329,"2026-09-11T10:43:33",17,"/ И у меня",204316,null],[204330,"2026-09-11T10:43:50",17,"/ Да хуйня, такая мысль мне бы не пришла",204317,null],[204331,"2026-09-11T10:44:00",18,"/как вариант идём мочить жабу",194458,null],[204332,"2026-09-11T10:44:10",17,"/ мои мысли вот",203858,null],[204333,"2026-09-11T10:44:22",9,"//Неактуально, я шутил, сами решайте свалить ли с этого цирка оставив как есть или сделать что-то",204317,null],[204334,"2026-09-11T10:45:27",18,"- пойдём до старосты сходим...",194458,null],[204353,"2026-09-11T10:51:23",18,"- объяснимся, распрощаеимся, а там видно будет.",194458,null],[204362,"2026-09-11T10:54:04",17,"Люпен черет затылок и смотрит на Рена",194458,null],[204372,"2026-09-11T10:56:41",20,"- Похоже только это нам и остаётся *Пожимает плечами Рен*\n\n- Жители явно на стороне старосты, некромант вот вот уедет *указывает на карету* - времени когото переубеждать особо не осталось \n- И я честно говоря уже не вижу что мы тут можем сделать, учитывая что пошли на прямую конфронтацию раньше. Да и рыбак на нас уже должен был доложить\n\n*Рен просто устал уже от этого.*\n/Я тоже",204353,null],[204374,"2026-09-11T10:57:15",20,"/я чувствую себя абсолютно бесполезным)",194458,null],[204376,"2026-09-11T10:58:07",9,"*Пока вы думаете Анастасия возвращается на свою лавку у ратуши откуда-то из деревни. Довольная, прглядывает на пирс к старосте.*\n\n*Рыбак заметил вас помахал с пирса улыбаясь, глава тожн кинул взгляд, что-то сказал рыбаку и они разошлись.*",194458,null],[204378,"2026-09-11T10:58:14",17,"/ Я надеялся мы с твоей помощью сможем тут бунт поднять против старосты\n А ему все наши планы рассказали бляяя",204374,null],[204379,"2026-09-11T10:58:48",17,"/ ну хотя я писал что мы отошли",194458,null],[204380,"2026-09-11T10:58:59",17,"/ Ладно пошли поговорим. Блефовать будем?",194458,null],[204382,"2026-09-11T10:59:22",20,"/да у нас по пизде все пошло когда в сцене пожара на конфликт пошли - сразу  + подозрения и староста всех на свою сторону перетянул",204378,null],[204384,"2026-09-11T10:59:42",20,"/ещё и что Рен маг спалили",194458,null],[204385,"2026-09-11T10:59:48",17,"/ Ну... Я сидел на крыше тогда, что могу сказать",194458,null],[204407,"2026-09-11T11:09:47",18,"Направляется к старосте широко улыбаясь распахнув руки для широких объятий...",194458,null],[204414,"2026-09-11T11:10:41",17,"— Я лучше промолчу. Говорите вы",194458,null],[204426,"2026-09-11T11:13:59",20,"- Пойдем может к Анастасии подойдем - спросим что тут происходило вообще. *Предлагает Рен*\n- Она вон какая довольная, может тоже свою сделку с главой или некромантом заключила",204414,null],[204428,"2026-09-11T11:15:30",17,"Люпен кивнул",194458,null],[204430,"2026-09-11T11:16:06",20,"/Рен и люпин идут к Анастасии",194458,null],[204433,"2026-09-11T11:17:29",9,"Девушка (Анастасия) — Привет. Как дело идёт? — *Она сидит на лавке, довольная, поглядывает в сторону пирса, лукаво, недобро.*",194458,null],[204436,"2026-09-11T11:18:33",18,"Подойдя и сграбастав старосту:\n- ну что же знатно вы над нами поглумились, жабëнка то ваша смышленая оказалась, мыслит прогрессивно, связь телепатицкую имеет и убивать её лишь за то, что ей не нравятся контрабандисты таскающие по реке тудой-сюдой мертвечинку мы конечно же не стали, так что оставляем вас с добрососедскими отношениями с тварью сией и потерями в прибылях. \nХохотнул..почти отпустив и отстранившись и как бы невзначай обронил шепотом:\n- но если некромант вас снасидьничал и вы против своей воли под его дуду пляшете, вы только подмигните 😉",194458,null],[204439,"2026-09-11T11:21:08",20,"- Прогулялись. Посмотрели местную фауну. Но похоже тут и без нас вполне все налажено *Пожимает плечами Рен*\n\n- Как тебе знакомство с тем магом? Довольно интересный опыт, полагаю?\n\n/Рен под обнаружением мыслей",204433,null],[204440,"2026-09-11T11:21:35",9,"Староста — Катитесь лесом отсюда, наемнички. — *Махнул рукой и идет к докам.*",204436,null],[204441,"2026-09-11T11:22:56",9,"Анастасия — С каким магом. — *Она наклониоа голову не понимающе.* — Я со стариками болтала, надеюсь они проверят что в тех лодках, только тсссс.\n\n*Она усмехнулась и прижала палец к губам, словно играла.*",204439,null],[204442,"2026-09-11T11:23:22",20,"/о чем думает?",204441,null],[204444,"2026-09-11T11:24:55",9,"*В мыслях Анастасии роится любопытство и жажда узнать что-же все же происходит. Она частично уверена что в лодках и правда мертвецы, рада что хорошо поболтала со стариками недавно. Слегка боится последствий и вся на нервах.*",194458,null],[204445,"2026-09-11T11:26:21",18,"- и тебе не хворать, если где болт промеж лопаток словите ненароком, не удивляйтесь... \nПреисполнивщись чувством собственного достоинства идёт к остаткам группы.",204440,null],[204446,"2026-09-11T11:27:28",20,"- Намекнула старейшинам что с друзом дела нечисты? Умно *Рен фыркнул со смехом, переведя взгляд на доки*\n- Если они с главой сцепятся из-за этой сделки...\n\n- Но если тебе правда так интересно то да, так и правда мертвецы *он решает удовлетворить ее любопытство, раз все равно они уйдут отсюда*\n- Везут скорее всего в Веспираль *указывает на чёрную карету*",204441,null],[204447,"2026-09-11T11:28:39",18,"*по пути к своим Лют проходя мимо заглядывает в карету...",194458,null],[204448,"2026-09-11T11:28:51",9,"Анастасия — Я могу достать алхимический огонь. Давай как стемнеет сожжем карету! — *Добавила она заговорчески, тихо, вошла во вкус.*",204446,null],[204449,"2026-09-11T11:28:52",20,"- Но шаг конечно рисковый - мы то уйдем, а вот на тебя глава может и обиду затаить *вздыхает он. Похоже слегка переживает за девушку*",204444,null],[204450,"2026-09-11T11:30:29",20,"*Рен смотрит на Люпена*",204448,null],[204451,"2026-09-11T11:31:42",9,"*Он взглянула на свою записную книжку, тяжко ей было, но боролось все со скукой и решимостью.*\n\nДевушка (Анастасия) — А плевать, я с вами уйду. Может стащу немного денег у толстяка перед уходом. — *Намеренье жить по новому, весело и без повсякдневных забот секретаря, конечно если вы её не прогоните.*",204449,null],[204453,"2026-09-11T11:32:51",20,"- Хах, а не плохая идея. У нас в лагере всегда найдется место смелым и умным *он подмигивает*\n\n/+ Приключенец обыватель?)",204451,null],[204454,"2026-09-11T11:33:34",9,"//Я не знаю, может леду закрою обратно и вместо него её",194458,null],[204455,"2026-09-11T11:35:33",9,"Девушка (Анастасия) — Тогда договорились. — *Девушка искренне улыбнулась.* — Устроим веселье на последок и уйдем с огоньком.",204453,null],[204457,"2026-09-11T11:50:59",18,"Подойдя к остальным и услышав окончание разговора:\n- ничëсь вы тут порешили, а я то, старый хрыч думал, что это я тут реакционер))",194458,null],[204458,"2026-09-11T11:51:12",18,"- ну что давайте сделаем это!",194458,null],[204459,"2026-09-11T11:52:22",9,"Девушка (Анастасия) — Тшшш, ты что. — *Она посмотрела на Люта и по сторонам осмотрелась.* — Не шуми ты так, узнает кто и всё. А у вас были какие-то планы?",194458,null],[204460,"2026-09-11T11:57:12",18,"- спасать красавицу и текать, со старостой я уже по доброму распрощался.",204459,null],[204462,"2026-09-11T12:02:38",17,"А Люпен отрицательно иалюшет головой\n\nИ на ухо шепчет ему\n\n— Есть мысля ночью облаву на лодочную устроить. Жёстко снять охрану и вскрыть все на месте преступления",204450,null],[204538,"2026-09-11T13:02:45",20,"- Если честно я не очень хотел бы вредить страже - как никак они мало в чем виноваты, да и нас тогда точно буду считать преступниками\n\n- Но вот если удастся сделать это более скрытно...может сработать. Но вскрыть это надо перед свидетелями, а все жители будут спать. Для облачения нужна аудитория... Можно поджечь лодки незаметно? Тогда в доки сбегутся люди и сами увидят мертвецов в них.\n\n*Он трет переносицу. Сложно...*\n\n- уж и не знаю как лучше поступить",204462,null],[204540,"2026-09-11T13:04:05",9,"Девушка (Анастасия) — Надеюсь старики прийдет до затемна. — *Смотрит на солнца что через пару часов начнут уходить в закат.*",194458,null],[204555,"2026-09-11T13:07:31",18,"- зажигательными стрелами? \nСтоит с умным видом ковыряясь в носу явно доволный собой...",204538,null],[204819,"2026-09-11T17:12:47",9,"//Ну, думайте чтотсобираетесь делать, а так.\n\n*Ближе к закату облака немного развеялись, на вас ложится свет под большим углом. Примерно в это время Староста почему-то снаряжал загруженные лодки на отплытие как к пирсу начали соьираться люди, сначала несколько стариков с молодыми а потом ещё. Стража занята тем что пытается не пустить их, с отплытием лодок заминка, но скорей всего их спустят на воду в течении 20-30 минут, возможно быстрее чем люди успеют плсмотреть что там.*\n\n//Думайте планы и действия, условно у вас было время подготовится, все детали на столе, если хотите чет спросить/уточнить — спрашивайте",194458,null],[204852,"2026-09-11T17:39:00",20,"- Похоже твой план сработал, старики повели всех к докам *Рен высматривает ситуацию на пирсе*\n\n- Давайте поспешим туда, вместе с ними надавим на стражу чтоб пропустили, пока лодки не уплыми\n\n/Был час времени чтобы снова призвать фальяра?",204819,null],[204855,"2026-09-11T17:40:29",9,"//У вас условно полтора часа на подготовку к этому)",204852,null],[204862,"2026-09-11T17:44:17",20,"/Рен ритуалом призывает себе сову (ⓛ▽ⓛ)",204855,null],[204885,"2026-09-11T17:59:05",20,"/тогда вопрос - у нас есть алхимический огонь, который хотела добыть Анастасия?",194458,null],[204889,"2026-09-11T18:01:14",20,"/или ей нужно помочь?",194458,null],[204891,"2026-09-11T18:01:52",9,"*Анастасия к вечеру все же достала алхимический огонь. Старая тара, слегка надколота но жидкость внутри все та же, алхимия не портится.*",194458,null],[204919,"2026-09-11T18:27:13",18,"Разглядывая пузырёк:\n- в принципе могу закинуть его футов на 100...",194458,null],[204958,"2026-09-11T19:15:56",17,"— Наведите шумиху ц кареты, а я одного мертвеца притащить попробую, людям показать. Старейшинам. Как вам идея?\n\nКак только огонь полет стража переполошится.",194458,null],[204989,"2026-09-11T19:35:20",20,"- Куртку можно попробовать факелом обычным поджечь. А вот огонь я бы оставил на толпу мертвецов - то что они там спокойно лежат не значит что они не могут встать, особенно если маг будет рядом.",204958,null],[204992,"2026-09-11T19:36:15",20,"- Получается Лют поджигает карету, Люпен скрытно старается подобраться за мертвецом, ну а мы с Анастасией может пойти к общей толпе - дополнительно отвлечем внимание и возможно сможем добиться чтобы всех в доки пропустили тебе навстречу",194458,null],[205028,"2026-09-11T19:57:12",17,"— Если никто не денется я рисковать не буду. Будем действовать по обстоятельствам",194458,null],[205029,"2026-09-11T19:57:17",17,"— Начинаем",194458,null],[205031,"2026-09-11T19:57:28",17,"Люпен накинул черный капюшон и поднял маску на лицо",194458,null],[205033,"2026-09-11T19:57:41",17,"И пошел затаится на рыьнгм рынке среди пустых прилавков",194458,null],[205063,"2026-09-11T20:02:06",20,"*Рен (и Анастасия если она согласна с планом) направляется к толпе*",194458,null],[205103,"2026-09-11T22:50:27",18,"* переместился за здание рядом с рыбным рынком",194458,null],[209149,"2026-09-13T17:44:49",9,"//Так, надо заканчивать я вам скажу. @OIK77GK @PaIIasCat @dunchev как нибудь завтра сможем?)",194458,null],[209152,"2026-09-13T17:45:15",17,"Да завтра можем",209149,null],[209173,"2026-09-13T18:02:04",18,"Постараюсь присутствовать по максимуму",194458,null],[210001,"2026-09-14T06:39:49",17,"И так\n\nЛюпен затаился на рыбном рынке, усевшись за прилавком и обустроил себе наблюдательный пункт за лодочной. Он ждал, когда остальные начнут маневр отвлечения. Его план был прост. Быстрые ноги. Скрытная пробежка \n\nОн натянул пониже черный капюшон и поднял черный платок на лицо. Только узкая полоска глаз осталась видна",194458,null],[210012,"2026-09-14T08:01:14",9,"//Остальные как подготовились?",194458,null],[210013,"2026-09-14T08:03:59",20,"/Рен подошёл к толпе - фамильяр сверху в небе, смотрит обстановку",210012,null],[210066,"2026-09-14T09:49:41",18,"/за зданием на рыбном рынке",194458,null],[210112,"2026-09-14T10:23:25",18,"*нервно насвистывает ротную Der tod in den ebenen...",194458,null],[210123,"2026-09-14T10:26:01",17,"/Хард вероятно никто не понимает как начать",194458,null],[210126,"2026-09-14T10:28:14",18,"*\"Смерть скачет на угольно чёрном коне\nКогда ландскнехт марширует по полю...\"\nРуки в который раз пробегают по амуниции и оружию проверяя готовность, завязки шлема, ровно ли распределяется вес кольчуги, щит, хорошо ли выходит молот из петли...",210112,null],[210236,"2026-09-14T12:40:14",9,"//Анастасье что за дело дали?",194458,null],[210239,"2026-09-14T12:41:32",17,"/ @PaIIasCat",194458,null],[210282,"2026-09-14T13:01:19",20,"/Рен позвал ее с собой",210236,null],[210285,"2026-09-14T13:01:54",20,"/помогать людям попасть в доки",194458,null],[210286,"2026-09-14T13:02:10",9,"— Карету не будем жечь? — *Она слегка разочарованно спросила.* — Ну ладно.",210282,null],[210307,"2026-09-14T13:05:09",18,"/девчонка ваще бомбистка 😈",210286,null],[210313,"2026-09-14T13:05:45",20,"- Возможно придется жечь этим огнем мертвецов, если маг их поднимет из лодок *тихо делится своим предположением Рен*\n- это веселее",210286,null],[210316,"2026-09-14T13:10:03",17,"/ Я думал подожжете",194458,null],[210317,"2026-09-14T13:10:28",20,"/огонь у Люта, так что ему решать на самом деле",194458,null],[210319,"2026-09-14T13:12:51",17,"/ Бомби как царя, Лют",194458,null],[210320,"2026-09-14T13:16:00",17,"/ @OIK77GK",194458,null],[210321,"2026-09-14T13:18:55",9,"*Вечереет, темнеет. Старики и ихлети уже толпой прожимают стражу, староста деревни пытается их успокоить но он не батька, не сильно помогает.*\n\nТучный староста — Тише! Отойдите, не шумите, привлечете бормотуна на пирс.\n\nСтарик — Да что ты милок, лишь покажи что в лодках, да мы разайдёмся. Слушок пашол, народ негодует.\n\n*Стражники пропустили пару людей, кадется это были свои. При этом знакомый вам рыбак был в толпе людей, он искренне не понимал что происходит.*\n\n//Стража отвлечена, если Люпен хочет пробраться к пирсу то скрытность с преимуществом, там есть люди старосты но всего несколько людей, не стража, хотят спустить лодки на воду. Действия остальных? Уточнения?",194458,null],[210323,"2026-09-14T13:21:06",17,"/r +d20+4 Я пошел к пирсу",194458,null],[210325,"2026-09-14T13:23:01",20,"*Рен пробирается к толпе*\n\n- Бормотуна? Странно - ведь раньше он никогда не нападалтна лодки! *Громко говорит он*\n\n- Все началось после того, как всех перестали пустить в доки и начали что-то грузить на лодки! Уж не из-за этого ли он так взбесился, а?\n\n- И почему вы скрываете это от людей?!\n\n*Кидает взгляд на Анастасию - мол помоги расшевелить толпу*",210321,null],[210326,"2026-09-14T13:23:22",9,"*Через забо и смотрящего это было сделать лучше всего. Люпен у сторожек и складов, перед ним лодочная, есть несколько окон, лверь в лодочную и крыша чтобы обойти к пирсу.*",210324,null],[210328,"2026-09-14T13:24:30",9,"//Выступление кинь, тут шумно очень, Анастасия пытается привлечт внимание чтобы тебя услышали",210325,null],[210329,"2026-09-14T13:25:04",20,"/с помощью или прямая проверка?",210328,null],[210330,"2026-09-14T13:25:24",9,"//Помощь, но у тебя еще и артистичный нет?)",210329,null],[210331,"2026-09-14T13:25:38",20,"/это тоже)",210330,null],[210332,"2026-09-14T13:26:21",20,"/r +d20+2 выступление",194458,null],[210334,"2026-09-14T13:27:30",9,"/roll 1d20 страроста выступление, у него и преим и помеха",194458,null],[210343,"2026-09-14T13:29:39",9,"*Люди вообще не стали слушать что там толстый бубнит себе страду вот вот сметут.*\n\nСтарик — Сынок верно говорил. Чаго ты нас не пусчаешь, все свои!\n\nТучный староста —  — Вам нельзя в доки, поверте нельзя. Идите пожалуств по домам. — *Он уже взмолился, видно что боится, но чего?*",194458,null],[210344,"2026-09-14T13:30:11",9,"*Люди почти прорвались, и спускать лодки на воду осталось всего пару человек.*",194458,null],[210345,"2026-09-14T13:30:13",18,"*Лют, выйдя из-за здания направляется к лодкам, рассчитывая подпалить лодки и док и вообще всё и вся...",194458,null],[210346,"2026-09-14T13:30:42",9,"//Как ты прорвешься через толпу, описывай)",210345,null],[210347,"2026-09-14T13:31:05",9,"// @dunchev",210326,null],[210349,"2026-09-14T13:31:54",18,"/я за толпой пока в перед не рвусь, жду",210346,null],[210353,"2026-09-14T13:35:39",18,"- за правду и справедливость люди добрые, установим истину во славу богам! \nРаспаляет Лют толпу из задних рядов, ожидая кульминации, что же за груз в лодках...",194458,null],[210356,"2026-09-14T13:37:25",17,"Люпен решил лезть на крышу чтобы поискать вход оттуда или просто посмотртеь. Скорее всего в лодочной должны быть окна на крыше",210326,null],[210358,"2026-09-14T13:38:07",20,"*Рен отступает в сторону от толпы, тяня за собой Анастасию чтобы если начнется паника, не попасть в давку.*\n\n*Переключается на зрение фамильяра, наблюдая за каретой - и на всякий случай смотря на Люта, что предупредить если из нее кто-то попытается выйти*",194458,null],[210359,"2026-09-14T13:39:23",9,"*С крыши Люпен видит что происходит что происходит в пирсе, а ещё рядом с ним сидит крыса, гнилая, мертвая и трусясь поворачивает голову смотря отсутствующими глазницами. Его заметили.*",210356,null],[210360,"2026-09-14T13:40:04",9,"*Карета пуста, в ней никого нет, даже стражник что ее стерёг побежал успокаивать толпу.*",210358,null],[210361,"2026-09-14T13:40:58",20,"/можно просмотреться что она точно пуста?",210360,null],[210362,"2026-09-14T13:41:46",20,"/r +d20+2 Рен присматривается через глаза совы, от нее же помощь",194458,null],[210364,"2026-09-14T13:41:54",20,"/ну чтож...",194458,null],[210365,"2026-09-14T13:42:03",18,"*По мере приближения толпы к лодкам Лют потихоньку начинает продвигаться вперёд дабы оказаться в первых рядах как только будет возможность увидеть что в лодках...",194458,null],[210367,"2026-09-14T13:42:16",9,"//В окошко подлететь посмотреть?)",194458,null],[210368,"2026-09-14T13:42:43",17,"Быстров выхватив лук озотник прицелился и выпустил стрелу в крысу\n\n/ Стреляю в крысу",210359,null],[210372,"2026-09-14T13:43:11",20,"/ага\n/Походу все мои фамильяра будут смертниками...",210367,null],[210375,"2026-09-14T13:43:27",17,"/r +6 Струляю",194458,null],[210378,"2026-09-14T13:43:45",17,"/r d6+4 Урон",194458,null],[210380,"2026-09-14T13:44:29",9,"*Сев поближе и заглянув в окошко за занавесками ты видишь карету что общита изнутри багровым бархатом. Она реально пуста.*",210372,null],[210384,"2026-09-14T13:45:10",20,"/верим верим...",210380,null],[210385,"2026-09-14T13:45:24",9,"*Люпен наблюдает как крыса прошитая стрелой к крыше еще шевелится, это кажется фамильяр и он не реагирует на физический урон.*",194458,null],[210386,"2026-09-14T13:45:35",18,"*Лют уловил  краем уха просвистевшую в отделении стрелу и завертел головой силясь понять откуда исходит угроза, в тоже время он уже во втором ряду толпы...",194458,null],[210388,"2026-09-14T13:46:01",17,"Тогда Люпен хватает мешком эту крысу",194458,null],[210389,"2026-09-14T13:46:13",17,"/r +3 Ловкость рук",194458,null],[210393,"2026-09-14T13:46:27",9,"//Преим, она прошита стрелой",210390,null],[210406,"2026-09-14T13:51:16",9,"*Пока Люпен пытаеися запеленать крысу из лодочной в сторону доков выплывает одинокая лодка.*\n\n*На лодке 2 помощника в темном и фигура мага, некроманта в балахоне, видна только нижняя часть чего бледного лица. Да, он в модных ботинках на каблуках.*\n\nТемная фигура — Вы слишком долго испытывали моё терпение. — *Он схватился за свисток на шее и дунул в него... а потом указал на Люпена на крыше. Его двоя помощников на лодке берут арбалеты и скоро будут готовы стрелять в охотника.*\n\n*Староста в замешательствес он растерян и не знает что делать, всё сорвалось, ряд неудач и вот он тут.*",194458,null],[210409,"2026-09-14T13:52:39",20,"/чисто в теории может ли Рен какой-то телепатической связью с миром позвать Бормотуна 🤔",194458,null],[210410,"2026-09-14T13:53:24",18,"//Лют далеко от лодки с некромантом и его подельниками, подельники его наймиты или из стражи поселения?",194458,null],[210412,"2026-09-14T13:54:42",20,"*Рен видит это глазами фамильяра и тут же посылает его к Люту как можно скорее*\n\n\"Огонь, быстрее отдай его сове, чтобы она сбросила на лодку!\" *Слышишь ты голос пацана в голове, когда к тебе подлетает сова*",194458,null],[210413,"2026-09-14T13:55:52",9,"//Люпен и выходит фамильяр внимательность",194458,null],[210415,"2026-09-14T13:56:10",18,"*передаю пернатику...",210412,null],[210417,"2026-09-14T13:56:37",20,"/r d20+3",210413,null],[210420,"2026-09-14T13:57:29",9,"*Фамильяр видит как брезенты в лодках с грузом начинают шевелиться и скоро подымутся.*",210418,null],[210421,"2026-09-14T13:58:57",18,"Лют ошаляло увидев это орёт:\n-.... ... ...!!! Жги некроманта! \nУказывает рукой на лодку с некромантом и его подельникаии.",210420,null],[210422,"2026-09-14T14:00:26",20,"\"И трупы поднимаются с лодок\" *предупреждает Люта Рен*\n\n- Анастасия, трупы сейчас встанут на лодках! Нужно предупредить людей! *Ее он придупреждает вслуз, все ещё сосредоточившись на зрении фамильяра. И пытаясь решить что эффективнее - огонь на трупы или на лодку. И думать нужно быстрее...*",210420,null],[210423,"2026-09-14T14:00:32",9,"//Ты не видишь как брезенты шевелятся за толпой, мб темную фигуру на лодке",210421,null],[210424,"2026-09-14T14:00:49",9,"//А, тогда знаешь",210422,null],[210425,"2026-09-14T14:00:50",20,"/Рен предупредил",210423,null],[210426,"2026-09-14T14:01:45",9,"//Николай пропадает, сейчас или он скпоется с крфли или в него начнут стрелять. Он отстает",194458,null],[210427,"2026-09-14T14:02:05",20,"/ждём тогда",210426,null],[210428,"2026-09-14T14:02:08",17,"/r +2 Внимание",210413,null],[210430,"2026-09-14T14:02:39",9,"*В тебя целятся с двур арбалетов, трупы скоро встанут с лодок, крысу не забрать.*",210429,null],[210431,"2026-09-14T14:02:49",17,"Понимая, что дело пахнет писюнами\n\nНекромантскими. Люпен скатывается с крыши и укрывается среди ящиков и бочек",194458,null],[210432,"2026-09-14T14:03:03",17,"/r +4 прячусь, на крысу пофиг",194458,null],[210434,"2026-09-14T14:03:29",18,"*мысленно всем кто слышит: -рубить голову, жги некроманта! \nСам же начинает распихивать селян, призывая из бежать по домам и вооружаться топорами, вилами и факелами...",194458,null],[210435,"2026-09-14T14:03:41",9,"*Люпена упустили но двое человек готовы стрелять как только он высунется.*",194458,null],[210436,"2026-09-14T14:05:12",9,"*Фигуры под брезентами встают, толпа затихла, стало очень тихо.*\n\nФигура в тёмном одеянии — Поднимайся моё воинство, сегодня жители с этой деревни станут в ваши ряды.",194458,null],[210437,"2026-09-14T14:05:42",17,"Из засады сам люпен ждёт момента когда в его сторону перестанут смотреть, может в момент швартовки к пирсу",210435,null],[210438,"2026-09-14T14:07:14",9,"*Мертвецы переворачиваются из лодок, толпа почти в пять десятков, падает, ползет, плывет по воде только дюжина стала на ноги и плетётся по пирсу, по берегу. Зомби и скелеты, иссохшие трупы.*",194458,null],[210440,"2026-09-14T14:07:32",20,"/можно уже действовать фамильяром пока арбалетчики отвлечены?\n/Или иня?",194458,null],[210441,"2026-09-14T14:07:40",9,"//Иня выходит, поду статблоки расчехлять",194458,null],[210442,"2026-09-14T14:07:58",17,"/r +3 Иня",194458,null],[210445,"2026-09-14T14:08:16",20,"/r d20+2",194458,null],[210448,"2026-09-14T14:10:27",18,"/roll d20+3",194458,null],[210450,"2026-09-14T14:12:04",9,"/roll 1d20+2 некромант\n/roll 1d20+4 две тени слуги",194458,null],[210455,"2026-09-14T14:16:16",9,"// Инициатива:\n\nЛюпен — 22\n\nРой мертвых крыс (почти додавили)\n\nДве тени слуги — 18\n\nПервая волна зомби \n\nЛют — 15\n\nПервая волна скелетов\n\nРен — 11\n\nВторая волна зомби \n\nНекромант — 11\n\nВторая волна скелетов\n\nСельские люди и Анастасия\n\nТретья волна зомби",194458,null],[210457,"2026-09-14T14:16:58",17,"/ Огласи цели которые я вижу в 120 футах и могу выстрелить пожалуйста",194458,null],[210461,"2026-09-14T14:20:18",9,"*Первая волна зомби движется с пирса. Люпен прячется за лодочной, в него целятся тени, но из его положения видны зомби что идут по пирсу. Фамильяр летит в небе с алхимичесуим огнем, Рен и Лют в затихшей толпе людей.*\n\n*На скопище в 30-40 крестьян  прет первая волна зомби, их там около десятка, остальные подальше и медленные не успели повылазить с лодок.*",194458,null],[210463,"2026-09-14T14:21:39",9,"//Зомби или сам некромант если выглянешь, но ты видел что в тебя начнут сразу стрелять его слуги. И у тебя же длинный тот лук? Хотя сам.",210457,null],[210467,"2026-09-14T14:23:20",17,"/ Ну фактически после моего выстрела.",194458,null],[210468,"2026-09-14T14:23:25",17,"/ Они будут делать реакцию",194458,null],[210471,"2026-09-14T14:25:01",17,"Люпен прикинул варианты.\n\n\n\"Тот тип в черной мантии ну как пить дать главный ублюдок.\"\n\nОн приготовил стрелу и натянул лук что было сил, пустил ее в некроманта \n\nЗнал что в него будут стрелять в ответ, но позиция некроманта на лодке пока слабая. Уклоняться некуда. А в воде может быть бормотун.",194458,null],[210472,"2026-09-14T14:25:15",17,"/r 3d20+1 Пошла стрела",194458,null],[210474,"2026-09-14T14:25:21",17,"/ 15",194458,null],[210476,"2026-09-14T14:25:43",17,"/r d6+3+1+5+10 Колющего если попал",194458,null],[210478,"2026-09-14T14:25:56",9,"*На некроманте засверкала защитная магич и стрела отскочила.*\n\n//Щит",194458,null],[210480,"2026-09-14T14:26:41",17,"\"от сукин сын\"\n\nИ Люпен побежал за лодочную за укрытие \n\n/ стреляй КД 13",194458,null],[210481,"2026-09-14T14:26:51",9,"*Слуги завидев откуда выстрел выпускают болты в Люпена.*",194458,null],[210483,"2026-09-14T14:27:22",9,"/roll 1d20+6 первый заготовленное\n/roll 1d20+6 второй заготовленное",194458,null],[210485,"2026-09-14T14:27:50",9,"/roll 1d8+4 болт прилетел",194458,null],[210488,"2026-09-14T14:28:41",17,"Стрела прилетела в плечо \n\nЛюпен сдал зубы и резким движением обломил древко убегая за укрытие",194458,null],[210490,"2026-09-14T14:28:50",17,"/ конец хода",194458,null],[210491,"2026-09-14T14:29:12",9,"//На скрыт не кинешь бонусным?",194458,null],[210493,"2026-09-14T14:30:28",17,"/ Буду. Да",194458,null],[210494,"2026-09-14T14:30:32",17,"/r +4 q",194458,null],[210496,"2026-09-14T14:30:55",20,"/может вдохновение докинуть...",194458,null],[210497,"2026-09-14T14:31:06",17,"/r d4 Да",194458,null],[210500,"2026-09-14T14:31:13",9,"*Из деревни выбегают крысы, из щелей из нор, немертвые, страшные скелетики, нападают на людей, те кричат, топчут их, парочку упало в обморок.*",194458,null],[210502,"2026-09-14T14:34:10",9,"*Тени заряжают арбалеты и готовы стрелять во все что угрожает господину, но не смотрят в небо, не ждут подвоха. Зомби плетутся к паникующим людям, некоторые убегают от медленных мертвецов, но из-за крыс под ногами не все могут нормально среагировать на угрозу и убежать.*\n\n// Лют @OIK77GK",194458,null],[210513,"2026-09-14T14:38:13",18,"- эх, говорил хер Хауптман, помрёшь ты, Лют, хероем... \nПривычным движением поднимает щит и молот вставая в боевую позицию.",194458,null],[210515,"2026-09-14T14:38:27",18,"//зомби прям рядом и могу бить?",194458,null],[210520,"2026-09-14T14:39:23",18,"//ну тады по ближайшему:",194458,null],[210525,"2026-09-14T14:40:05",18,"/roll d20+3+2",194458,null],[210529,"2026-09-14T14:40:30",9,"//Попал, у зомби кд 8",194458,null],[210531,"2026-09-14T14:40:46",20,"/на пирсе по картинке есть забор, они его уже прошли?",194458,null],[210533,"2026-09-14T14:41:06",18,"/roll d8+3",194458,null],[210535,"2026-09-14T14:41:50",9,"*Часть зомби перелезла через забор и почти дошла к людям.*\n\n//Поэтому я разделил на группы нежить",210531,null],[210539,"2026-09-14T14:42:50",9,"*Удар будто рубишь дерево не топором, клинок лишь немного ранил мертвеца.*\n\n//Ход?",210534,null],[210547,"2026-09-14T14:44:16",18,"//ход",210539,null],[210564,"2026-09-14T14:47:13",9,"*Из реки начинают вылазить легкие и доволе шустрые в отличие от зомби скелеты. Парочка совсем без труда перебирается через ограду.*\n\n//Рен, твой ход",194458,null],[210579,"2026-09-14T14:50:16",20,"*Рен отдает мысленный приказ фамильяру сбросить огонь на лодку*\n\n*Сам лихорадочно осматривает окрестности, пытаясь найти способ замедлить толпу - куча бочек или бревен, которые можно на них столкнуть подожженными. Что-то на местности - что угодно чтобы нанести массовый урон. Если пытаться остановить их как Лют по одному они здесь все погибнут*",194458,null],[210581,"2026-09-14T14:50:24",20,"/что есть вокруг?",194458,null],[210590,"2026-09-14T14:53:50",9,"*Прилавки рыбного рынка, забор мешает немного мертвецам. У лодочной связанны веревками брёвна для будущиз лодок. Бочки пустые, ящики, веревки. Это пирс деревни что основном промышляла рыбалкой, сети и снасти почти везде.*",194458,null],[210598,"2026-09-14T15:00:28",20,"*Рен оглядывает людей, стараясь увидеть тех, кто способен бороться*\n\n*Решает что нужно попробовать организовать хоть какое-то сопротивление*\n\n- НУЖНО ЗАДЕРЖАТЬ ИХ И СБИТЬ! СПУСТИТЕ НА НИХ ВОН ТЕ БРЕВНА И ПОДОЖГИТЕ!!! *Он старается перекричать хаос, указывая на бревна у лодочной*\n\n- НУЖНО СОЗДАТЬ ПРЕГРАДЫ ДЛЯ ПЕРВЫХ, ЧТОБЫ ПОСЛЕДУЮЩИЕ УЖЕ НЕ ПРОЛЕЗЛИ ИЗ-ЗА ТЕЛ!\n\n- НЕСИТЕ ФАКЕЛЫ И ВСЕ МАСЛО! И ГОРЮЧЕЕ ЧТО НАЙДЕТЕ!!! СЕГОДНЯ ЗДЕСЬ УПОКОЮТСЯ ОНИ А НЕ МЫ!!",194458,null],[210599,"2026-09-14T15:00:47",20,"/r +d20+2 на выступление",194458,null],[210604,"2026-09-14T15:01:35",17,"/ Эх вот бы фамильяр принес мне доспехи мага))",194458,null],[210605,"2026-09-14T15:02:06",20,"/намек понят, если выживет после подарочка для лодки попробую",210604,null],[210616,"2026-09-14T15:07:36",20,"*Ну а фамильяр тем временем пролетает прямо к лодке, зависая над ней в воздухе и сбрасывая алхимический огонь прямо вниз, чтоб точно не промахнуться*",194458,null],[210628,"2026-09-14T15:14:54",9,"//Атака фамильяром, лодка большая промахнутся сложно, через ловкость",194458,null],[210629,"2026-09-14T15:15:42",20,"/r d20+3 сброс огня",210628,null],[210631,"2026-09-14T15:15:55",20,"/если не хватит докину вдохновение",194458,null],[210635,"2026-09-14T15:17:40",20,"/r d4",194458,null],[210638,"2026-09-14T15:18:00",20,"/удача кончилась, но надеюсь хватит(",194458,null],[210639,"2026-09-14T15:18:18",9,"//Как раз 13 хватает, щас опишу, щанят прост",194458,null],[210655,"2026-09-14T15:24:20",9,"*Люди похватали кто что мог. ДАЖЕ ПОДРОСТОК НЕ ПАНИКОВАЛ КАК ОНИ ВЗРОСЛЫЕ МОГЛИ!? В мертвецов полетели снасти и сети, что похрабрее взял вилы и палки сталкивать нежить. Не то чтобы это сильно помогло, но достаточно замедлило*\n\n*Алхимический огонь падает в лодку, да она влажная, да, но на дне лежали сети и сама лодка деревянная, зазглась почти как спичка. Некромант со своими слугами переворачиваются в лодке и палают в воду. Но не тонут, плавать умеют.*",194458,null],[210657,"2026-09-14T15:24:34",9,"//Больше атака у теней слуг не заготовленна",194458,null],[210665,"2026-09-14T15:27:59",9,"// Ход всё?",194458,null],[210667,"2026-09-14T15:28:35",20,"/если выступление было действием то да, все",210665,null],[210701,"2026-09-14T15:40:33",9,"*Мертвецы вылазят из воды, налегают на людей толпой, добрая половина уже полезла вперед, кого то укусили, кого-то толкнули, но люди пока стояли, не давали себя в обиду. Они храбро и не раз отстаивали свою деревню от монстров, мертвецы их испугают? Ни в жизнь!*\n\nДевушка (Анастасия) — А ну бабоньки, зрвите помощь! Все что горит сюда и мужиков тоже зовите, щас мы зададим. — *Она раздавив ногой очередную восставшую крысу оборвала юбку и бежит помогать собрать народ.*\n\nТучный староста — Черт, защищайте людей! — *Он среагировал почти сразу, стража перехватив копья переминулась сталкивать нежить вместе с ними. Сам староста куда то убегает, но перед этим он протрубил в рожок, наверное подзывал подмогу.*\n\nРыбак — Ахахах, а я все думал что же в лодке. — *Он смотанной удочкой из-за спин людей хлестко ударил одного мертвеца по черепушке, тот отвлекся и его свалили в воду.*\n\n*Некромант пытался и все же кое как первым вылез на пирс, сейчас отряхивается. Его тёмная мантия выглядит не так хорошо.*",194458,null],[210702,"2026-09-14T15:40:47",9,"// @dunchev ход люпена, слишком много переменных, эх",194458,null],[210736,"2026-09-14T15:46:31",20,"/давай, снайпер - бей гада",194458,null],[210742,"2026-09-14T15:47:24",17,"Люпен делает выстрел на выдохе по некроманту",194458,null],[210743,"2026-09-14T15:47:30",17,"/ Я хз чё делать тут толпа",194458,null],[210755,"2026-09-14T15:49:23",20,"/добить некроманта с подсосами, зомбаков согнать в кучу и сжечь, не давая вилезти из огнища",210743,null],[210756,"2026-09-14T15:49:42",20,"/с полной горожан и стражей может получиться",194458,null],[210765,"2026-09-14T15:51:09",9,"//Зомби сильнее и выносливее людей, на справку, люди лишь оттягивают неизбежное... все в ваших руках",194458,null],[210781,"2026-09-14T15:53:38",20,"/тогда надо думать...",210765,null],[210794,"2026-09-14T15:56:15",17,"/r 3d20+1\n\nd6+19 если попал",194458,null],[210795,"2026-09-14T15:56:16",17,"Потом меняет позицию и укрывается в укромном месте",194458,null],[210798,"2026-09-14T15:56:27",17,"/r +4 Скрытность",194458,null],[210800,"2026-09-14T15:56:28",17,"/ инет плохой",194458,null],[210809,"2026-09-14T16:00:55",9,"*Фигура некроманта снова покрылась защитной пленкой и стрела отскочила от него.*\n\n*Прислужники выбираются на пирс вслед за господином, один из них обранил арбалет в воде.*\n\n*Зомби прут на людей, часть забора под таким напором упала.*\n\n*Лют вилит что просто бить мало поможет делу.*\n\n// @OIK77GK твой ход",194458,null],[210821,"2026-09-14T16:07:40",18,"/метательным копьём молний в некроманта",194458,null],[210823,"2026-09-14T16:08:18",18,"/roll d20+3+2",194458,null],[210825,"2026-09-14T16:08:47",9,"//Такс, щас посмотрю точнее копьё чтобы описать эффекты",194458,null],[210829,"2026-09-14T16:10:23",9,"/roll 1d20+2 некр\n/roll 1d20+4 слуга\n/roll 1d20+4 слуга",194458,null],[210835,"2026-09-14T16:10:44",9,"//Кинь 4д6 урона електричеством)",194458,null],[210838,"2026-09-14T16:11:17",20,"/о, они как раз мокренькие)",210835,null],[210846,"2026-09-14T16:23:10",18,"/roll 4d6",210835,null],[210900,"2026-09-14T16:39:55",9,"*Молнией копьё озарило этот крохотный деревенский пирс, запахло паленой плотью, пару скелетов оно снесло на своём пути и хотя Люц целился в некроманта оно пролетело мимо в воду и осталось плавать на поверхности, но перед этим хорошо прожарив троицу что только что вылезла из воды. У некроманта затлелась одежда, один из слуг теней был сильно опален, а другой вовремя увернулся. Кажется слуги некроманта смотрят на люта как на угрозу.*\n\n*Люди вдохновленные явлением начали отбиваться ещё яростнее.*\n\n— С нами герой! Маг!\n\n— Мы победим!\n\n//Лют держи вдохнову, но полноценную та что с перекидыванием, тебя поддерживает народ!",194458,null],[210901,"2026-09-14T16:40:22",9,"//Рен, твой ход если Лют всё",194458,null],[210907,"2026-09-14T16:41:06",18,"-.....ь!",194458,null],[210908,"2026-09-14T16:41:11",18,"//ход.",194458,null],[210921,"2026-09-14T16:44:17",20,"*Рен отдает приказ фамильяру - помогать Люту*\n\n*Сам фокусируется на маге. Он видел, как тот отбивал стрелы Люпена с помощью щита. Нужно попробовать дестабилизировать его достаточно, чтобы не дать ему провернуть такое снова*\n\n*Собирается с силами и применяет излюбленный телепатический трюк*",194458,null],[210926,"2026-09-14T16:44:54",20,"/r +d20+3 обман",194458,null],[210930,"2026-09-14T16:45:51",20,"*Сзади мага и прихвостней из воды раздается оглушительный рев(?), тот в точь как у Бормотуна!*",194458,null],[210932,"2026-09-14T16:46:21",9,"//Напомни дальность своей телепатии?",194458,null],[210934,"2026-09-14T16:47:33",20,"//60 вроде, но думала через сову ещё работает",194458,null],[210945,"2026-09-14T16:49:28",9,"//Хм, щас прикину, вродь хватает с натяжкой если стоишь поближе к забору",194458,null],[210948,"2026-09-14T16:49:48",9,"/roll 1d20+3 проницательность",194458,null],[210952,"2026-09-14T16:50:49",9,"//Это весь ход?",210934,null],[210956,"2026-09-14T16:51:49",20,"/ещё осматриваю обстановку, что происходит и как держаться люди против зомбаков",210952,null],[210957,"2026-09-14T16:52:17",9,"//Я просто щас опишу все разом, вот и спрашиваю)",194458,null],[210958,"2026-09-14T16:53:26",20,"/ну тогда Рен ещё отходит от забор подальше от противников и конец хода",194458,null],[210999,"2026-09-14T17:08:20",9,"*Некромант отвлеченный оборачивается на звук который якобы слышал, но вот его слуги никак не среагировали, будто им было всё равно.*\n\nВ темном балахоне — Жалкие фокусы, вы удумали меня обмануть. — *Больше он не поведётся, выступает немного вперед готовый колдовать (но в этом ходу потратил действие на осмотр).*\n\n*Немертвая крыса (тот фамильяр) спрыгивает с крыши к Люпену и мешает ему прыгая, норовя укусить (даёт помеху).*\n\n*Припеченные молниеносным копьём. В сетях запутанные меривецы лезут вперёд. Порвались первые сети, пару раненых оттащили от прямого столкновения, люди не справлялись. Анастасия еще не пришла с подмогой, старосты нет рядом, прибежало лишь пару мужиков с соседних домов.*",194458,null],[211002,"2026-09-14T17:09:04",9,"/roll 1d20+4 скелет по люту\n/roll 1d20+3 зомби тоже",194458,null],[211008,"2026-09-14T17:10:15",20,"/а как крыса мешает если ее пригвоздили стрелой, а Люпен уже ушел с крыши?",194458,null],[211013,"2026-09-14T17:11:07",9,"*Челюсти зомби клацнули перед лицом Люта и сверху прилетело ржавым мечом что вылезший из воды скелет держал в руках.*",194458,null],[211014,"2026-09-14T17:11:43",9,"/roll 1d6+2 колющего люту если кд не двадцать два",194458,null],[211016,"2026-09-14T17:11:52",17,"/ Ну я спрятался вроде на 17 крыса как нашла?",194458,null],[211017,"2026-09-14T17:12:02",9,"//Снялась, не один ход прошел, стрела вообще ей урона не нанесла",211008,null],[211025,"2026-09-14T17:13:18",9,"//Ты прячешься но врагам примерно известно где тебя искать, зайдя за укрытие за которым ты они точно увидят тебя без проверок?",211016,null],[211027,"2026-09-14T17:14:31",17,"/ Вообще то я перемещаясь после того как скрываюсь они приходят туда а там никого уже",194458,null],[211028,"2026-09-14T17:14:36",17,"/ у меня 35 скорости",194458,null],[211032,"2026-09-14T17:14:46",17,"/ я писал что перемещаясь просто не вижу смысла душиться",194458,null],[211033,"2026-09-14T17:14:53",17,"/ Ты должен кидать вниаиние выше моей скрытности",194458,null],[211034,"2026-09-14T17:14:57",17,"/ По правилам",194458,null],[211037,"2026-09-14T17:15:37",9,"//Хм а куда ты переместился? Крыса могла видеть тебя с крыши взглянув вниз?",194458,null],[211041,"2026-09-14T17:16:44",17,"/ В бочку спрятался",194458,null],[211042,"2026-09-14T17:16:51",17,"/ Как в самом первом побеге",194458,null],[211044,"2026-09-14T17:16:54",17,"/ ))",194458,null],[211045,"2026-09-14T17:17:01",17,"/ Ладно похер. Крыса около мегя",194458,null],[211046,"2026-09-14T17:17:03",17,"/ Пусть",194458,null],[211051,"2026-09-14T17:17:20",17,"/ Не хочешь чтобы некроманта был шанс пробить. Я даю по папкам и пусть все горит нахуй",194458,null],[211053,"2026-09-14T17:17:30",9,"/roll 1d20 внимание крысы, нюха нет у неё, мертва, вщамен на имун к урону обычному",194458,null],[211056,"2026-09-14T17:17:39",17,"/ Я ещё не понял что значит крыса невосприимчива к физическим атакам",194458,null],[211057,"2026-09-14T17:17:41",17,"/ Ебать",194458,null],[211058,"2026-09-14T17:17:44",9,"//Крыса не меша5т)",194458,null],[211059,"2026-09-14T17:18:56",9,"//Некромант постарался, это мерзость",211056,null],[211061,"2026-09-14T17:19:08",17,"/ Хорошо жду хода",194458,null],[211063,"2026-09-14T17:19:45",9,"//Твой ход как раз, люта ударили",194458,null],[211070,"2026-09-14T17:21:59",17,"Выскакиеваю из бочки бегу на угол выстрела по некроманту и стреляю\n\nКрышка бочки летит на крысу",194458,null],[211071,"2026-09-14T17:22:11",17,"/r 3d20+1\n\nd6+19",194458,null],[211073,"2026-09-14T17:22:47",17,"Убегаю назад и забегаю в случайный дом прячусь там",194458,null],[211075,"2026-09-14T17:22:56",17,"/r +4",194458,null],[211077,"2026-09-14T17:23:14",17,"/Конец хода",194458,null],[211095,"2026-09-14T17:36:38",9,"*Стрела просто пролетела мимо.*",194458,null],[211097,"2026-09-14T17:37:05",9,"/roll 1d20+6 арбалетный болт\n/roll 1d20+6 кинджал",194458,null],[211106,"2026-09-14T17:38:21",9,"*Тени движутся ближе к людям и битве, одна стреляет в люта из арбалета а вторая метает кинджал.*\n\n*Кажется метнув копьё он привлек много внимания к своей персоне.*\n\n//Кто попал?",211098,null],[211109,"2026-09-14T17:39:28",18,"//КД 19",211106,null],[211110,"2026-09-14T17:39:43",18,"//болт получаеися",194458,null],[211168,"2026-09-14T18:00:50",9,"/roll 1d8+4 болтом и твой ход, тени за мертвецами, одна все еще вощле еекроманта, а другая поближе подошла, к ней 20 футов сего и 10 футов из них стена мертвецов",211110,null],[211219,"2026-09-14T18:18:46",18,"//рывком на 60 футов от стены зомбей и скелетов",194458,null],[211222,"2026-09-14T18:20:33",9,"/roll 1d20+3 провоцирка от какого то из зомбей",211219,null],[211226,"2026-09-14T18:21:39",20,"/эх, чёт у меня в этом квесте вообще опускаются руки \n/Валим поитогу?",194458,null],[211268,"2026-09-14T18:33:35",18,"/я точно да",211226,null],[211281,"2026-09-14T18:38:30",9,"//Собираетесь убегать — немного обыграйте побег и это решение",194458,null],[211290,"2026-09-14T18:43:36",18,"*Лют очень быстро, без оглядки, через ворота по дороге по которой приехали. Скорым маршем к родному домику в лесу. Без денег, но живой.",211281,null],[211295,"2026-09-14T18:44:37",9,"//копье в реку выбросил тоже",194458,null],[211300,"2026-09-14T18:45:27",9,"*Рен наблюдает как Лют бежит, за ним и часть людей. Он их вдохновил боротся и тут же сбежал, это ударило по морали.*",211290,null],[211311,"2026-09-14T18:49:09",9,"//Да? Тогда отлично",194458,null],[211312,"2026-09-14T18:50:03",20,"*Рен отыскивает Анастасию, быстро хватая ее за руку и ведя за собой*\n\n- Нужно отступить - долго мы их наступление не сдержим,подмога все не идёт, а тактика с сжиганием не сработала. Сейчас нужно просто постараться сохранить как можно больше жизней - пусть и бегством\n\n*Он оглядывается назад. Мертвецы медленные - шансы убежать у селян и у них самих есть.*\n\n*Все что он сейчас может сделать - это попытаться организовать отход так, чтобы не возникла давка и лишняя паника*",211300,null],[211313,"2026-09-14T18:50:20",20,"/r +d20+2 выступление",194458,null],[211315,"2026-09-14T18:51:26",20,"*но слова как будто застревают в горле. А что он может? Он просто мальчишка*\n\n- Они медленнее вас - используйте это чтобы создать разрыв!",194458,null],[211316,"2026-09-14T18:51:30",20,"/а в пизду",194458,null],[211317,"2026-09-14T18:52:42",9,"Девушка (Анастасия) — Прости малыш, беги. Я постараюсь справится. — *Она прибежала с местными бабами и подмогой как раз. Сдаваться? Не намеренна. Потрепала Рена по волосам и взяв вилы ринулась в бой.*",194458,null],[211319,"2026-09-14T18:53:41",20,"/можно хоть фамильяром глянуть, идёт там хоть какая-то подмога?",194458,null],[211320,"2026-09-14T18:53:57",9,"//Глянь. Щас твой ход",194458,null],[211321,"2026-09-14T18:54:41",20,"*Рен смотрит глазами фамильяра, летя в ту сторону куда убежал староста*",211320,null],[211323,"2026-09-14T18:55:47",9,"*Он собирает мужиков, даже сам кольчугу одевает, раздает оружие, но их дюжина всего, не справятся. Это дело происходит за ратушой.*",194458,null],[211328,"2026-09-14T18:57:15",20,"/ну короче окружения для тактики нифига нет, у обывателей естественно ничего нет\n/ни один план нормально так и не сработал",194458,null],[211330,"2026-09-14T18:57:39",20,"/хз что мы тут вообще могли делать кроме смерти или отступления",194458,null],[211343,"2026-09-14T19:02:48",9,"//Решите что будете делать как нибудь, не подгоняю",194458,null],[211352,"2026-09-14T19:05:04",18,"/послушать истории в таверне из разряда \"сами виноваты\" о том как сожрали мертвяки под чистую село на границе с Веспиралью, а те кого не сожрали попередохли от поносу...",211330,null],[211354,"2026-09-14T19:07:05",18,"*Лют умотав от ворот уже ярдов на 100, оглядывается:\n- а и х... с ним! \nИ чешет дальше.",211343,null],[212500,"2026-09-15T07:01:27",9,"//Рен и Люпен, если убегаете окончательно — чекние, опишу итоги.",194458,null],[212672,"2026-09-15T10:13:52",17,"Люпен бежит со всех ног мимо Рена и тянет его за руку\n\n— Бежим, пацан. Тут нам уже ничего не сделать.",194458,null],[212673,"2026-09-15T10:13:59",17,"/Всё мы убежали",194458,null],[212675,"2026-09-15T10:15:31",20,"*Рен с сожалением смотрит на деревню позади, следуя за Люпеном*\n\n*Похоже они и правда тут бессильны...*\n\n/Да, убегаем(",212672,null],[212676,"2026-09-15T10:15:59",17,"/Я хочу отписать еще разговор с Реном. Но это уже когда сбежали. Поэтому на очередь постов не влияет",194458,null],[212796,"2026-09-15T11:43:05",17,"Люпен долго молчит. Идёт рядом, не оглядываясь на зарево позади. Потом резко останавливается.\n\n— Запомни этот город, Рен. Но не мертвецов и не крики и даже не то, как мы оттуда бежали.\n\nОн оглядывается наконец на город позади\n\n— Запомни момент, когда мы уже знали правду… и всё ещё пытались играть по их правилам\n\nОн сплёвывает в траву\n\n— Мы знали, что староста врёт. Знали, что в лодочной что-то прячут. Знали, что нас специально отправили убивать Бормотуна, чтобы убрать подальше. И что мы сделали?\nПошли просить разрешения у крысы проверить её собственную нору.",194458,null],[212811,"2026-09-15T11:46:45",17,"Люпен проводит ладонью по лицу. Голос становится тише.\n\n— Я всё думал, намнужны доказательства. Нужно, чтобы люди увидели. Нужно сделать всё правильно. А знаешь, что нам дали эти несколько часов правильности?\n\n— Некроманту, ебучему Старосте и мертвецам время. Время что бы понять, что они загнаны в угол. Мы спровоцировали эту бойню, Рен.\n\nОн смотрит на Рена\n\n— Мы привели туда толпу. Людей без оружия, без строя, без понятия, что их ждёт. Я не снял некроманта, он волшебник. Ты не смог заставить перепуганных мужиков вдруг стать солдатами. Лют не удержал эту орду. На что мы надеялись? Что мертвецов там мало? Но мы же видели пустые могилы. Десятки.\n\n\n— Я чувствую вину. Черт, она гложет меня теперь. Женщин, детей, рвали зомби. А всё что я смог сделать это выпустить пару стрел в ублюдка который выпустил их на город. И не попал.",194458,null],[212815,"2026-09-15T11:47:48",17,"— Если бы мы только... Обманули его, что убили Бормотуна. Он бы поплыл и лягух сделал всё за нас.",194458,null],[212816,"2026-09-15T11:47:55",17,"Он машет рукой в бессильном жесте",194458,null],[212818,"2026-09-15T11:48:15",17,"Подходит к стволу дерева рядом\n\nЭто берёзка\n\nИ со всей дури бьёт кулаком\n\n— СУКА СУКА СУКА",194458,null],[212827,"2026-09-15T11:54:20",20,"*Рен идёт, опустив голову. Молча слушая старшего*\n\n*Люпен прав. Это его ошибка - слишком медленно действовали, слишком неосторожно. Нужно было выследить того чертового некроманта как только события на площади пошли не так. А они просто потеряли время...подставили людей под удар...*\n\n*А позади теперь только разруха и мертвецы. И кровь, которая на его руках*\n\n*Бессилие, тошнотворное бессилие что преследовало его в прошлом вновь накатывает с головой. Каждая жизнь что оборвалась сегодня - результат его последовательных ошибок. Каждая.*\n\n-...",194458,null],[212831,"2026-09-15T12:03:45",20,"*Что-то в груди странно сжимается, золотистый свет становится чуть ярче когда зрение на несколько секунд мутнеет*\n\n*Надо было убить, просто убить...убить...убить...*\n\n*На кончиках пальцев потрескивает неконтролируемые золотистые искры, обжигая пальцы*\n\n*Силы? У него бы их хватило, точно хватило. Смотреть как тот маг корчится в агонии, сломать его разум так, чтобы даже щит не спас. Раз за разом, пока он бы не молил о смерти. И потом ещё больше...*\n\n*Темные мысли льются спутанным бесконечным потоком, когда контроль утекает сквозь пальцы, слишком пошатанный событиями дня*\n\n/Не знаю как на самом деле должно действовать то безумие проклятого дворянства - но вижу что-то такое",194458,null],[212857,"2026-09-15T12:21:27",17,"Люпен возвращается к Рену. Костяши сбиты и кровоточат. Теперь в его голосе почти нет злости. Только усталость.\n\n— Пошли. Найдём себе другую работу.",194458,null],[212860,"2026-09-15T12:34:29",20,"*Рен вздрагивает услышав знакомый голос, резко выныривая из своего приступа. Золото гаснет. Странная волна чувств уходит, оставляя после себя лишь усталость и пустоту на душе*\n\n-...идем *тихо говорит он, кивая и следуя за Люпином.*\n\n*Ни слез, ни страха, ни истерики. Только рука сжимает краешек плаща мужчины впереди с отчаянием ребенка, который пытается ухватиться в этом мире хоть за что ни будь, что не рассыпаться*",212857,null],[212865,"2026-09-15T12:53:49",9,"*Лют потерял тогда копьё молний, его унесло рекой ниже по течению. Убегая его подобрал торговец да предложил подвезти, сговорившись со старым воякой договорились они на мешочек звонкого серебра с парой золотых что Лют поможет в дороге.*\n\n// копьё потерял, 20 золотых за охрану торговца и 500 опыта это с квестом отыграшем и прочим. @OIK77GK",194458,null],[212878,"2026-09-15T12:57:36",9,"*Рен с Люпеном остановились в деревушке по пути ночевать. Тогда они узнали что ночью мимо деревни проехала черная карета, часть умертвий за ней плелась а часть вместо лошадей тащила транспорт. Охотник который любил ночью выйти на промысел клялся что \"он видел это своими глазами!\"*\n\n// По 500 опыта за квест, отыгрыш и так далее.",194458,null],[212882,"2026-09-15T12:59:30",9,"*Дрейхолт остался стоять, но он уже не тот что прежде.*\n\n//Квест считаю провальным, не защитан, коментарии видел. И все же, спасибо за игру.)",194458,null],[219250,"2026-09-17T20:12:18",9,"ХХХХХХХХХХХХХХХХХХХХХХХХХ",194458,null],[233638,"2026-09-24T11:10:04",9,"⛰РЕЧНАЯ ДОЛИНА🏞\n\nМестность что лишь частично поглощенна некротическими облаками Веспирали, северозападнее. Не смотря на то что находится близ Вальдхейма, дикая охота не приходит сюда помогать местным. Много монстров, местячковая власть, разрозненные боевые деревни. Даже дети умеют держать оружие в руках, суровое место.",194458,null],[233639,"2026-09-24T11:10:25",9,"//Узнать подробности:\n\n— деревня \"Дрейгхолт\"\n\n— \"мост Троллей\"",233637,null],[233652,"2026-09-24T11:44:20",9,"Запас",194458,null],[233653,"2026-09-24T11:44:26",9,"ХХХХХХХХХХХХХХХХХХХХХХХХХХ",194458,null],[272641,"2026-10-17T13:41:48",9,"*Палящее солнце уже зашло. Путники путешествующие в тенях дороги, ночь уже близко, как и земля смерти. В лучах заходящего солнца, ваши дороги, ваша дорога.*",194458,null],[272642,"2026-10-17T13:43:05",9,"*Вас ждет деревня Вертимора, шёпот о работенке, подземелье что возможно хранит сокровище.*",233637,null],[272643,"2026-10-17T13:46:22",9,"*Вечерний свет уходящего заливает золотом ворота что виднеются впереди. Селение на холме, огороженное частоколом, старым. Усеянный костями ров, запах смерти и крови. Рычание.*",194458,null],[272646,"2026-10-17T13:48:40",9,"*Посреди дороги стоит телега, в ней мертвецы. Зобми скребутся в направлении живых путников, рычат и харчат, подсохшие, обессиленные.*",194458,null],[272651,"2026-10-17T13:52:05",9,"// @SheoSheol @DrawAndRip добро пожаловать в речную долину, поселение Вертимора, тут начнутся ваши приключения",194458,null],[272722,"2026-10-17T14:28:09",39,"*Эвкалипт как раз выходил из опушки леса, весь в ветках, грязи , матерясь и паралельно отцепливая репейник у себя с одежды, с ним подруку шел медведь, который как раз и вывел его из этого леса*\n*когда Эвкалипт попрощался с медведем, он пошел в сторону деревни, обходя телегу с мертвецами, с отвращением закрывая нос. Хотя сам он пах не лучше после двух месяцев блужданий по лесу и предгорьям в поисках хоть какого-то признака цивилизации*\n*подойдя к табличке с названием деревни, Эвкалипт поднял взгляд и ахуел* \n\n\nЙоб твою мать, куда я попал..... Я  ж был в темнограде! 😭",194458,null],[272728,"2026-10-17T14:29:43",27,"// Береги медведя! Предупреди его, чтобы он не садился в горящие машины!",272722,null],[272734,"2026-10-17T14:32:15",9,"*Медведь отдал честь и на своих четверых стал уходить в лес оставив Эвкалипта одного среди дороги.*",272722,null],[272758,"2026-10-17T14:42:03",39,"*Эвкалипт обречённо вздохнул, слегка всплакивая от осознания того что они с медведем наверняка больше не встрется.. А ведь за последние три недели медведь стал ему как родной брат, они вместе добывали пищу, гонялись за белками, и спали под открытым небом обнявшись, медведь согревал Эвкалипта своим телом холодными ночами.. И наверное лишь благодаря этому Эвкалипт не замёрз полностью* *да и к тому же, это ведь медведь вывел его сюда*\n*но, что ж. Как бы не было грустно, нужно идти, ведь карьера K-pop идола, сама себя не построит*\n \n-Ну, с богом! \n\n*Эвкалипт направился к воротам деревни, надесь что его туда хотя-бы пустят, ибо идти к следующей деревне ни физических, ни моральных сил у него уже нет*",194458,null],[272771,"2026-10-17T14:48:56",9,"*Тени становились выше и длиннее, свет заката освещал лишь верхнюю половину частокола. На часовой башне стоял дозорный в старой кольчужной рубах он приметил путника.*\n\nЧасовой — Стоять! Ты кто. — *Седещий мужик прищурился пытаясь рассмотреть путника получше.* — Откуда вылезло это чучело. Григорий, посмотри на этого бедного шута.\n\n*Позвав своего товарища, из башни часовых Эвкалипта рассматривают уже двое человек.*",272758,null],[272775,"2026-10-17T14:52:28",39,"*Эвкалипт цокнул языком и демонстративно,эффектно, провел по своим сальным, грязным волосам, заправив их назад*\n\n-хей! Попрошу не выражаться, я вообще-то будуший k-pop идол!\n\n\n*Эвкалипт немного помолчал, а затем неловко откашлялся*.. \n\n\n-Просто жизнь немного потрепала..",194458,null],[272785,"2026-10-17T14:56:14",9,"Часовой — Григорий, мы будем пускать окаянного? Он мне не нраывися. — *Он не шептался говоря вслух, второй только пожал плечами. Стражу пришлось самому решать, поэтому он начал засыпать вопросами:* — Кто ты, путник. Откуда идёшь и зачем?",194458,null],[272804,"2026-10-17T15:05:48",39,"-Меня зовут Эвкалипт, я из Темнограда, из города Ужацнезёма , просто хотелось поесть грибов, вот я и пошел их собирать, нашел полянку с красивыми грибочками и решил прям там и сожрать один.. А потом очнулся в каких-то горах..\n\n *Эвкалипт шмыгнул носом и вытер потёкшую соплю локтем*\n\n\n-ну и в общем, уже пару пару месяцев искал выход из леса, и вот наконец-то нашёл 🥹!!! \n\n\n\n*Эвкалипт говорит отряхивая свою леопардовую сумочку со стразиками от засохшей травы* \n\n-а кстати, Ужацнезёма далеко отсюда находится?",194458,null],[272847,"2026-10-17T15:20:46",9,"*Седеющий страж щурился как Эскиз пока слушал историю, думая что делать.*\n\nЧасовой — Шут гороховый. — *Леопардовый цвет был мужику не щнаком, а вот платья в горошек он видел.* — О Темнограде слыхал, но не более. Это как тебя помотало.\n\n*Думает, пускать ли Эвкалипта или нет, сомневается.*\n\n//Проверка \"выступление\" сл 10 чтобы тебя пропустили так",272804,null],[272863,"2026-10-17T15:26:35",39,"/roll 1d20+2 выступление",194458,null],[272878,"2026-10-17T15:31:17",29,"Маркус, продрал застланные очи от дневного сна. Место было неудобное и наспех выбранное. Из-за беспечности, прошлой ночью, рассвет застал Маркуса в расплох и он не успел подготовить убежище на день. Чуть ли не спотыкаясь о лесные коренья Маркус увидал узкую нору какого-то животного и ничего не оставалось кроме как залезть туда и надеяться, что хозяин норки не вернётся. Благо в течение дня этого так и не произошло. Ощущения после сна были ужасными. Всё тело болело от тесноты и давления земли, спать пришлось словно трупу. Маркус мгновение потянулся, после чего стал чистить свою одежду магией. Через минут десять после того как бог-солнце скрылся за горизонтом и его последние губительные лучи исчезли, Маркус был готов продолжать путешествие.",194458,null],[272906,"2026-10-17T15:40:45",39,"//стражникам поёт. Они от такого выступления 100% должны просто растаять//",272884,null],[272915,"2026-10-17T15:42:25",9,"*Маркус вышел на тропинку.*",272878,null],[272917,"2026-10-17T15:42:52",9,"*Нежить в телеге на него никак не отреагировала когда он шел мимо них.*",272646,null],[272922,"2026-10-17T15:45:49",9,"*У ворот заставы стоял кто-то и просился войти внутрь. Какой-то бродячий музыкант? Играл он ужасно. На стене стояли пару стражей и ругали его.*\n\nЧасовой — Иди нахуй отсюда. Уши вянут. — *Тот стражник был достаточно впечатлен ужасной игрой чтобы начать ругаться.*",272643,null],[272934,"2026-10-17T15:48:33",39,"*Эвкалипт театрально положил руку себе на лоб, и вторую на сердце* *он драматичным тоном, сказал*\n\n-ох! Какие вы жестокие!! Если не хотите пускать, то я лягу прямо здесь! А ведь я так слаб (нет) , и моё тело все исцарапано! Если я здесь умру, моя смерть будет на вашей совести!",194458,null],[272944,"2026-10-17T15:53:48",29,"Молодой человек, облачённый в пустынную, но богатую одежду с длинным мечом в руках, приблизился к воротам. Меч он держал в руках чуть ниже гарды, со стороны лезвия. На мече не было ножен и меч сам похоже видал лучшие времена. Вскоре юноша, подошёл вплотную к заварушке. Он внимательно осмотрел извивающегося на земле  @DrawAndRip(карлика) в странных одеяниях.\n— Всё дивлюсь какой увидительный мир проходил мимо меня всё это время.\n\nПосле чего юноша перевёл взгляд наверх, на ворота.\n— Простите, люди добрые, я странник и эти земли для меня новы. Я слышал в этом городе есть подземелье, в котором якобы находится сокровище. Так уж вышло, что я ищу одно. Не могли бы вы меня пустить за ворота?\n\nЮноша говорил спокойно, видимо это не первое поселение на его пути.",194458,null],[272966,"2026-10-17T15:59:31",9,"*Страж посмотрел на новое лицо что появилось перед ним. Путник выглядел опрятно, такого задерживать за воротами не гоже, особенно под вечер, тем более наёмник.*\n\nЧасовой — Да, мы ждем наемников. — *Он посмотрел на плохую игру человека под дверьми, ему не хотелось пускать Эвкалипта, странный он, но походе прийдется.* — Соберись окаянный, удача на твоей стороне, сейчас открою.",194458,null],[272975,"2026-10-17T16:01:27",9,"*Скрип дерева, на той стороне слышны звуки как убирают тяжелый засов.*\n\nЧасовой — Ух, угораздило же, на ночь заранее закрыть... — *Ворча и стараясь он наконец открыл двери изнутри и сказал:* — Входите.",194458,null],[272983,"2026-10-17T16:04:25",39,"*Эвкалипт поднялся с земли, отряхнулся, и проходя в ворота сказал стражникам*\n\n-Ох.. Спасибо вам большое, хороший господин...хорошей вам ночи, береги вас господь... \n\n*Эвкалипт немного нахмурившись, пробормотал себе под нос едва слышно*\n\n-хах, это все из за стереотипов и предрассудков.. У людей нет чувства стиля, они просто не выкупают моего вайба....",194458,null],[272990,"2026-10-17T16:07:40",39,"*Эвкалипт пошел немного вперед второго человека который тоже шел через ворота* *глаза которые находились у Эвкалипта над ягодицами и шортами все ещё следили за стражниками*",194458,null],[273136,"2026-10-17T17:02:31",29,"Юноша вновь провёл взглядом по коротышке, после чего направился через ворота.\n\n— Эй, постой. Ты ведь тоже пришёл сюда ради подземелья? Ты же не местный, да?\n\nЗолотые глаза осматривали низкого человека. Юноша и сам был не высоким (172 см), но видеть кого-то настолько маленького, но при этом широкого было непривычно. Коротышка был похож больше на дичь, на мускулистого оленёнка, но никак не на охотника. Такое было первое впечатление Маркуса.",272990,null],[273153,"2026-10-17T17:09:48",39,"*Эвкалипт обернулся, окинул взглядом Юношу, и сказал*.\n\n-.. Ну, я вообще просто заблудился... Но насчёт подземелья интересная информация...\n\n\n*Эвкалипт уже полностью обернулся к юноше,и с небольшим смешком, сказал*.\n\n-.. А ты, малец.. такой юный, а уже по подземельям ходишь?.. Тебе сколько вообще лет, а? Тебя мама отпустила по подземельям шастать?",194458,null],[273174,"2026-10-17T17:23:39",29,"Маркус посмотрел вниз на карлика с недоумением на лице. Его золотистые глаза прошлись по карлику сверху вниз, оценивающе.\n\n— Мне... семнадцать... наверное. Я точно не уверен.\n\nМаркус хмыкнул. \n\n— Но можете за меня не волноваться, со мной всё будет хорошо. При мне мой клинок, да и выживать я умею. А вас не затруднит назвать тогда свой возраст?",273153,null],[273194,"2026-10-17T17:31:10",39,"*Эвкалипт говорит, скрестив руки на груди, и сказал ухмыльнувшись одной стороной рта*\n\n-выглядишь лет на 14... и давно тебе 17?\n\n-А мне вообще уже 23.....\n\n*Эвкалипт о чём-то помолчал, подумал*\n\n- .. Хм.. Говоришт есть клинок и умеешь выживать,и  направляешься в подземелье?..\nНе дурно....\n\n\n*Эвкалипт протягивает руку для рукопожатия... Его рука удивительно чистая, для того кто провел два месяца в лесу... Видимо Эвкалипт все же где-то мылся, хотя судя по его запаху мыл он явно только руки, ну может ещё лицо* *(ну, или его руки просто облизывал медведь)*\n\n-Меня Эвкалипт зовут... А ты кем будешь?",194458,null],[273205,"2026-10-17T17:39:20",39,"//",194458,null],[273237,"2026-10-17T17:51:28",29,"Юноша протянул руку в ответ.\n\n— Меня зовут Маркус.\n\nЮноша явно нахмурил брови и был чем-то недоволен.\n\n— Знаете, если вы хотите мериться возрастом, то мои друзья жили гораздо дольше обычной человеческой жизни и пускай их сейчас нет в живых, но разница в шесть лет не делает вас в чём-то лучше меня.",273194,null],[273267,"2026-10-17T18:04:18",39,"*Эвкалипт пожал руку Маркусу, его хватка оказывается очень крепкая.*.\n\n\n-хей, я не имел ввиду что я чем-то лучше, я просто удивился что такой молодой парень уже по подземельям бегает, но раз тебе уже 17, то все нормально..\n\n*Эвкалипт отпустил его руку*\n\n-ты прямо сейчас в подземелье собираешься, или у тебя ещё есть какие-то дела?.. Я бы тоже не против в подземелье пойти, да и к тому же, в одиночку ходить в такие места это то же самое что пойти на верную смерть",194458,null],[273287,"2026-10-17T18:10:29",29,"Маркус оглядел взглядом Эвкалипта ещё раз\n\n— У тебя и имя странное и твоя одежда. Почему ты так одет? Твоя одежда очень откровенна и не похожа ни на что, что я видел ранее.\n\nМаркус провёл взглядом за плечо Эвкалипта.\n\n— Я не против объединиться, если ты всё-таки опытный. Я не очень опытен в бою.",273267,null],[273353,"2026-10-17T18:47:57",9,"//Отвечать что-то будешь, или мне описывать окружение и далее?",273267,null],[273468,"2026-10-17T19:44:19",39,"*Эвкалипт говорит, поставив руки себе на  талию*\n\n\n- .. Хмф... Нормальное у меня имя, красивое, мне нравиться.. \n\n*его тон приобретает оттенок благоговения* \n-И то что мне на мне одето, это н просто одежда! Это произведение искусства!! Этот узор, эти блестящие стразы, этот крой, все прекрасно!!\n\nЭто стильно, модно и молодёжно! У людей просто нет вкуса!\nА на то что она откровенная, мне откровенно все равно ... Люди просто ещё не видели откровенной одежды..\n\n\n*Эвкалипт неловко улыбнулся и вздознул*.\n\n\n-. Ну а насчёт опыта.. Ну.... Так скажем, опыт в бою у меня есть... Меня часто пытались побить когда я выступал в тавернах.. Приходилось часто драться с неблагодарными слушателями без слуха к настоящей музыке..\n\n\n*Эвкалипт оглядывается по сторонам*.\n\n-ух, думаю нам не стоит стоять посреди дороги, хим, интересно, здесь где-то есть отель или таверна...",273287,null],[273601,"2026-10-17T21:18:07",29,"Маркус задумался.\n\n— Хорошо, мне этого достаточно. Мне самому редко удавалось применить свои навыки на практике, я в основном старался избегать опасностей. Я думаю действительно стоит найти ночлег. И найти место где можно поохотиться.\n\nСказал Маркус и пошёл глубже в город за Эвкалиптом, осматриваясь.",273468,null],[274304,"2026-10-18T14:55:40",29,"// Hard @DrawAndRip мы сегодня играем?",194458,null],[274469,"2026-10-18T15:44:23",9,"*Вас встречает двухэтажное здание корчмы. Тут основном сидят свои, работяги и селяне, обычно в таких местах всегда шумно но сейчас посетителей мало, и даже те что есть сидят словно сьели лимон.*\n\n*Вгляды точно угадывали незнакомцев вошедших в небольшое здание. Корчмарь производил впечатление зайеятого человека, протирал кружку, эта кружка была протерта им столько раз что поверхность стала глянцевой и слегка отражающией размытые в ней фигуры.*\n\nКорчмарь — Чего изволите путешественники. По делу или мимоходом в нашех краях. — *Он поправил свои пышные усы и наклонил голову выглядывая из под соломенной шляпы. Будто вторя ситуации меж корчмарём и вами подул сквозняк трепая его длинные волосы.*",194458,null],[274496,"2026-10-18T16:07:16",39,"*Эвкалипт подошёл поближе к стойке, за которой сидел корчмарь, и сказал, пытаясь выглядеть адекватным человеком, видимо поняв что если он этого делать не будет, то здесь будет то же самое, что и с охранниками на входе в деревню*\n\n\n- ну, мы вроде как в подземелье собираемся, и нам нужно где-то переночевать, здесь есть свободные комнаты?\n\n*Эвкалипт окинул взглядом других посетителей, а затем повернулся обратно к Корчмарю*\n\n\n-а чё все  сидят с такими кислыми лицами? Что-то случилось?",194458,null],[274498,"2026-10-18T16:09:28",39,"//я могу играть хоть целый день, просто жду брата, когда он будет.",274304,null],[274499,"2026-10-18T16:09:50",39,"//потому что просто болтать персонажами, это конечно хорошо, но мы же играем",194458,null],[274501,"2026-10-18T16:13:54",9,"Корчмарь — Наёмники? Комната и ужин бесплатно если вы по делу подземелья. — *Он ставит чашку и вздыхает.* — Наплыв монстров, многие заняты а другие уже на том свете. Ещё кобольды поселились в руинах, староста собирает людей чтобы от них избавится пока они не стали еще одной угрозой.\n\n*Он взял кружку начав снова её протирать.*\n\nКорчмарь — Мы не раз обваливали проходы старой крепости, но кто-то постоянно возвращается к ним. Пару лет назад это были гоблины.",274496,null],[274506,"2026-10-18T16:21:16",39,"*Эвкалипт явно обрадовался*\n\n-ох, отлично! Мы тогда остановимся у вас\n\n *Эвкалипт немного задумался*\n\n\n-.. Но насчёт кобольдов не знаю.. Я то не против и на них пойти, люблю тренироваться в реальных боях..так сказать, размять свое тело и дух.. А вот насчет того мальца, не знаю...\n\n*Эвкалипт обернулся к Маркусу*\n\n-. Хей, Маркус, тем кто в подземелье идёт бесплатная комната и ужин., тут ещё , говорят о походе на кобольдов, что думаешь?",194458,null],[274543,"2026-10-18T17:32:09",29,"Маркус осмотрел взглядом присутствующих и вновь повернулся на корчмаря с Эвкалиптом.\n\n— Я не против попробовать помочь этим людям и истребить кобольдов, я не привязан ко времени. Можем пойти и размяться на кобольдах сначала. Заодно, узнаем боевые навыки друг друга.\n\nМаркус проходит к барной стойке и чуть задирает голову на корчмаря.\n\n— Я буду комнату, окна на западной стороне, пожалуйста, если есть. Ужин не нужен, лучше скажите есть ли у вас тут скот. Я бы хотел купить корову или кого-то ещё. Так уж вышло, что по... По моим обычаям я не доверяю еде не приготовленной лично мной.",274501,null],[274635,"2026-10-18T19:18:23",9,"Корчмарь — Комната западнее есть, но она без окна, так уж вышло что стена общая с соседским домом. Пару свечей найдётся. А на счет скота, давеча с этим проблемы. Дичь есть, заяц ещё живой на кухне, пару золотых на стол попрошу положить за него. — *Корямарь ухом даже не повел на странности.*",274543,null],[274642,"2026-10-18T19:21:14",29,"Маркус слегка приподнял бровь, от того, что корчмарь никак не отреагировал на его просьбу, но не стал придавать этому значение.\n\n— Благодарю.\n\nМаркус, пошарился свободной рукой в кармане и достал три золотых.\n\n— Продай мне ещё нож для разделки и бумагу, чтобы я мог завернуть тушу.",274635,null],[274646,"2026-10-18T19:23:50",9,"Корчмарь — Найду. — *Он прячет золото, и уходит в дверь. А потом вы слышите душераздерающий крик. Просто взяв зайца за уши он его притащил прямо к стойке, бумагу и нож положил на столешницу.*\n\nКорчмарь — Вот, только дкржи его как можно крепче, чтобы не убежал.",274642,null],[274647,"2026-10-18T19:24:36",9,"https://youtu.be/wtW6iupD-50?si=YXwcKOdWRzUghZA_",194458,null],[274657,"2026-10-18T19:29:22",29,"Маркус, крепкой хваткой взял зайца свободной рукой и поставил меч на пол. После чего заткнул нож за пояс и протянул руку, ожидая ключ.\n\n— Я разделаю его в комнате, обещаю, что буду аккуратен и после меня не придётся отмывать комнату.",274646,null],[274661,"2026-10-18T19:31:45",39,"*Эвкалипт говорит, с улыбкой*\n\n-а где ты его готовить будешь?\nИли ты прям так его? \n\n*Эвкалипт немного посмеялся над своей же шуткой* \n*подойдя к Маркусу, Эвкалипт глянул на зайца*\n\n-мда... Видимо с животными здесь действительно проблемы....",194458,null],[274662,"2026-10-18T19:32:14",9,"Корчмарь — Ключа нет парень. Я покажу твою комнату. — *Он ведет вас к двери за которой лесница наверх, а там влсемь комнат, он показывает на три.* — Эти свободны, вон та что без окна. Внутри есть засов если печешься о своей бегопасности, позже занесу парочку свечей.",274657,null],[274663,"2026-10-18T19:32:30",39,"//ща, поменяю",194458,null],[274664,"2026-10-18T19:33:21",9,"Корчмарь — Завтра скажу старосте что наёмники пришли. Он вам даст хорошего провожатого к месту работы.",194458,null],[274668,"2026-10-18T19:36:30",39,"*Эвкалипт последовал за Корчмарем, немного зевая, потягиваясь*\n\n-ух, наконец-то посплю не в какой-то холодной яме на твёрдой земле, слушая соперние медведя, и шугаясь каждого шороха в темноте леса... \n\n\n-кстати, а тут где-то есть где можно помыться?",194458,null],[274674,"2026-10-18T19:39:08",9,"Корчмарь — Снаружи ща углом дождевой боченок. Возле него черпак, все умываются там. Если нужно корыто воды нагреть — за два серебрянника сделаю.",274668,null],[274680,"2026-10-18T19:43:01",39,"-это не просто нужно, это жизненно необходимо \n\n*Эвкалипт достаёт мешочек с монетами, достаёт оттуда два серебрянника и даёт их Кочмарю*\n\n-я был бы очень признателен, возможность помыться сделает меня наверное, самым счастливым человеком в этом посёлке",274674,null],[274685,"2026-10-18T19:44:09",39,"//монеты я если что списала только что  у себя в анкете",194458,null],[274687,"2026-10-18T19:44:49",9,"Корчмарь — Хорошо, я постучу через пол часа и принесу принадлежности.",274680,null],[274688,"2026-10-18T19:45:02",9,"//Да, из инвентаря, все правильно)",274685,null],[274689,"2026-10-18T19:45:12",29,"Маркус кивает и проходит к двери в комнату.\n\n— Эвкалипт, я сейчас заготовлю зайца на потом и пойду охотиться на кобольдов, если хочешь помочь, я бы не отказался.\n\nПосле этого Маркус заходит внутрь и запирает засов двери в свою комнату.\nМаркус осматривает комнату и располагается сидя на полу. Он кладёт рядом меч и стелит бумагу перед собой. После чего берёт бедного кролика в две руки и подносит к своему рту. Маркус впивается в его шею своими клыками и начинает жадно пить. Через минуты две, кролик высыхает и Маркус начинает его разделывать, положив на бумагу. Сначала шкура, потом мясо и внутренности, разделив всё и свернув по отдельности, Маркус наконец выходит из комнаты.",274680,null],[274694,"2026-10-18T19:47:38",39,"*Эвкалипт, который тоже как раз собирался зайти в свою комнату, закончив разговор с Корчмарем, говорит*..\n\n\n- Ну, я наверное сначала помоюсь, а потом присоединюсь, а то я наверное воняю хуже чем те зомби которые были при входе в деревню..",194458,null],[274696,"2026-10-18T19:48:55",9,"*Вскоре тебя окликнули и привели в отдельное помещение. Что-то похожее на баньку, но там пусто, похоже её не часто топят. Новот несколько ведер с водой, черпак и таз это кажется тебе.*",274694,null],[274699,"2026-10-18T19:52:04",9,"*Уже достаточно темно, в таверненикого нет. Только корчмарь на месте.*",274689,null],[274702,"2026-10-18T19:54:28",29,"Маркус спускается вниз, держа в одной руке свой клинок, всё так же за основание лезвия. А в другой руке держит мешочек с кроликом. Выйдя наружу, юноша становиться у входа в таверну и ожидает Эвкалипта.",274699,null],[274705,"2026-10-18T19:55:08",39,"*Эвкалипт с нетерпением снял с себя одежду и начал мыться*\n\n-ох боже! Какое блаженство... Ну что за рай!!! О, всевышний, как прекрасно что человечество придумало мыться!\n\n*после того как Эвкалипт помыл себя, он протёр свою сумочку, а также немного постирал свою одежду..запасной одежды у Эвкалипта не было, так что ему пришлось одеть одежду обратно, хоть она и была мокрая.. Хотя, его одежда из за материала быстро сохнет, да и он бывал в ситуациях и похуже, так что, закончив все свои дела, Эвкалипт взял вещи, и пошел искать Маркуса*",274696,null],[274715,"2026-10-18T20:01:53",9,"*По небу сиелятся редкие черные облака, видны звёзды. Уходящий месяц прячется за крышами невысоких зданий.*",274702,null],[274717,"2026-10-18T20:04:12",29,"Маркус стоял около входа в таверну и наслаждался тишиной мирностью момента. Пускай он и знал, что эта деревня далека от состояния мира, но то, что он видел сейчас успокаивало Маркуса и даже внушало надежду",194458,null],[274721,"2026-10-18T20:07:21",39,"*Эвкалипт вышел на улицу, он довольно, с улыбкой, вдохнул свежий, ночной воздух*\n\n-боже.. Как же хорошо дышать не запахом болотной тины и кислого пота... Как хорошо что я больше не воняю как бездомная собака, и не выгляжу как болотный монстр обвалявшиеся в грязи... \n\n\n*Эвкалипт,увидел Маркуса, подошёл к нему, эвкалипт был явно в отличном настроении, и видимо ещё и закалён, ибо не похоже чтобы ему было холодно, ну или Эвкалипт просто не подаёт виду*\n\n-йо, ну, идём, да? Ты уже все сделал что хотел?",194458,null],[274722,"2026-10-18T20:08:11",9,"//Кто нибудь кинте на анализ, сл 10 😏👌",194458,null],[274728,"2026-10-18T20:10:29",39,"//@SheoSheol ты кидай, у тебя там вроде +",194458,null],[274730,"2026-10-18T20:11:02",29,"// окей, щас кину",194458,null],[274731,"2026-10-18T20:11:16",29,"/roll@roll_bot",194458,null],[274733,"2026-10-18T20:11:47",29,"// ну... Не совсем кинулось так как я хотел, но я не жалуюсь...",194458,null],[274734,"2026-10-18T20:12:16",29,"// там ещё +2",194458,null],[274760,"2026-10-18T20:26:23",29,"Маркус перестал облокачиваться на стену таверны и повернул голову в сторону Эвкалипта. Юноше было не очень привычно постоянно смотреть вниз, ведь обычно это Маркус был тем, на кого смотрят сверху вниз.\n\n— Да, думаю выдвинемся прямо сейчас, чтобы не терять времени.\n\nМаркус приложил к груди Эвкалипта мешочек.\n\n— Вот, твоя часть кролика, я всё разделал и мне оказалось много, поэтому можешь забрать остальное.\n\nМаркус ещё раз осмотрел Эвкалипта.\n\n— И ты не спросишь почему мы делаем всё это ночью? Я конечно доволен, что ты держишь своё любопытство в узде, но в этом нет ничего сверхъестественного. В пустыне солнце Губительны и смертельно, поэтому я привык с детства передвигаться ночью, пока температура не очень низкая.",274721,null],[274762,"2026-10-18T20:29:31",9,"*Почти полночь, на улице особо никого не видно. Вы не знаете куда идти. Нужно поговорить с ответственным о вознаграждении и прочее.*",274732,null],[274766,"2026-10-18T20:33:24",29,"Маркус осмотрелся по сторонам, заприметив самый приличный дом и показал на него пальцем.\n\n— Надо бы спросить у старосты по поводу кобольдов и подземелья.\n\nСказал юноша и отправился в сторону дома, пытать удачу, что именно в богатом доме окажется староста деревни.",274721,null],[274771,"2026-10-18T20:37:02",9,"/roll 1d20 удача",194458,null],[274775,"2026-10-18T20:38:15",9,"*Ты постучался в дом что казался вполне приличным, никто не отвечает. Где то по улочке идут несколько людей с свечой в фонаре, громко болтают.*",274766,null],[274777,"2026-10-18T20:40:06",29,"Маркус быстрым шагом подошёл к людям.\n\n— Прошу прощения, добрые люди. Не могли бы вы мне сказать где живёт староста. Я бы хотел узнать о местонахождении руин, чтобы поохотиться на кобольдов, прежде чем спуститься в подземелье.",274775,null],[274797,"2026-10-18T21:01:22",39,"*Эвкалипт конечно был удивлён, но взял мешочек*\n\n-о, спасибо... Не буду отказываться, все что можно сожрать, выкидывать нельзя\n\n*Эвкалипт положил мешочек себе в сумочку, из сумочки достал связку с сушеными частичками осьминога, и пошел рядом с Маркусом, жуя осьминога*",274760,null],[275033,"2026-10-19T11:36:39",9,"Прохожий — Староста? Дык вот его дом. — *Маркусу показали на дом, что был буквально через дорогу напротив того в который он стучался.*",274777,null],[275035,"2026-10-19T11:38:04",29,"— Благодарю, добрые люди.\n\nМаркус слегка кивнул головой, попрощавшись с ними и направился к дому старосты, после чего постучал в дверь три раза.",275033,null],[275040,"2026-10-19T11:49:37",9,"*В доме кажется горела свеча и тебе открыл громила к большими руками, выше не на голову, на целых две.*\n\nСтароста — Вечер добрый. По какому делу в столь поздний час. — *Он держал подсвечник в одной руке, а второй погладил седевшую бороду, слегка прищурившсь и наклонившись, пытаясь разглядеть ваши фигуры в тусклом свете метающегося под лёгким ветром огня свечи.*",275035,null],[275041,"2026-10-19T11:51:52",29,"— Прошу прощения, что тревожу так поздно. Но лучшего времени для охоты и не найти. Я пришёл в деревню так как слышал, что тут есть подземелье, в котором находится сокровище, но в таверне узнал, что у вас ещё есть и проблема с кобольдами. Могу ли я получить более подробную информацию о местонахождении и кобольдов и подземелья?\n\nМаркус говорил вежливо и размеренно.",275040,null],[275046,"2026-10-19T11:59:24",9,"Староста — Наемники? Доволе поздний час. Подождите минуту. — *Он зашёл в дом и вскоре вернулся со свежим письмом.* — Отдадите страже на северных воротах, он даст наводку. Ночью идти по лесам не рекомендую.\n\n*Староста хотел уже уходить и тут вспомнив кое что добавил:*\n\nСтароста — Сборы за устранение кобольдов составляют 230 золотых. Охотники насчитали около трех дюжин мелких, чешуйчатых лиц, будьте на чеку.",275041,null],[275059,"2026-10-19T12:09:03",39,"-Да что там те леса, я там два месяца ходил и спал, хах, может и медведя с которым я там был встретим\n\n*Эвкалипт достал из своей сумочки какие-то листья, и начал их жевать*\n\n\n-м.. А за устранение кобольдов ещё и деньги платят? Отлично....",194458,null],[275074,"2026-10-19T12:26:25",29,"— Тогда...\n\nМаркус обернулся в сторону Эвкалипта.\n\n— Думаю нам не стоит терять время. Сейчас разберёмся с кобольдами, а потом отправимся в подземелье.\n\nМаркус, не сильно ускоряя темп, чтобы Эвкалипт не отставал, направился к северным воротам.",275046,null],[275077,"2026-10-19T12:31:05",9,"*Эти врата так же стояли закрытыми. На стенах стояли четверо стражей кажется развлекались.*\n\nЧасовой — Смотри, он подходит ближе, еще ближе, и. — *Он держал длинный лук натянутым когда отпустил тятиву. Под одобрительные возгласы товарищей раздался скулёж за стеной, кадется он в кого-то попал.*\n\n*Они совершенно не обращают на вас внимания, занятые своими делами.*",194458,null],[275078,"2026-10-19T12:34:33",29,"— Эй, добры люди. В кого стреляете?\n\nПрокричал Маркус, приложив свободную руку ко рту, чтобы усилить звук его голоса.\n\n— У нас тут бумага от старосты, сказал вы поможете найти где кобольды за сели, да подземелье обнаружить.",275077,null],[275079,"2026-10-19T12:37:08",9,"*Они посмотрели на вас. Тот кто стрелял вернулся а делу.*\n\nЛучник — Степан, проверь сходи. — *Он натянул лук и целится стоит в кого-то.*\n\n*Один из стражей спустился, почитал бумадку в свете фонаря.*\n\nСтепан — Ага, ну. Выходить наружу в ночь гиблое дело.",275078,null],[275084,"2026-10-19T12:40:56",39,"*Эвкалипт посмотрев на Маркуса*\n\n-ну, мне то все равно, сдохну так здохну.. Зато будет весело..\n\n-а вот ты решай когда пойдём\n\n*Эвкалипт положил оставшиеся сушеные листья обратно в сумочку*  *и взчл в руки свою металическую балалайку, видимо готовясь идти*",194458,null],[275085,"2026-10-19T12:43:34",9,"Степан — Эх, пошли покажу. — *Он идет на стену по лестнице и приглашает вас за собой.*",275084,null],[275086,"2026-10-19T12:44:41",39,"*Эвкалипт немного замешкался конечно, но пошел вместе со стражником, настороженно*",194458,null],[275091,"2026-10-19T12:48:59",9,"Степан — Смотрите. — *Он переставляет заслонку и в темноте, на краю направленного луча со стены вы видите восемь пар очей светящихся из тьмы.* — Волки.\n\n*Примерно на расстоянии 400 футов лежит несколько пристреленных на краю дороги, там что-то есть за чем они хотят прийти, и шастают неподалеку.*\n\nСтепан — Уорик разлил ведро с кровью и потроха, они шаснули на приманку и мы их отстреливаем. Животина давеча голодная пошла, лезет даже если опасно. — *Обьяснил он в чем дело. Сама стража и стала причиной этой ситуации.*",275086,null],[275094,"2026-10-19T12:51:24",39,"*Эвкалипт усмехнулся*\n\n- Просто волки?, ну незнаю даже\n\n*Эвкалипт окликнул Маркуса*\n\n- Хей, Маркус, собак не боишься?? \n\n\n\n\n-как думаешь, с волками справимся? Там их наверное куча, лезть будут постоянно",194458,null],[275110,"2026-10-19T13:08:53",29,"— Волки не должны представлять большой угрозы, пока мы сохраняем бдительность.\n\nКрикнул в ответ Маркус.\n\n— Лучше закончить с этим побыстрее пока темно и мы сможем скрыться от чужих глаз. Разберёмся с волками у ворот, а дальше надо будет идти осторожно, скрытно.",275094,null],[275113,"2026-10-19T13:15:15",9,"Степан — Как знаете. О руинах, они северовосточнее... — *Непного расказав как найти нужное место, он взял лестницу и спустил её под стеной ворот.* — Слезайте так, в ночь ворота я не открою.\n\n*Свист стрелы. Лучник выпустил еще одну, но на этот раз промахнулся.*",275110,null],[275117,"2026-10-19T13:16:44",39,"*Эвкалипт покрепче сжал балалайку, и на всякий случай в другую руку взял кинджал*\n\n-так, ну что, пошли...",194458,null],[275122,"2026-10-19T13:18:48",29,"Маркус взошёл на ворота и начал слезать по лестнице вниз.\n\n— Пошли, Эвкалипт, только смотри в оба, если не видно ничего в темноте, то держись рядом со мной, у меня зрение получше.\n\nНаконец достигнув земли, Маркус перехватил клинок и взялся правой рукой за гарду длинного меча, готовясь к встрече с врагами.",275113,null],[275240,"2026-10-19T15:36:38",39,"*Эвкалипт спустился за  Маркусом, не отводя взгляд от волков*\n\n-хорошо, я буду очень внимательным, буду смотреть во все четыре глаза.... По всем сторонам \n\n\n*Эвкалипт немного подумал*\n\n\n-чисто технически... Если я попробую с ними договориться....они вроде пока не нападают",194458,null],[275242,"2026-10-19T15:39:38",39,"-волкам же тоже наверняка кобольды мешают.. Может они помогут",194458,null],[275251,"2026-10-19T15:50:36",29,"Маркус не отводит взгляда от тьмы, где обитают волки, но всё же отвечает.\n\n— Ты умеешь разговаривать с животными? Как? Разве это не просто звери?",275240,null],[275258,"2026-10-19T15:56:18",39,"*Эвкалипт вздохнул*\n\n\n-я разговаривал с крысами, и облезлыми собаками на помойках.. Да и с медведем как-то подружился.\n\n-думаешь я не справлюсь с какими-то волками?\n\n-мне просто нужно 10 минут чтобы, так сказать, открыть свою чарку, настроиться на разговор",194458,null],[275269,"2026-10-19T16:02:53",9,"*Из тьмы, достаточно далеко (400+ футов) раздалось рычание. Отражение хищных глаз смотрит на вас, никто не подходит.*\n\n*Зверь знакомый с человеком хитёр, они понимают угрозу со стены.*\n\n*Голодные пасти затихли, огни глаз потухли. Вас ждут из темноты, готовя засаду, достаточно лишь уйти дальше положенного.*",194458,null],[275273,"2026-10-19T16:04:42",29,"Маркус повернул голову в сторону Эвкалипта, смотря на него удивлёнными глазами.\n\n— Что же тебе удалось пережить? Не представляю, что же, если ты всё ещё хочешь поговорить это твой шанс, пока они не решаются напасть.",275269,null],[275280,"2026-10-19T16:07:45",39,"*Эвкалипт встаёт в позу, ноги на ширине плеч, одну руку он вытягивает впередд и начинает водить кругами ею, а вторую руку он ложит на предплечье той вытянутой руки, и начинает говорить, очень серёзно, даже как-то заговорчески*",194458,null],[275282,"2026-10-19T16:07:50",39,"-Колдуй баба, колдуй дед, колдуй серенький медвед",194458,null],[275283,"2026-10-19T16:07:58",39,"-Колдуй серенький волчек, не кусай нас за бочек",194458,null],[275284,"2026-10-19T16:08:06",39,"-Научусь вас понимать, чтоб не стали нас вы жрать",194458,null],[275286,"2026-10-19T16:08:14",39,"-Волк и волку брат, ауф",194458,null],[275288,"2026-10-19T16:08:29",39,"-волк не тот кто волк, а тот кто волк",194458,null],[275290,"2026-10-19T16:08:46",39,"-волк, волку брат, а брат брату, брат",194458,null],[275292,"2026-10-19T16:09:10",39,"-волк волку волк, а волку волк волк",194458,null],[275294,"2026-10-19T16:09:33",39,"-брат, помни брат,  волк, волку брат",194458,null],[275297,"2026-10-19T16:11:23",39,"-Каждый волк, это волк, а если волк это волк, значит волк это волк",194458,null],[275303,"2026-10-19T16:13:27",39,"-если волк вместе с волком, то вместе они волки",194458,null],[275311,"2026-10-19T16:15:11",39,"-волк не один, один это цифра, а не волк",194458,null],[275315,"2026-10-19T16:15:49",39,"-Не какждый тот кто не тот, и не каждый тот кто не кто",194458,null],[275316,"2026-10-19T16:16:34",39,"-Волк волк когда он волк, а когда он не волк, он не волк",194458,null],[275317,"2026-10-19T16:17:00",39,"-если волки рядом, то волки рядом",194458,null],[275320,"2026-10-19T16:17:36",39,"-не важно кто волк, важно кто волк",194458,null],[275334,"2026-10-19T16:20:53",39,"-Запомни, брат: волк не спит, волк спит, но если волк спит, то волк не спит",194458,null],[275345,"2026-10-19T16:22:09",39,"-Упал — вставай,Встал — упай.",194458,null],[275347,"2026-10-19T16:22:21",39,"-Упай — чокопай,Не суди, не гуди.",194458,null],[275349,"2026-10-19T16:22:32",39,"-Не будай вада буди, Дабуди дабудай!",194458,null],[275379,"2026-10-19T16:30:19",9,"//Это писец",194458,null],[275382,"2026-10-19T16:30:41",39,"//ты сказал любое",194458,null],[275397,"2026-10-19T16:34:15",9,"*Даже стражаначала странно поглядывать.*\n\nСтепан шепчет кому-то — Он не толкьо выглядит как немного того и сам этого.\n\n*Эвкалипт медленно погружался испытывая ощущения некоего транса в своих свловах. Тихое рычание стало шёпотом, а шёпот сдовами. Если сосредоточится, можно было понять обрывки слов.*\n\nВолки — Тут... тихо... давай, подойди... — *Звучит угрожающе.*",194458,null],[275416,"2026-10-19T16:37:02",39,"*Эвкалипт, подошёл к волкам поближе*\n\n\n-ребят , мы тут кобольдов порешать собираемся.. Они вам самим случайно не мешают?\n\n-мы можем пожалуйста пройти?.. Или может и с нами пойдёте?",194458,null],[275422,"2026-10-19T16:37:36",39,"//если что разговоры волков же только я слышу",194458,null],[275459,"2026-10-19T16:44:20",9,"*Рычачание притихли, Эвкалип со своим опытом мог сказать что они малость оху... удивились.*\n\nВолк — Кто ты. Ты не брат, ты не стоишь на четырёх ногах, жалкая двуногая собака. — *На краю безопасной зоны сверкнули мудрые глаза, в них отражался свет огней за темной фигурой Эвкалипта.*",194458,null],[275467,"2026-10-19T16:46:08",39,"*Эвкалипт говорит*\n\n\n-волк ведь не тот кто волк, а тот кто волк\n\n-волки это волки, и брат который брат может быть волком даже если брат не волк.\n\n-душа волка, это душа волка\n\n-волк может быть волком в душе",194458,null],[275474,"2026-10-19T16:48:01",39,"-мы пришли сюда чтобы победить кобольдов, они ведь и вам наверняка мешают, дичи и так мало, а они ведь тоже охотяться",194458,null],[275475,"2026-10-19T16:48:04",29,"Маркус стоит позади Эвкалипта и крайне удивлённо смотрит на последнего, пытаясь осмыслить то, что сейчас происходит. Не сделал ли он ошибку объединившись с этим карликом и быть может, если волки растерзают его бедное тело, то так будет даже лучше, бедный умолишённый карлик не будет больше придаваться агонии существования. Тёмные и противоречивые мысли посещали Маркуса.",275467,null],[275498,"2026-10-19T16:54:17",9,"//Кинь на выступление или убеждение",275467,null],[275505,"2026-10-19T16:56:57",39,"/roll 1d20+2   убеждение",194458,null],[275516,"2026-10-19T16:59:22",9,"Старый волк — Смысл есть в твоих словах. Иди. — *Он завыл и волки разбежались, вскоре свет отраженья глаз исчез. Вслед за ветром. Наступила тишина.*",275506,null],[275521,"2026-10-19T17:01:36",39,"*Эвкалипт обернулся к Маркусу, выдохнул*\n\n-ну, все, я договорился чтобы они нас не трогали, теперь можно идти, по идее на нас волки нападать не будут\n\n\n-жаль конечно что помочь они нам не захотели, но что ж.. И так уже хорошо, от них хотя бы отбиваться не придётся",194458,null],[275528,"2026-10-19T17:03:08",29,"Маркус удивлённо посмотрел на Эвкалипта.\n\n— Так ты правда говорил с ними, а не сошёл с ума?\n\nМаркус, быстро приходит в себя.\n\n— Ну... Что же, тогда отправляемся в сторону кобольдов. Хорошо, что мы сэкономили время.",275521,null],[275533,"2026-10-19T17:05:50",39,"*Эвкалипт говорит возмущенно*\n\n\n-я что, похож на сумашедшего?!  Конечно я правда с ними говорил! Если бы я был сумасшедшим, меня бы ещё в лесу медведь бы загрыз, а я ведь с ним три недели по лесу бродил\n\n\n*Эвкалипт начинает идти, и немного раздраженно говорит*\n\n-да, да, пошли... В какой там стороне кобольды находяться?",194458,null],[275550,"2026-10-19T17:07:30",29,"Маркус слегка винова-то опускает голову.\n\n— Прости, я не хотел тебя оскорбить. Конечно, никто сейчас точно не будет сомневаться в твоих способностях и то, что ты можешь договориться с животными. А в сторону развалин вроде туда...",275533,null],[275622,"2026-10-19T17:33:48",9,"*Завывание вдали, перед вами дорога, лес, а после тропа. За вехушками деревьев виднеется тень руин, старых стен частично освещенных луной.*\n\n*Эвкалипту ночью ничего не видно.*\n\n//Насталр время рисовать карту",194458,null],[275644,"2026-10-19T17:40:52",29,"// можем завтра продолжить, если тебе тяжко",275622,null],[275691,"2026-10-19T17:58:07",9,"*Стены крепости вощвышаются за деревьями. Маркус как немногощрачий в темноте увидел кобольда сидящего на стене, он кадется жевал что-то и смотрел. Часовой, он вас пока не заметил силя достаточно далеко.* \n\n//Синий — Маркус. Фиолетовый — Эвкалипт. Коричневые круги — стволы деревьев. Зеленое полупрозрачное — густые кусты. Полупрозрачное коричневое — рытвины и ямы. Красная точка кобрльт которого вы заметили",275688,null],[275693,"2026-10-19T18:00:30",9,"//Пока отписываю по настроению, тут ваншот, кое как доведу 100%",275644,null],[275694,"2026-10-19T18:01:37",39,"/шо это за херня",275688,null],[275696,"2026-10-19T18:01:52",39,"/ща приду к тебе",194458,null],[275699,"2026-10-19T18:04:16",29,"Маркус почти вплотную приближается к Эвкалипт и кладёт свой указательный палец себе по центру губ, обозначая, чтобы он вёл себя тихо. После чего, юноша пригибается и медленно двигается ближе к кобольду, скрываясь от одного куста, к другому.",275691,null],[275724,"2026-10-19T19:36:39",39,"//-Синий 🔵 — Маркус. \n\n-Фиолетовый🟣 — Эвкалипт.\n\n- Коричневые круги 🟤🎄— стволы деревьев. \n\nЗеленое 🟩— густые кусты.\n\nКоричневые ямы  🟫— рытвины и ямы с мусором и всякими костями и тд. \n\n- Красная точка🔴- кобрльт которого вы заметили\n\n-кирпичи 🧱- стена",194458,null],[275725,"2026-10-19T19:36:40",39,"//так получше",194458,null],[275730,"2026-10-19T19:44:52",39,"*Эвкалипт конечно нихера особо не понял, почему маркус так крадётся, однако на всякий случай молча тоже пригнулся и прячась за всем что только попадётся, пошел за Маркусом*",194458,null],[275763,"2026-10-19T20:18:43",9,"//Вы в темноте, от обоих скрыт, возьмем среднее если вместе движетесь",194458,null],[275764,"2026-10-19T20:22:11",39,"/roll 1d20+2   скрытность",194458,null],[275766,"2026-10-19T20:24:19",29,"/roll 1d20+6",194458,null],[275770,"2026-10-19T20:28:47",29,"// мат ожидание: (15+19)/2=17",194458,null],[275774,"2026-10-19T20:29:40",39,"//каждый раз когда кидаю ролл, молюсь",194458,null],[275775,"2026-10-19T20:29:47",29,"// Я спать, отвечу завтра рано утром, если будет на что отвечать",194458,null],[276006,"2026-10-19T23:18:37",9,"*Лупоглазый кобольд сидит на стене (высотою стена 25 футов), его глаза смотрят в разные стороны. Он что-то ест, занят вот и не видит.*",194458,null],[276034,"2026-10-20T02:42:26",29,"Маркус, аккуратно берёт меч в зубы и начинает карабкаться по отвесной стене, якобы хватаясь за старые выступающие кирпичи. Он мог бы это делать даже без рук, просто пройдясь по стене, но не хотел привлекать лишнее внимание Эвкалипта к своей персоне.\n\nПосле того как Маркус взобрался на стену, он взяв клинок в руку, резко сократил дистанцию и нанёс удар мечом.\n(30 футов передвижения должно хватить + атака)",276006,null],[276035,"2026-10-20T02:43:00",29,"/roll 1d20+4 атака длинным мечом",194458,null],[276037,"2026-10-20T02:43:51",29,"// Предположу, что я попал и сразу урон кину",194458,null],[276038,"2026-10-20T02:44:15",29,"/roll 1d8+4",194458,null],[276042,"2026-10-20T07:09:31",9,"//Из засады удары с преимуществом почти всегда",194458,null],[276043,"2026-10-20T07:10:44",9,"//Тоесть имеем преим на попадание обычно, если помехи нет.",276036,null],[276050,"2026-10-20T08:06:27",29,"// окей, ну я кину ещё раз вдруг крит",276043,null],[276051,"2026-10-20T08:08:24",29,"/roll 1d20+6",194458,null],[276053,"2026-10-20T08:08:45",29,"// а ещё я забыл, что там бм идёт в сумме на атаку, так как я умею, так что там 22 в первом броске",194458,null],[276054,"2026-10-20T08:19:05",29,"// Я думал у него там язык торчит, а это заострёееая в клюв морда. XD",276006,null],[276056,"2026-10-20T08:36:51",39,"//я тоже",276054,null],[276057,"2026-10-20T08:39:14",39,"*Эвкалипт был немного в шоке от того что такой юный парень был таким смелым, эвкалипт, предложил что, видимо, этот парень не впервые делает что-то подобное*\n\n*эвкалипт, не смотря на свое телосложение, еле как забрался на эту стену,когда Маркус уже нанёс удар*",276034,null],[276058,"2026-10-20T08:41:20",39,"*Эвкалипт говорит тихо*\n\n-ох, ты как вообще так быстро взобрался?\n\n\n*Эвкалипт взял свою балалайку и потыкал ею в кобольда, который (я предполагаю) уже лежал на земле*\n\n-помер, да?",194458,null],[276061,"2026-10-20T08:52:08",9,"*Вы прикончили часового. Он умер занимаясь любимым делом, кушая.*",194458,null],[276063,"2026-10-20T08:53:43",9,"*За стенами тихо. Возможно где-то еще прячутся кобольды. Уцелевшая башня на другой стене выглядит достаточно привлекательно для дозорного.*",194458,null],[276067,"2026-10-20T09:05:56",39,"//звучит как-то грустно, его аж жалко",276061,null],[276075,"2026-10-20T09:09:14",39,"*Эвкалипт говорит, оглядываясь по сторонам*\n\n-хорошо что нас ещё не заметили, мы же не знаем сколько их  может их здесь целая орава",194458,null],[276076,"2026-10-20T09:10:57",39,"-хотя, там вроде дальше  ещё какое-то строение.... Не особо могу разглядеть из за темноты... То-ли ещё какая-то стена... То-ли ещё что-то",194458,null],[276080,"2026-10-20T09:19:11",39,"*Эвкалипт взял в руку также кинджал, на его лице расцвета какая-то немного сумашедшая ухмылка*\n\n\n-Ну что ,раз уж они хотят поиграть в прятки..... Пойдем их искать",194458,null],[276087,"2026-10-20T09:31:06",39,"*начинает пытаться всматриваться в темноту, чтобы возможно кого-то заметить*\n\n-нужно вести себя тихо.",194458,null],[276111,"2026-10-20T09:47:23",29,"Маркус осматривал дозорную башню.\n\n— Нам же говорили, их две три дюжины, это от двадцати четырёх, до тридцати шести кобольдов. Если сможем большую часть перерезать пока спят, то даже не получим серьёзных ран.\n\nМаркус аккуратно спустился со стены и скрытно пошёл в сторону башни",276075,null],[276123,"2026-10-20T10:13:34",9,"//Я вас отпускаю @SheoSheol и @DrawAndRip . Нет вобще настроения. 300 опыта и 50 золотых каждому, простите за плохой опыт 💔, не могу держать вас просто.",194458,null],[276124,"2026-10-20T10:13:40",9,"ХХХХХХХХХХХХХХХХХХХХ",194458,null],[276125,"2026-10-20T10:14:38",39,"//бля",194458,null],[276126,"2026-10-20T10:15:16",39,"//сам меня сюда значит затащил, и сам же и слился",194458,null],[276127,"2026-10-20T10:15:26",39,"//я так и знала что так будет",194458,null],[276128,"2026-10-20T10:24:46",39,"//а так хотелось спалится, чтобы на нас побежала толпа, а Эвкалипт заорал бы, побежал в ответ и орал размахивая плеткой и балалайкой во все сторони, говоря\n-Бегите, я конченый!",194458,null],[276129,"2026-10-20T10:36:40",31,"классика. Подстркаткль бежит первым",276126,null]]);
